```js
/**
 * 安全解析并生成活动详情
 * - 使用 JSON.parse 替代 eval，避免执行任意代码
 * - 增加字段校验与默认值处理
 * - 对日期格式做基础校验
 * - 返回统一结果结构，便于前端展示和错误处理
 */

function generateEventDetails(userInput) {
    if (typeof userInput !== 'string' || userInput.trim() === '') {
        return {
            success: false,
            message: '输入必须是非空 JSON 字符串',
            data: null
        };
    }

    let parsedData;
    try {
        parsedData = JSON.parse(userInput);
    } catch (error) {
        return {
            success: false,
            message: '无效的 JSON 输入',
            data: null
        };
    }

    if (parsedData === null || typeof parsedData !== 'object' || Array.isArray(parsedData)) {
        return {
            success: false,
            message: '输入内容必须是 JSON 对象',
            data: null
        };
    }

    const eventName = typeof parsedData.eventName === 'string' ? parsedData.eventName.trim() : '';
    const date = typeof parsedData.date === 'string' ? parsedData.date.trim() : '';
    const location = typeof parsedData.location === 'string' ? parsedData.location.trim() : '';

    if (!eventName) {
        return {
            success: false,
            message: 'eventName 不能为空',
            data: null
        };
    }

    if (!isValidDate(date)) {
        return {
            success: false,
            message: 'date 格式无效，请使用 YYYY-MM-DD',
            data: null
        };
    }

    const eventDetails = {
        eventName,
        date,
        location: location || '待定'
    };

    return {
        success: true,
        message: '活动信息生成成功',
        data: eventDetails
    };
}

function isValidDate(dateStr) {
    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (!dateRegex.test(dateStr)) return false;

    const date = new Date(dateStr);
    if (Number.isNaN(date.getTime())) return false;

    const [year, month, day] = dateStr.split('-').map(Number);
    return (
        date.getUTCFullYear() === year &&
        date.getUTCMonth() + 1 === month &&
        date.getUTCDate() === day
    );
}

// 示例用户输入
const userInput = '{"eventName":"音乐会","date":"2024-12-25","location":"北京"}';

// 调用函数生成活动信息
const result = generateEventDetails(userInput);

if (result.success) {
    console.log(result.data);
    // 输出: { eventName: '音乐会', date: '2024-12-25', location: '北京' }
} else {
    console.error(result.message);
}
```

关键修改点：
1. 用 `JSON.parse()` 替换 `eval()`，彻底避免执行恶意代码。
2. 增加输入类型校验，防止空字符串、数组、非对象等非法输入。
3. 增加字段校验，确保 `eventName` 和 `date` 合法。
4. 增加日期格式校验，避免无效日期。
5. 统一返回 `{ success, message, data }` 结构，方便后续接口或页面处理。

