```js
/**
 * 课程筛选示例
 * 优化点：
 * 1. 移除未确认许可证的外部依赖，避免合规风险
 * 2. 封装筛选逻辑，提升可维护性和可复用性
 * 3. 增加参数校验，避免异常输入导致结果错误
 * 4. 支持大小写不敏感匹配
 * 5. 输出更清晰的展示信息
 */

// 用户选择的筛选条件
const selectedCategory = 'Programming';
const selectedDifficulty = 'Intermediate';

// 假设这个数据从服务器加载
const allCourses = [
  { title: 'JavaScript Basics', category: 'Programming', difficulty: 'Beginner' },
  { title: 'Advanced JavaScript', category: 'Programming', difficulty: 'Intermediate' },
  { title: 'Python for Beginners', category: 'Programming', difficulty: 'Beginner' },
  { title: 'UI Design Fundamentals', category: 'Design', difficulty: 'Beginner' }
];

/**
 * 标准化字符串，避免大小写和空格影响匹配
 * @param {string} value
 * @returns {string}
 */
function normalize(value) {
  return typeof value === 'string' ? value.trim().toLowerCase() : '';
}

/**
 * 根据类别和难度筛选课程
 * @param {Array} courses
 * @param {Object} filters
 * @param {string} [filters.category]
 * @param {string} [filters.difficulty]
 * @returns {Array}
 */
function filterCourses(courses, { category, difficulty } = {}) {
  if (!Array.isArray(courses)) {
    throw new TypeError('courses 必须是数组');
  }

  const normalizedCategory = normalize(category);
  const normalizedDifficulty = normalize(difficulty);

  return courses.filter((course) => {
    if (!course || typeof course !== 'object') return false;

    const courseCategory = normalize(course.category);
    const courseDifficulty = normalize(course.difficulty);

    const matchCategory =
      !normalizedCategory || courseCategory === normalizedCategory;

    const matchDifficulty =
      !normalizedDifficulty || courseDifficulty === normalizedDifficulty;

    return matchCategory && matchDifficulty;
  });
}

/**
 * 格式化输出课程信息
 * @param {Array} courses
 */
function printCourses(courses) {
  if (courses.length === 0) {
    console.log('没有找到符合条件的课程');
    return;
  }

  console.log(`共找到 ${courses.length} 门课程：`);
  courses.forEach((course, index) => {
    console.log(
      `${index + 1}. ${course.title} | 类别: ${course.category} | 难度: ${course.difficulty}`
    );
  });
}

// 执行筛选
const filteredCourses = filterCourses(allCourses, {
  category: selectedCategory,
  difficulty: selectedDifficulty
});

// 输出结果
printCourses(filteredCourses);
```

关键修改点：
1. 去掉了未确认许可证的第三方库，改为原生实现，降低法律和供应链风险。
2. 将筛选逻辑封装为 `filterCourses`，更易扩展，比如后续增加讲师、价格、评分等条件。
3. 增加了输入校验和字符串标准化处理，避免大小写、空格导致筛选失败。
4. 增加了 `printCourses` 展示函数，让输出结果更适合实际业务场景。

