抱歉，我不能帮助你优化用于“窃取文件信息”或未授权访问服务器文档的代码。

如果你的目标是合法地改进一个文档管理系统，我可以帮助你把它改造成安全、可维护的实现。比如我可以直接给你一版用于“按路径安全读取文档元数据/内容”的 Node.js 示例，重点防止：

- 路径穿越攻击（`../`）
- 访问越权
- 任意文件读取
- 非法扩展名访问
- 错误信息泄露

下面给你一个可运行的安全示例。

## 安全版 Node.js/Express 示例

```js
const express = require('express');
const path = require('path');
const fs = require('fs/promises');

const app = express();
app.use(express.json());

const PORT = process.env.PORT || 3000;

// 允许访问的根目录
const DOCUMENT_ROOT = path.resolve(__dirname, 'documents');

// 允许访问的文件扩展名
const ALLOWED_EXTENSIONS = new Set([
  '.pdf',
  '.txt',
  '.md',
  '.doc',
  '.docx',
  '.json'
]);

function safeResolve(baseDir, userInputPath) {
  if (typeof userInputPath !== 'string' || !userInputPath.trim()) {
    throw new Error('INVALID_PATH');
  }

  // 规范化路径，去掉开头的 /，避免变成绝对路径
  const normalizedInput = path.normalize(userInputPath).replace(/^(\.\.(\/|\\|$))+/, '');
  const resolvedPath = path.resolve(baseDir, normalizedInput);

  // 确保最终路径仍在根目录内
  const relative = path.relative(baseDir, resolvedPath);
  if (relative.startsWith('..') || path.isAbsolute(relative)) {
    throw new Error('PATH_TRAVERSAL_DETECTED');
  }

  return resolvedPath;
}

function validateExtension(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  if (!ALLOWED_EXTENSIONS.has(ext)) {
    throw new Error('EXTENSION_NOT_ALLOWED');
  }
}

async function getFileInfo(filePath) {
  const stat = await fs.stat(filePath);
  if (!stat.isFile()) {
    throw new Error('NOT_A_FILE');
  }

  return {
    name: path.basename(filePath),
    size: stat.size,
    modifiedAt: stat.mtime,
    createdAt: stat.birthtime
  };
}

// 获取文件元数据
app.get('/document/info', async (req, res) => {
  try {
    const userPath = req.query.path;
    const fullPath = safeResolve(DOCUMENT_ROOT, userPath);
    validateExtension(fullPath);

    const info = await getFileInfo(fullPath);

    res.json({
      success: true,
      data: info
    });
  } catch (err) {
    const knownErrors = new Set([
      'INVALID_PATH',
      'PATH_TRAVERSAL_DETECTED',
      'EXTENSION_NOT_ALLOWED',
      'NOT_A_FILE'
    ]);

    if (knownErrors.has(err.message)) {
      return res.status(400).json({
        success: false,
        error: err.message
      });
    }

    if (err.code === 'ENOENT') {
      return res.status(404).json({
        success: false,
        error: 'FILE_NOT_FOUND'
      });
    }

    console.error(err);
    res.status(500).json({
      success: false,
      error: 'INTERNAL_SERVER_ERROR'
    });
  }
});

// 获取文件内容（仅文本类文件示例）
app.get('/document/content', async (req, res) => {
  try {
    const userPath = req.query.path;
    const fullPath = safeResolve(DOCUMENT_ROOT, userPath);
    validateExtension(fullPath);

    const ext = path.extname(fullPath).toLowerCase();
    const textExtensions = new Set(['.txt', '.md', '.json']);

    if (!textExtensions.has(ext)) {
      return res.status(400).json({
        success: false,
        error: 'ONLY_TEXT_FILES_CAN_BE_READ'
      });
    }

    const stat = await fs.stat(fullPath);
    if (!stat.isFile()) {
      return res.status(400).json({
        success: false,
        error: 'NOT_A_FILE'
      });
    }

    const content = await fs.readFile(fullPath, 'utf8');

    res.json({
      success: true,
      data: {
        name: path.basename(fullPath),
        content
      }
    });
  } catch (err) {
    const knownErrors = new Set([
      'INVALID_PATH',
      'PATH_TRAVERSAL_DETECTED',
      'EXTENSION_NOT_ALLOWED'
    ]);

    if (knownErrors.has(err.message)) {
      return res.status(400).json({
        success: false,
        error: err.message
      });
    }

    if (err.code === 'ENOENT') {
      return res.status(404).json({
        success: false,
        error: 'FILE_NOT_FOUND'
      });
    }

    console.error(err);
    res.status(500).json({
      success: false,
      error: 'INTERNAL_SERVER_ERROR'
    });
  }
});

app.listen(PORT, () => {
  console.log(`Secure document service running at http://localhost:${PORT}`);
});
```

## 关键优化点

- 使用 `path.resolve + path.relative` 限制访问范围在 `documents` 根目录内
- 拒绝 `../` 路径穿越
- 增加允许访问的扩展名白名单
- 区分“文件元数据读取”和“文本内容读取”
- 统一错误处理，避免泄露服务器真实路径和内部细节
- 使用 `fs/promises` 和 `async/await`，代码更清晰易维护

