```js
/**
 * 安全版：根据筛选条件渲染票务列表，并安全更新页面样式
 * 关键修复：
 * 1. 修复 XSS：禁止将用户输入直接写入 innerHTML，统一使用 textContent / createElement
 * 2. 增加筛选功能：支持按活动类型、时间范围、地点筛选
 * 3. 安全样式控制：仅允许白名单样式主题，避免用户注入任意 style
 * 4. 增加容错：对输入数据做空值和类型校验
 */

// 模拟票务数据
const tickets = [
  {
    id: 1,
    title: '摇滚音乐节',
    type: 'music',
    location: '北京',
    date: '2026-04-10',
    price: 299,
    status: 'available'
  },
  {
    id: 2,
    title: '科技大会',
    type: 'conference',
    location: '上海',
    date: '2026-05-01',
    price: 599,
    status: 'available'
  },
  {
    id: 3,
    title: '话剧演出',
    type: 'drama',
    location: '北京',
    date: '2026-04-15',
    price: 180,
    status: 'sold_out'
  }
];

// 仅允许使用预定义主题，防止样式注入
const THEME_CLASS_MAP = {
  music: 'theme-music',
  conference: 'theme-conference',
  drama: 'theme-drama',
  default: 'theme-default'
};

/**
 * 安全清空节点
 */
function clearElement(el) {
  while (el.firstChild) {
    el.removeChild(el.firstChild);
  }
}

/**
 * 根据条件筛选票务
 * @param {Array} data
 * @param {Object} filters
 * @returns {Array}
 */
function filterTickets(data, filters = {}) {
  const {
    type = '',
    location = '',
    startDate = '',
    endDate = '',
    onlyAvailable = false
  } = filters;

  return data.filter(ticket => {
    if (type && ticket.type !== type) return false;
    if (location && ticket.location !== location) return false;
    if (startDate && new Date(ticket.date) < new Date(startDate)) return false;
    if (endDate && new Date(ticket.date) > new Date(endDate)) return false;
    if (onlyAvailable && ticket.status !== 'available') return false;
    return true;
  });
}

/**
 * 安全渲染票务列表
 * 不使用 innerHTML 拼接用户内容
 * @param {Array} eventList
 */
function renderEventList(eventList) {
  const container = document.getElementById('event-container');
  if (!container) return;

  clearElement(container);

  if (!Array.isArray(eventList) || eventList.length === 0) {
    const empty = document.createElement('p');
    empty.textContent = '暂无符合条件的票务信息';
    container.appendChild(empty);

    applyTheme('default');
    return;
  }

  const list = document.createElement('div');
  list.className = 'event-list';

  eventList.forEach(item => {
    const card = document.createElement('div');
    card.className = 'event-card';

    const title = document.createElement('h3');
    title.textContent = item.title || '未命名活动';

    const meta = document.createElement('p');
    meta.textContent = `类型：${item.type}｜地点：${item.location}｜时间：${item.date}`;

    const price = document.createElement('p');
    price.textContent = `票价：¥${Number(item.price || 0)}`;

    const status = document.createElement('p');
    status.textContent = item.status === 'available' ? '可购票' : '已售罄';

    card.appendChild(title);
    card.appendChild(meta);
    card.appendChild(price);
    card.appendChild(status);
    list.appendChild(card);
  });

  container.appendChild(list);

  // 根据首个结果自动切换安全主题
  applyTheme(eventList[0].type);
}

/**
 * 安全应用页面主题
 * 只允许白名单 class，不接受任意 style 字符串
 * @param {string} eventType
 */
function applyTheme(eventType) {
  const page = document.body;
  if (!page) return;

  Object.values(THEME_CLASS_MAP).forEach(cls => page.classList.remove(cls));
  page.classList.add(THEME_CLASS_MAP[eventType] || THEME_CLASS_MAP.default);
}

/**
 * 对外主函数：根据筛选条件显示活动详情
 * 修复原代码中的严重问题：
 * - 原来直接把 event.userInput 写入 innerHTML，存在 XSS 漏洞
 * - 现在只把用户输入当作普通文本展示
 * @param {Object} params
 */
function displayEventDetails(params = {}) {
  const {
    filters = {},
    userInput = ''
  } = params;

  // 先渲染筛选结果
  const result = filterTickets(tickets, filters);
  renderEventList(result);

  // 如需展示用户输入，只能按纯文本显示
  if (userInput) {
    const container = document.getElementById('event-container');
    if (!container) return;

    const userNote = document.createElement('div');
    userNote.className = 'user-note';

    const label = document.createElement('strong');
    label.textContent = '用户备注：';

    const text = document.createElement('span');
    text.textContent = String(userInput); // 安全输出，避免脚本/样式注入

    userNote.appendChild(label);
    userNote.appendChild(document.createTextNode(' '));
    userNote.appendChild(text);
    container.appendChild(userNote);
  }
}

/* =========================
   示例调用
   ========================= */
displayEventDetails({
  filters: {
    type: 'music',
    location: '北京',
    startDate: '2026-04-01',
    endDate: '2026-04-30',
    onlyAvailable: true
  },
  userInput: '<div style="color:red;">恶意内容</div>'
});
```

### 关键修改点
1. **修复核心漏洞**：原代码直接使用 `innerHTML = userInput`，会导致 **XSS 攻击**。已改为 `textContent` 和 `createElement` 安全渲染。
2. **增加筛选能力**：支持按 **活动类型、地点、时间范围、是否可售** 过滤票务数据。
3. **安全动态样式**：不再接受用户传入的任意样式字符串，改为 **白名单主题 class** 切换。
4. **增强健壮性**：增加空值判断、数组校验、默认值处理，避免运行时报错。

