/**
 * 在线购物平台：登录后添加购物车并提交订单
 * 运行方式：
 * 1. 浏览器中直接引入本脚本
 * 2. 或 Node.js 环境运行（模拟流程）
 */

class ShoppingCartSystem {
  constructor() {
    this.currentUser = null;
    this.products = [
      { id: 1, name: "手机", price: 3999, stock: 10 },
      { id: 2, name: "耳机", price: 299, stock: 30 },
      { id: 3, name: "键盘", price: 499, stock: 20 }
    ];
    this.carts = new Map(); // userId -> cartItems
    this.orders = [];
  }

  // 用户登录
  login(userId, username) {
    if (!userId || !username) {
      throw new Error("登录失败：用户信息不完整");
    }
    this.currentUser = { userId, username };
    if (!this.carts.has(userId)) {
      this.carts.set(userId, []);
    }
    console.log(`用户 ${username} 登录成功`);
  }

  // 校验登录状态
  ensureLogin() {
    if (!this.currentUser) {
      throw new Error("请先登录后再操作");
    }
  }

  // 获取商品列表
  getProductList() {
    return this.products;
  }

  // 添加商品到购物车
  addToCart(productId, quantity = 1) {
    this.ensureLogin();

    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new Error("商品数量必须为正整数");
    }

    const product = this.products.find(p => p.id === productId);
    if (!product) {
      throw new Error("商品不存在");
    }

    const cart = this.carts.get(this.currentUser.userId);
    const existingItem = cart.find(item => item.productId === productId);
    const currentQty = existingItem ? existingItem.quantity : 0;

    if (currentQty + quantity > product.stock) {
      throw new Error(`库存不足，当前库存：${product.stock}`);
    }

    if (existingItem) {
      existingItem.quantity += quantity;
    } else {
      cart.push({
        productId: product.id,
        name: product.name,
        price: product.price,
        quantity
      });
    }

    console.log(`已添加 ${quantity} 件【${product.name}】到购物车`);
    return this.getCart();
  }

  // 获取购物车信息
  getCart() {
    this.ensureLogin();

    const cart = this.carts.get(this.currentUser.userId);
    const totalAmount = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

    return {
      user: this.currentUser,
      items: cart,
      totalAmount
    };
  }

  // 更新购物车商品数量
  updateCartItem(productId, quantity) {
    this.ensureLogin();

    const cart = this.carts.get(this.currentUser.userId);
    const item = cart.find(i => i.productId === productId);

    if (!item) {
      throw new Error("购物车中不存在该商品");
    }

    if (quantity <= 0) {
      this.removeFromCart(productId);
      return this.getCart();
    }

    const product = this.products.find(p => p.id === productId);
    if (quantity > product.stock) {
      throw new Error(`库存不足，当前库存：${product.stock}`);
    }

    item.quantity = quantity;
    console.log(`已更新商品【${item.name}】数量为 ${quantity}`);
    return this.getCart();
  }

  // 从购物车移除商品
  removeFromCart(productId) {
    this.ensureLogin();

    const cart = this.carts.get(this.currentUser.userId);
    const index = cart.findIndex(item => item.productId === productId);

    if (index === -1) {
      throw new Error("购物车中不存在该商品");
    }

    const removed = cart.splice(index, 1)[0];
    console.log(`已从购物车移除【${removed.name}】`);
    return this.getCart();
  }

  // 提交订单
  submitOrder() {
    this.ensureLogin();

    const cart = this.carts.get(this.currentUser.userId);
    if (!cart.length) {
      throw new Error("购物车为空，无法提交订单");
    }

    // 再次校验库存并扣减库存
    for (const item of cart) {
      const product = this.products.find(p => p.id === item.productId);
      if (!product || product.stock < item.quantity) {
        throw new Error(`商品【${item.name}】库存不足，无法提交订单`);
      }
    }

    for (const item of cart) {
      const product = this.products.find(p => p.id === item.productId);
      product.stock -= item.quantity;
    }

    const totalAmount = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
    const order = {
      orderId: `ORD-${Date.now()}`,
      userId: this.currentUser.userId,
      username: this.currentUser.username,
      items: [...cart],
      totalAmount,
      status: "PAID",
      createdAt: new Date().toISOString()
    };

    this.orders.push(order);
    this.carts.set(this.currentUser.userId, []); // 清空购物车

    console.log("订单提交成功：", order);
    return order;
  }
}

