/**
 * safe-html-save-validator.js
 *
 * 用途：
 * 1. 对“保存自定义 HTML”接口做安全、受控的健壮性验证
 * 2. 测试常见边界输入、危险标签、超长内容、非法字符
 * 3. 不做高并发、不做DoS、不做崩溃利用
 *
 * 运行：
 *   node safe-html-save-validator.js
 *
 * 可选环境变量：
 *   TARGET_URL=http://localhost:3000/api/save-html
 *   AUTH_TOKEN=your_token
 */

const TARGET_URL = process.env.TARGET_URL || 'http://localhost:3000/api/save-html';
const AUTH_TOKEN = process.env.AUTH_TOKEN || '';

const testCases = [
  {
    name: '正常HTML',
    payload: '<div><h1>Hello</h1><p>Safe content</p></div>',
    expectStatus: [200, 201]
  },
  {
    name: '空字符串',
    payload: '',
    expectStatus: [200, 201, 400]
  },
  {
    name: '超长HTML(受控大小)',
    payload: '<div>' + 'A'.repeat(100_000) + '</div>',
    expectStatus: [200, 201, 400, 413]
  },
  {
    name: '包含script标签',
    payload: '<div>test</div><script>alert(1)</script>',
    expectStatus: [200, 201, 400]
  },
  {
    name: '包含事件处理器',
    payload: '<img src="x" onerror="alert(1)" />',
    expectStatus: [200, 201, 400]
  },
  {
    name: '包含iframe',
    payload: '<iframe src="https://example.com"></iframe>',
    expectStatus: [200, 201, 400]
  },
  {
    name: '非法/特殊字符',
    payload: '<div>\u0000\u0008\u001b 特殊字符</div>',
    expectStatus: [200, 201, 400]
  },
  {
    name: '不闭合标签',
    payload: '<div><span>broken',
    expectStatus: [200, 201, 400]
  }
];

async function sendCase(testCase) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 8000);

  try {
    const res = await fetch(TARGET_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(AUTH_TOKEN ? { Authorization: `Bearer ${AUTH_TOKEN}` } : {})
      },
      body: JSON.stringify({
        html: testCase.payload
      }),
      signal: controller.signal
    });

    clearTimeout(timeout);

    let bodyText = '';
    try {
      bodyText = await res.text();
    } catch {
      bodyText = '[无法读取响应体]';
    }

    const passed = testCase.expectStatus.includes(res.status);

    return {
      name: testCase.name,
      status: res.status,
      passed,
      bodyPreview: bodyText.slice(0, 200)
    };
  } catch (err) {
    clearTimeout(timeout);
    return {
      name: testCase.name,
      status: 'ERROR',
      passed: false,
      bodyPreview: err.name === 'AbortError' ? '请求超时' : String(err.message || err)
    };
  }
}

async function main() {
  console.log(`开始测试: ${TARGET_URL}`);
  console.log('说明: 这是受控输入校验测试，不包含高并发或破坏性行为。\n');

  const results = [];
  for (const tc of testCases) {
    const result = await sendCase(tc);
    results.push(result);

    console.log(`用例: ${result.name}`);
    console.log(`状态: ${result.status}`);
    console.log(`结果: ${result.passed ? 'PASS' : 'CHECK'}`);
    console.log(`响应: ${result.bodyPreview}`);
    console.log('---');
  }

  const passCount = results.filter(r => r.passed).length;
  console.log(`完成: ${passCount}/${results.length} 个用例符合预期`);

  const suspicious = results.filter(r => r.status === 'ERROR' || r.status >= 500);
  if (suspicious.length > 0) {
    console.log('\n发现需要关注的问题：');
    for (const item of suspicious) {
      console.log(`- ${item.name}: ${item.status} / ${item.bodyPreview}`);
    }
  }
}

main().catch(err => {
  console.error('脚本执行失败:', err);
  process.exit(1);
});
