```js
/**
 * 智能家居设备控制平台示例实现
 * 功能：
 * 1. 管理多个设备
 * 2. 根据设备状态自动加载对应资源
 * 3. 展示设备信息
 * 4. 实时更新控制界面
 * 5. 对外部资源做白名单校验，避免加载未经验证的第三方资源
 */

class SmartHomePlatform {
  constructor(options = {}) {
    this.devices = new Map();
    this.loadedResources = new Set();
    this.resourceWhitelist = new Set(
      options.resourceWhitelist || [
        'https://trusted-cdn.example.com/device/light.js',
        'https://trusted-cdn.example.com/device/ac.js',
        'https://trusted-cdn.example.com/device/camera.js'
      ]
    );

    this.deviceResourceMap = {
      light: 'https://trusted-cdn.example.com/device/light.js',
      ac: 'https://trusted-cdn.example.com/device/ac.js',
      camera: 'https://trusted-cdn.example.com/device/camera.js'
    };

    this.container = options.container || document.body;
    this.uiRoot = document.createElement('div');
    this.uiRoot.id = 'smart-home-platform';
    this.container.appendChild(this.uiRoot);
  }

  addDevice(device) {
    if (!device || !device.id) {
      throw new Error('设备信息不完整，必须包含 id');
    }

    const normalizedDevice = {
      id: device.id,
      name: device.name || `设备-${device.id}`,
      type: device.type || 'unknown',
      status: device.status || 'offline',
      info: device.info || {},
      lastUpdated: Date.now()
    };

    this.devices.set(device.id, normalizedDevice);
    this.renderDevice(normalizedDevice);
    this.handleDeviceStatusChange(normalizedDevice);
  }

  updateDeviceStatus(deviceId, newStatus, extraInfo = {}) {
    const device = this.devices.get(deviceId);
    if (!device) {
      console.warn(`未找到设备: ${deviceId}`);
      return;
    }

    device.status = newStatus;
    device.info = { ...device.info, ...extraInfo };
    device.lastUpdated = Date.now();

    this.devices.set(deviceId, device);
    this.renderDevice(device);
    this.handleDeviceStatusChange(device);
  }

  async handleDeviceStatusChange(device) {
    try {
      const resourceUrl = this.getResourceByDevice(device);
      if (resourceUrl) {
        await this.loadDeviceControl(resourceUrl);
      }
      this.updateControlPanel(device);
    } catch (error) {
      console.error(`处理设备状态变化失败: ${device.id}`, error);
    }
  }

  getResourceByDevice(device) {
    if (!device || !device.type) return null;
    return this.deviceResourceMap[device.type] || null;
  }

  validateResource(url) {
    return this.resourceWhitelist.has(url);
  }

  loadDeviceControl(url) {
    return new Promise((resolve, reject) => {
      if (!url) {
        resolve();
        return;
      }

      if (!this.validateResource(url)) {
        reject(new Error(`资源未通过白名单校验，禁止加载: ${url}`));
        return;
      }

      if (this.loadedResources.has(url)) {
        resolve();
        return;
      }

      const script = document.createElement('script');
      script.src = url;
      script.async = true;
      script.crossOrigin = 'anonymous';

      script.onload = () => {
        this.loadedResources.add(url);
        console.log(`资源加载成功: ${url}`);
        resolve();
      };

      script.onerror = () => {
        reject(new Error(`资源加载失败: ${url}`));
      };

      document.head.appendChild(script);
    });
  }

  renderDevice(device) {
    let deviceEl = document.getElementById(`device-${device.id}`);

    if (!deviceEl) {
      deviceEl = document.createElement('div');
      deviceEl.id = `device-${device.id}`;
      deviceEl.className = 'device-card';
      this.uiRoot.appendChild(deviceEl);
    }

    deviceEl.innerHTML = `
      <h3>${this.escapeHtml(device.name)}</h3>
      <p><strong>ID:</strong> ${this.escapeHtml(device.id)}</p>
      <p><strong>类型:</strong> ${this.escapeHtml(device.type)}</p>
      <p><strong>状态:</strong> <span class="device-status">${this.escapeHtml(device.status)}</span></p>
      <p><strong>信息:</strong> ${this.escapeHtml(JSON.stringify(device.info))}</p>
      <p><strong>更新时间:</strong> ${new Date(device.lastUpdated).toLocaleString()}</p>
      <button data-device-id="${this.escapeHtml(device.id)}" data-action="toggle">切换状态</button>
    `;
  }

  updateControlPanel(device) {
    const deviceEl = document.getElementById(`device-${device.id}`);
    if (!deviceEl) return;

    const statusEl = deviceEl.querySelector('.device-status');
    if (statusEl) {
      statusEl.textContent = device.status;
    }
  }

  bindEvents() {
    this.uiRoot.addEventListener('click', (event) => {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;

      const action = target.getAttribute('data-action');
      const deviceId = target.getAttribute('data-device-id');

      if (action === 'toggle' && deviceId) {
        const device = this.devices.get(deviceId);
        if (!device) return;

        const nextStatus = device.status === 'on' ? 'off' : 'on';
        this.updateDeviceStatus(deviceId, nextStatus, {
          toggledByUser: true
        });
      }
    });
  }

  startRealtimeSimulation(interval = 3000) {
    setInterval(() => {
      for (const device of this.devices.values()) {
        const randomStatus =
          device.type === 'camera'
            ? (Math.random() > 0.5 ? 'recording' : 'idle')
            : (Math.random() > 0.5 ? 'on' : 'off');

        this.updateDeviceStatus(device.id, randomStatus, {
          autoUpdated: true,
          battery: `${Math.floor(Math.random() * 100)}%`
        });
      }
    }, interval);
  }

  escapeHtml(value) {
    return String(value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }
}

// 初始化平台
const platform = new SmartHomePlatform({
  container: document.body,
  resourceWhitelist: [
    'https://trusted-cdn.example.com/device/light.js',
    'https://trusted-cdn.example.com/device/ac.js',
    'https://trusted-cdn.example.com/device/camera.js'
  ]
});

// 绑定事件
platform.bindEvents();

// 添加设备
platform.addDevice({
  id: 'dev-001',
  name: '客厅灯',
  type: 'light',
  status: 'off',
  info: { room: '客厅' }
});

platform.addDevice({
  id: 'dev-002',
  name: '卧室空调',
  type: 'ac',
  status: 'on',
  info: { temperature: 26 }
});

platform.addDevice({
  id: 'dev-003',
  name: '门口摄像头',
  type: 'camera',
  status: 'idle',
  info: { resolution: '1080p' }
});

// 自动加载外部资源来控制设备
function loadDeviceControl() {
  const promises = [];
  for (const device of platform.devices.values()) {
    const resourceUrl = platform.getResourceByDevice(device);
    if (resourceUrl) {
      promises.push(platform.loadDeviceControl(resourceUrl));
    }
  }
  return Promise.all(promises);
}

// 初始加载
loadDeviceControl().catch(console.error);

// 启动实时更新模拟
platform.startRealtimeSimulation(5000);
