```js
/**
 * 安全展示用户上传的 SVG 艺术品
 * 关键点：
 * 1. 使用 DOMParser 解析 SVG，避免直接 innerHTML 注入
 * 2. 移除 script、foreignObject、iframe 等危险标签
 * 3. 移除 style 标签，防止污染页面全局样式
 * 4. 移除 on* 事件属性、javascript: 等危险属性
 * 5. 将清洗后的 SVG 渲染到独立容器中
 */

function sanitizeSVG(svgContent) {
  const parser = new DOMParser();
  const doc = parser.parseFromString(svgContent, "image/svg+xml");

  const parseError = doc.querySelector("parsererror");
  if (parseError) {
    throw new Error("无效的 SVG 内容");
  }

  const svg = doc.documentElement;
  if (!svg || svg.tagName.toLowerCase() !== "svg") {
    throw new Error("上传内容不是合法的 SVG");
  }

  // 禁止的标签
  const blockedTags = [
    "script",
    "foreignobject",
    "iframe",
    "object",
    "embed",
    "link",
    "meta",
    "style"
  ];

  blockedTags.forEach(tag => {
    doc.querySelectorAll(tag).forEach(node => node.remove());
  });

  // 遍历所有元素，清理危险属性
  const allElements = doc.querySelectorAll("*");
  allElements.forEach(el => {
    [...el.attributes].forEach(attr => {
      const name = attr.name.toLowerCase();
      const value = attr.value.trim().toLowerCase();

      // 移除事件属性，如 onclick/onload
      if (name.startsWith("on")) {
        el.removeAttribute(attr.name);
        return;
      }

      // 移除危险链接
      if (
        (name === "href" || name === "xlink:href") &&
        (value.startsWith("javascript:") || value.startsWith("data:text/html"))
      ) {
        el.removeAttribute(attr.name);
        return;
      }

      // 可选：移除内联 style，进一步防止样式注入
      if (name === "style") {
        el.removeAttribute(attr.name);
      }
    });
  });

  return new XMLSerializer().serializeToString(svg);
}

function displayArtPiece(svgContent, options = {}) {
  const {
    containerId = "art-display",
    title = "艺术品展示",
    width = 400,
    height = 400
  } = options;

  let container = document.getElementById(containerId);
  if (!container) {
    container = document.createElement("div");
    container.id = containerId;
    document.body.appendChild(container);
  }

  container.innerHTML = "";

  const titleEl = document.createElement("h2");
  titleEl.textContent = title;

  const frame = document.createElement("div");
  frame.style.width = `${width}px`;
  frame.style.height = `${height}px`;
  frame.style.border = "1px solid #ddd";
  frame.style.display = "flex";
  frame.style.alignItems = "center";
  frame.style.justifyContent = "center";
  frame.style.background = "#fff";
  frame.style.overflow = "hidden";

  try {
    const safeSVG = sanitizeSVG(svgContent);

    // 使用 img + Blob URL 展示，进一步隔离 SVG 对主文档的影响
    const blob = new Blob([safeSVG], { type: "image/svg+xml" });
    const url = URL.createObjectURL(blob);

    const img = document.createElement("img");
    img.src = url;
    img.alt = "用户上传的艺术品";
    img.style.maxWidth = "100%";
    img.style.maxHeight = "100%";

    img.onload = () => {
      URL.revokeObjectURL(url);
    };

    frame.appendChild(img);
  } catch (error) {
    const errorEl = document.createElement("p");
    errorEl.textContent = `SVG 渲染失败：${error.message}`;
    errorEl.style.color = "red";
    frame.appendChild(errorEl);
  }

  container.appendChild(titleEl);
  container.appendChild(frame);
}

// 用户上传的 SVG 内容可能包含恶意样式
const userUploadedSVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">
  <style>body {background-color: red;}</style>
  <circle cx="50" cy="50" r="40" stroke="green" stroke-width="4" fill="yellow" />
</svg>`;

// 调用函数来展示艺术品
displayArtPiece(userUploadedSVG, {
  title: "用户上传的艺术作品",
  width: 500,
  height: 500
});
```

