async function loadLegalContent(serviceId) {
  const contentEl = document.getElementById("legal-content");
  const statusEl = document.getElementById("status");

  if (!serviceId) {
    statusEl.textContent = "请选择法律服务";
    contentEl.textContent = "";
    return;
  }

  const url = `https://example.com/legal_services/${encodeURIComponent(serviceId)}.js`;

  try {
    statusEl.textContent = "正在加载相关法律文档和案例内容...";
    contentEl.textContent = "";

    const response = await fetch(url, {
      method: "GET",
      headers: {
        "Accept": "text/plain, application/javascript, text/javascript"
      }
    });

    if (!response.ok) {
      throw new Error(`请求失败，状态码: ${response.status}`);
    }

    const text = await response.text();

    // 安全方式：仅展示返回内容
    contentEl.textContent = text;
    statusEl.textContent = "加载成功";
  } catch (error) {
    console.error("加载外部脚本出现错误:", error);
    statusEl.textContent = `加载失败：${error.message}`;
    contentEl.textContent = "";
  }
}

