 * 注意：执行第三方脚本存在安全风险，请谨慎使用。
 */
function loadLegalScript(serviceId) {
  return new Promise((resolve, reject) => {
    if (!serviceId) {
      reject(new Error("serviceId 不能为空"));
      return;
    }

    const oldScript = document.getElementById("dynamic-legal-script");
    if (oldScript) {
      oldScript.remove();
    }

    const script = document.createElement("script");
    script.id = "dynamic-legal-script";
    script.src = `https://example.com/legal_services/${encodeURIComponent(serviceId)}.js`;
    script.async = true;

    script.onload = () => resolve(`脚本 ${serviceId} 加载成功`);
    script.onerror = () => reject(new Error(`脚本 ${serviceId} 加载失败`));

    document.body.appendChild(script);
  });
}

