// 可直接在浏览器环境中使用
// 作用：将输入框中的评论内容即时、安全地展示到对应区域

document.addEventListener("DOMContentLoaded", () => {
  const commentInput = document.getElementById("commentInput");
  const commentDisplay = document.getElementById("commentDisplay");
  const submitButton = document.getElementById("submitButton");

  function escapeXml(str) {
    return str
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&apos;");
  }

  function submitComment() {
    const comment = commentInput.value.trim();

    // 构造与 Python 版本类似的 XML 展示字符串
    const displayText = `<display><comment>${escapeXml(comment)}</comment></display>`;

    // 使用 textContent 展示纯文本，避免被当作 HTML 执行
    commentDisplay.textContent = displayText;
  }

  // 点击按钮提交
  submitButton.addEventListener("click", submitComment);

  // 即时展示：输入时同步更新
  commentInput.addEventListener("input", submitComment);
});
