const AUTH_COOKIE = ''; // 如需登录态可填写，例如：session=xxxx
const FILE_FIELD_NAME = 'file'; // 上传字段名，按实际接口修改

function createFakeFile(filename, contentType, content) {
  return {
    value: Buffer.from(content, 'utf8'),
    options: {
      filename,
      contentType,
    },
  };
}

const testCases = [
  {
    name: '正常 jpg 文件',
    file: {
      value: Buffer.from([0xff, 0xd8, 0xff, 0xe0, 0x00, 0x10, 0x4a, 0x46, 0x49, 0x46]),
      options: {
        filename: 'normal.jpg',
        contentType: 'image/jpeg',
      },
    },
    expected: 'allow',
  },
  {
    name: '双扩展名测试',
    file: createFakeFile('test.php.jpg', 'image/jpeg', 'fake image content'),
    expected: 'reject',
  },
  {
    name: '伪造 MIME 的脚本文件',
    file: createFakeFile('shell.php', 'image/jpeg', '<?php echo "test"; ?>'),
    expected: 'reject',
  },
  {
    name: '图片扩展名但内容非图片',
    file: createFakeFile('fake.png', 'image/png', '<script>alert(1)</script>'),
    expected: 'reject',
  },
  {
    name: '大小写绕过测试',
    file: createFakeFile('evil.PhP', 'application/octet-stream', '<?php phpinfo(); ?>'),
    expected: 'reject',
  },
  {
    name: '空文件测试',
    file: createFakeFile('empty.jpg', 'image/jpeg', ''),
    expected: 'reject',
  },
];

async function uploadTest(testCase) {
  const form = new FormData();
  form.append(FILE_FIELD_NAME, testCase.file.value, testCase.file.options);

  try {
    const res = await axios.post(TARGET_URL, form, {
      headers: {
        ...form.getHeaders(),
        ...(AUTH_COOKIE ? { Cookie: AUTH_COOKIE } : {}),
      },
      maxBodyLength: Infinity,
      validateStatus: () => true,
      timeout: 15000,
    });

    const passed =
      testCase.expected === 'reject'
        ? res.status >= 400 || /reject|invalid|forbidden|not allowed/i.test(String(res.data))
        : res.status >= 200 && res.status < 300;

    console.log(`\n[${passed ? 'PASS' : 'FAIL'}] ${testCase.name}`);
    console.log(`Expected: ${testCase.expected}`);
    console.log(`Status: ${res.status}`);
    console.log(`Response: ${typeof res.data === 'string' ? res.data.slice(0, 300) : JSON.stringify(res.data).slice(0, 300)}`);
  } catch (err) {
    console.log(`\n[ERROR] ${testCase.name}`);
    console.log(err.message);
  }
}

(async () => {
  console.log('开始上传安全测试...');
  for (const testCase of testCases) {
    await uploadTest(testCase);
  }
  console.log('\n测试完成');
})();
