```php
<?php
declare(strict_types=1);

/**
 * 优化后的用户登录与会话管理示例
 * 运行方式：
 * 1. 保存为 login.php
 * 2. 通过 PHP 内置服务器运行：php -S localhost:8000
 * 3. 浏览器访问：http://localhost:8000/login.php
 */

// -------------------------
// 安全的 Session 初始化
// -------------------------
function startSecureSession(): void
{
    if (session_status() === PHP_SESSION_NONE) {
        $isHttps = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off');

        session_set_cookie_params([
            'lifetime' => 0,
            'path'     => '/',
            'domain'   => '',
            'secure'   => $isHttps,
            'httponly' => true,
            'samesite' => 'Strict',
        ]);

        session_start();
    }
}

// -------------------------
// 模拟用户数据
// 实际项目中应从数据库读取
// -------------------------
function getUsers(): array
{
    return [
        'user' => [
            'username' => 'user',
            'password_hash' => password_hash('password', PASSWORD_DEFAULT),
        ],
    ];
}

// -------------------------
// 登录逻辑
// -------------------------
function userLogin(string $username, string $password): array
{
    $users = getUsers();

    if (!isset($users[$username])) {
        return ['success' => false, 'message' => '用户名或密码错误！'];
    }

    $user = $users[$username];

    if (!password_verify($password, $user['password_hash'])) {
        return ['success' => false, 'message' => '用户名或密码错误！'];
    }

    // 防止会话固定攻击
    session_regenerate_id(true);

    $_SESSION['username']   = $user['username'];
    $_SESSION['logged_in']  = true;
    $_SESSION['login_time'] = time();

    return ['success' => true, 'message' => '登录成功！'];
}

// -------------------------
// 检查是否已登录
// -------------------------
function isLoggedIn(): bool
{
    return !empty($_SESSION['logged_in']) && !empty($_SESSION['username']);
}

// -------------------------
// 登出逻辑
// -------------------------
function userLogout(): void
{
    $_SESSION = [];

    if (ini_get('session.use_cookies')) {
        $params = session_get_cookie_params();
        setcookie(
            session_name(),
            '',
            time() - 42000,
            $params['path'],
            $params['domain'],
            $params['secure'],
            $params['httponly']
        );
    }

    session_destroy();
}

// -------------------------
// 主流程
// -------------------------
startSecureSession();

$message = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $username = trim($_POST['username'] ?? '');
    $password = trim($_POST['password'] ?? '');

    if ($username === '' || $password === '') {
        $message = '用户名和密码不能为空！';
    } else {
        $result = userLogin($username, $password);
        $message = $result['message'];
    }
}

if (isset($_GET['action']) && $_GET['action'] === 'logout') {
    userLogout();
    header('Location: ' . strtok($_SERVER['REQUEST_URI'], '?'));
    exit;
}
?>
