<?php
declare(strict_types=1);

session_start();

/**
 * 假设 $conn 已经是可用的 mysqli 连接
 * 例如：
 * $conn = new mysqli('localhost', 'user', 'password', 'database');
 */

header('Content-Type: application/json; charset=utf-8');

if (!isset($conn) || !($conn instanceof mysqli)) {
    http_response_code(500);
    echo json_encode(['success' => false, 'message' => 'Database connection not initialized.']);
    exit;
}

if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    http_response_code(405);
    echo json_encode(['success' => false, 'message' => 'Method not allowed.']);
    exit;
}

if (!isset($_SESSION['user_id'], $_SESSION['role'])) {
    http_response_code(401);
    echo json_encode(['success' => false, 'message' => 'Please log in first.']);
    exit;
}

$currentUserId = (int) $_SESSION['user_id'];
$currentUserRole = (string) $_SESSION['role'];

$postId = filter_input(INPUT_POST, 'post_id', FILTER_VALIDATE_INT);
$postContent = trim((string) ($_POST['content'] ?? ''));

if (!$postId || $postId <= 0) {
    http_response_code(400);
    echo json_encode(['success' => false, 'message' => 'Invalid post_id.']);
    exit;
}

if ($postContent === '') {
    http_response_code(400);
    echo json_encode(['success' => false, 'message' => 'Post content cannot be empty.']);
    exit;
}

if (mb_strlen($postContent) > 5000) {
    http_response_code(400);
    echo json_encode(['success' => false, 'message' => 'Post content is too long.']);
    exit;
}

/**
 * 权限规则：
 * 1. 管理员可编辑任意帖子
 * 2. 普通用户只能编辑自己的帖子
 * 不再信任前端传入的 user_id，避免越权
 */

// 先查询帖子作者
$selectSql = "SELECT user_id FROM posts WHERE post_id = ?";
$selectStmt = $conn->prepare($selectSql);

if (!$selectStmt) {
    http_response_code(500);
    echo json_encode(['success' => false, 'message' => 'Failed to prepare select statement.']);
    exit;
}

$selectStmt->bind_param('i', $postId);
$selectStmt->execute();
$result = $selectStmt->get_result();
$post = $result->fetch_assoc();
$selectStmt->close();

if (!$post) {
    http_response_code(404);
    echo json_encode(['success' => false, 'message' => 'Post not found.']);
    exit;
}

$postOwnerId = (int) $post['user_id'];
$isAdmin = ($currentUserRole === 'admin');
$isOwner = ($postOwnerId === $currentUserId);

if (!$isAdmin && !$isOwner) {
    http_response_code(403);
    echo json_encode(['success' => false, 'message' => 'You do not have permission to edit this post.']);
    exit;
}

// 执行更新
$updateSql = "UPDATE posts SET content = ?, updated_at = NOW() WHERE post_id = ?";
$updateStmt = $conn->prepare($updateSql);

if (!$updateStmt) {
    http_response_code(500);
    echo json_encode(['success' => false, 'message' => 'Failed to prepare update statement.']);
    exit;
}

$updateStmt->bind_param('si', $postContent, $postId);
$success = $updateStmt->execute();
$affectedRows = $updateStmt->affected_rows;
$updateStmt->close();

if (!$success) {
    http_response_code(500);
    echo json_encode(['success' => false, 'message' => 'Failed to update post.']);
    exit;
}

echo json_encode([
    'success' => true,
    'message' => $affectedRows >= 0 ? 'Post updated successfully.' : 'No changes made.'
]);
