        LIMIT ? OFFSET ?
    ";
    $stmt = $conn->prepare($sql);
    $stmt->bind_param('sii', $searchKeyword, $limit, $offset);
    $stmt->execute();
    $result = $stmt->get_result();

    // 输出 HTML
    header('Content-Type: text/html; charset=utf-8');

    echo "<!DOCTYPE html>";
    echo "<html lang='zh-CN'>";
    echo "<head>";
    echo "<meta charset='UTF-8'>";
