```php
<?php
declare(strict_types=1);

header('Content-Type: application/json; charset=utf-8');

/**
 * 从环境变量读取 Base64 编码的 32 字节密钥
 * 生成方式示例：
 *   php -r "echo base64_encode(random_bytes(32)), PHP_EOL;"
 */
function getEncryptionKey(): string
{
    $keyB64 = getenv('PAYMENT_ENCRYPTION_KEY');
    if ($keyB64 === false || $keyB64 === '') {
        throw new RuntimeException('Missing PAYMENT_ENCRYPTION_KEY environment variable.');
    }

    $key = base64_decode($keyB64, true);
    if ($key === false || strlen($key) !== 32) {
        throw new RuntimeException('PAYMENT_ENCRYPTION_KEY must be a valid base64-encoded 32-byte key.');
    }

    return $key;
}

/**
 * 使用 AES-256-GCM 加密数据
 */
function encryptPaymentData(string $plaintext, string $key): array
{
    $cipher = 'aes-256-gcm';
    $ivLength = openssl_cipher_iv_length($cipher);
    if ($ivLength === false) {
        throw new RuntimeException('Unable to determine IV length.');
    }

    $iv = random_bytes($ivLength);
    $tag = '';

    $ciphertext = openssl_encrypt(
        $plaintext,
        $cipher,
        $key,
        OPENSSL_RAW_DATA,
        $iv,
        $tag
    );

    if ($ciphertext === false) {
        throw new RuntimeException('Encryption failed.');
    }

    return [
        'algorithm'  => $cipher,
        'iv'         => base64_encode($iv),
        'tag'        => base64_encode($tag),
        'ciphertext' => base64_encode($ciphertext),
    ];
}

try {
    if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
        http_response_code(405);
        echo json_encode(['error' => 'Method not allowed']);
        exit;
    }

    $paymentData = $_POST['paymentData'] ?? '';
    if (!is_string($paymentData) || trim($paymentData) === '') {
        http_response_code(400);
        echo json_encode(['error' => 'paymentData is required']);
        exit;
    }

    $key = getEncryptionKey();
    $encrypted = encryptPaymentData($paymentData, $key);

    // 这里可将 $encrypted 存入数据库
    // 示例：仅返回结果
    echo json_encode([
        'success' => true,
        'data' => $encrypted
    ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);

} catch (Throwable $e) {
    http_response_code(500);
    echo json_encode([
        'success' => false,
        'error' => 'Internal server error'
    ]);
}
```

