```php
<?php
declare(strict_types=1);

/**
 * 安全嵌入第三方支付页面
 * 关键点：
 * 1. 不再直接写死/信任任意第三方 URL，改为白名单校验
 * 2. 强制要求 HTTPS
 * 3. 过滤并转义 iframe src，防止注入
 * 4. 增加 sandbox / referrerpolicy / allow 等安全属性
 * 5. 增加 CSP 响应头，限制 frame 来源
 */

final class PaymentIframeEmbedder
{
    /**
     * 仅允许可信支付域名
     * 实际项目中请替换为你的真实支付服务商域名
     */
    private const ALLOWED_HOSTS = [
        'secure-payment.example.com',
        'checkout.payment-provider.com',
    ];

    public static function render(string $paymentUrl): void
    {
        $safeUrl = self::validatePaymentUrl($paymentUrl);

        if ($safeUrl === null) {
            http_response_code(400);
            echo '<p>支付页面地址无效或不被允许。</p>';
            return;
        }

        // 建议在任何输出前设置响应头
        header(
            "Content-Security-Policy: default-src 'self'; " .
            "frame-src 'self' " . self::buildFrameSrcPolicy() . "; " .
            "object-src 'none'; base-uri 'self';"
        );
        header('X-Content-Type-Options: nosniff');
        header('Referrer-Policy: strict-origin-when-cross-origin');

        echo '<iframe'
            . ' src="' . htmlspecialchars($safeUrl, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '"'
            . ' width="100%"'
            . ' height="600"'
            . ' style="border:0;"'
            . ' loading="lazy"'
            . ' referrerpolicy="strict-origin-when-cross-origin"'
            . ' sandbox="allow-scripts allow-forms allow-same-origin"'
            . ' allow="payment *"'
            . '></iframe>';
    }

    private static function validatePaymentUrl(string $url): ?string
    {
        $url = trim($url);
        if ($url === '') {
            return null;
        }

        $parts = parse_url($url);
        if ($parts === false) {
            return null;
        }

        $scheme = strtolower($parts['scheme'] ?? '');
        $host   = strtolower($parts['host'] ?? '');

        if ($scheme !== 'https') {
            return null;
        }

        if (!in_array($host, self::ALLOWED_HOSTS, true)) {
            return null;
        }

        return filter_var($url, FILTER_VALIDATE_URL) ?: null;
    }

    private static function buildFrameSrcPolicy(): string
    {
        return implode(' ', array_map(
            static fn(string $host): string => 'https://' . $host,
            self::ALLOWED_HOSTS
        ));
    }
}

// 示例：实际项目中建议从服务端配置或订单支付会话中获取，而不是直接信任用户输入
$paymentUrl = 'https://secure-payment.example.com/checkout/session-123';

PaymentIframeEmbedder::render($paymentUrl);
?>
```

### 关键修改点
1. **白名单校验域名**：只允许可信支付服务商域名，避免嵌入恶意站点。  
2. **强制 HTTPS**：防止明文传输带来的中间人风险。  
3. **输出转义**：对 `src` 做 `htmlspecialchars`，防止属性注入。  
4. **增加 iframe 安全属性**：使用 `sandbox`、`referrerpolicy`、`allow` 限制能力范围。  
5. **增加 CSP**：通过 `Content-Security-Policy` 限制可嵌入的 frame 来源。  

如果你愿意，我还可以继续帮你补一版：
