```php
<?php
declare(strict_types=1);

/**
 * 用户注册处理
 * 修复点：
 * 1. 补充数据库连接
 * 2. 使用预处理语句，防止 SQL 注入
 * 3. 对用户名和密码做基础校验
 * 4. 密码使用 password_hash 加密存储，不能明文入库
 * 5. 增加请求方式校验与异常处理
 * 6. 返回统一 JSON 响应，便于前后端联调
 */

header('Content-Type: application/json; charset=utf-8');

// ====== 数据库配置 ======
$dbHost = '127.0.0.1';
$dbUser = 'root';
$dbPass = 'your_password';
$dbName = 'your_database';

// ====== 创建数据库连接 ======
$conn = new mysqli($dbHost, $dbUser, $dbPass, $dbName);
if ($conn->connect_error) {
    http_response_code(500);
    echo json_encode([
        'success' => false,
        'message' => '数据库连接失败'
    ], JSON_UNESCAPED_UNICODE);
    exit;
}
$conn->set_charset('utf8mb4');

/**
 * 注册用户
 */
function registerUser(mysqli $conn, string $username, string $password): array
{
    $username = trim($username);

    // ====== 参数校验 ======
    if ($username === '' || $password === '') {
        return [
            'success' => false,
            'message' => '用户名和密码不能为空'
        ];
    }

    if (mb_strlen($username) < 3 || mb_strlen($username) > 50) {
        return [
            'success' => false,
            'message' => '用户名长度必须在 3 到 50 个字符之间'
        ];
    }

    if (!preg_match('/^[a-zA-Z0-9_]+$/', $username)) {
        return [
            'success' => false,
            'message' => '用户名只能包含字母、数字和下划线'
        ];
    }

    if (strlen($password) < 6) {
        return [
            'success' => false,
            'message' => '密码长度不能少于 6 位'
        ];
    }

    // ====== 检查用户名是否已存在 ======
    $checkStmt = $conn->prepare('SELECT id FROM users WHERE username = ? LIMIT 1');
    if (!$checkStmt) {
        return [
            'success' => false,
            'message' => 'SQL 预处理失败：' . $conn->error
        ];
    }

    $checkStmt->bind_param('s', $username);
    $checkStmt->execute();
    $checkStmt->store_result();

    if ($checkStmt->num_rows > 0) {
        $checkStmt->close();
        return [
            'success' => false,
            'message' => '用户名已存在'
        ];
    }
    $checkStmt->close();

    // ====== 密码加密 ======
    $hashedPassword = password_hash($password, PASSWORD_DEFAULT);
    if ($hashedPassword === false) {
        return [
            'success' => false,
            'message' => '密码加密失败'
        ];
    }

    // ====== 插入用户 ======
    $stmt = $conn->prepare('INSERT INTO users (username, password) VALUES (?, ?)');
    if (!$stmt) {
        return [
            'success' => false,
            'message' => 'SQL 预处理失败：' . $conn->error
        ];
    }

    $stmt->bind_param('ss', $username, $hashedPassword);
    $result = $stmt->execute();

    if (!$result) {
        $error = $stmt->error;
        $stmt->close();
        return [
            'success' => false,
            'message' => '注册失败：' . $error
        ];
    }

    $userId = $stmt->insert_id;
    $stmt->close();

    return [
        'success' => true,
        'message' => '注册成功',
        'user_id' => $userId
    ];
}

// ====== 仅允许 POST 请求 ======
if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    http_response_code(405);
    echo json_encode([
        'success' => false,
        'message' => '仅支持 POST 请求'
    ], JSON_UNESCAPED_UNICODE);
    $conn->close();
    exit;
}

// ====== 获取请求参数 ======
$username = $_POST['username'] ?? '';
$password = $_POST['password'] ?? '';

// ====== 执行注册 ======
$response = registerUser($conn, $username, $password);

echo json_encode($response, JSON_UNESCAPED_UNICODE);

$conn->close();
?>
```

### 关键修改点
1. **修复 `$conn` 未定义问题**：补充了数据库连接代码。  
2. **防止 SQL 注入**：将字符串拼接 SQL 改为 **预处理语句**。  
3. **密码安全**：使用 `password_hash()` 加密后再存库，避免明文密码。  
4. **输入校验**：增加用户名、密码非空、长度、格式校验。  
5. **重复用户名检查**：注册前先查询用户名是否已存在。  
6. **请求与响应规范化**：限制为 POST 请求，并返回 JSON 结果。  

