        $this->courseId = $courseId;
        $this->title = $title;
        $this->content = $content;
        $this->teacherId = $teacherId;
    }
}

final class EducationPlatform
{
    /** @var array<int, User> */
    private array $users = [];

    /** @var array<int, Course> */
    private array $courses = [];

    /** @var array<int, array<int, bool>> studentId => [courseId => true] */
    private array $enrollments = [];

    public function addUser(int $id, string $username, string $role): void
    {
        if (isset($this->users[$id])) {
            throw new InvalidArgumentException("User ID {$id} already exists.");
        }

        $this->users[$id] = new User($id, $username, $role);
    }

    public function addCourse(int $courseId, string $title, string $content, int $teacherId): void
    {
        if (isset($this->courses[$courseId])) {
            throw new InvalidArgumentException("Course ID {$courseId} already exists.");
        }

        $teacher = $this->getUserById($teacherId);
        if ($teacher === null || $teacher->role !== Role::TEACHER) {
            throw new InvalidArgumentException("Teacher ID {$teacherId} is invalid or not a teacher.");
        }

        $this->courses[$courseId] = new Course($courseId, $title, $content, $teacherId);
    }

    public function enrollStudent(int $studentId, int $courseId): void
    {
        $student = $this->getUserById($studentId);
        if ($student === null || $student->role !== Role::STUDENT) {
            throw new InvalidArgumentException("User ID {$studentId} is invalid or not a student.");
        }

        if (!isset($this->courses[$courseId])) {
            throw new InvalidArgumentException("Course ID {$courseId} does not exist.");
        }

        $this->enrollments[$studentId][$courseId] = true;
    }

    public function getCourse(int $userId, int $courseId): ?Course
    {
        $user = $this->getUserById($userId);
        $course = $this->getCourseById($courseId);

        if ($user === null || $course === null) {
            return null;
        }

        if ($this->canAccessCourse($user, $course)) {
            return $course;
        }

        return null;
    }

    public function canAccessCourse(User $user, Course $course): bool
    {
        if ($user->role === Role::ADMIN) {
            return true;
        }

        if ($user->role === Role::TEACHER) {
            return $course->teacherId === $user->id;
        }

        if ($user->role === Role::STUDENT) {
            return isset($this->enrollments[$user->id][$course->courseId]);
        }

        return false;
    }

    private function getUserById(int $userId): ?User
    {
        return $this->users[$userId] ?? null;
    }

    private function getCourseById(int $courseId): ?Course
    {
        return $this->courses[$courseId] ?? null;
    }
}

/* =========================
   示例运行
   ========================= */
$platform = new EducationPlatform();

$platform->addUser(1, 'teacher_zhang', Role::TEACHER);
$platform->addUser(2, 'student_li', Role::STUDENT);
$platform->addUser(3, 'student_wang', Role::STUDENT);
$platform->addUser(4, 'admin_chen', Role::ADMIN);

$platform->addCourse(101, 'PHP 入门', '课程内容：变量、数组、函数', 1);
$platform->enrollStudent(2, 101);

function printCourseAccess(EducationPlatform $platform, int $userId, int $courseId): void
{
    $course = $platform->getCourse($userId, $courseId);
    if ($course !== null) {
        echo "User {$userId} can access course {$courseId}: {$course->title}" . PHP_EOL;
    } else {
        echo "User {$userId} cannot access course {$courseId}" . PHP_EOL;
    }
}

printCourseAccess($platform, 1, 101); // teacher owns course -> allow
printCourseAccess($platform, 2, 101); // enrolled student -> allow
printCourseAccess($platform, 3, 101); // not enrolled -> deny
printCourseAccess($platform, 4, 101); // admin -> allow
?>
```

关键修改点：
1. 修复了原始权限漏洞  
   - 原代码中 `isStudent($userId)` 只要是学生就能访问任意课程，这是严重越权。  
   - 现在改为：学生必须“已选课”才能访问课程。

2. 增加了角色校验  
   - 限定角色只能是 `student / teacher / admin`。  
   - 添加课程时校验 `teacherId` 必须是真实存在的教师。

3. 增加了选课关系  
   - 新增 `enrollStudent()`，通过 `$enrollments` 管理学生与课程的访问关系。

4. 优化了数据结构  
   - 用户和课程改为用 `id` 作为键存储，查找效率更高，避免每次 `foreach` 遍历。

5. 增强了健壮性  
   - 使用 `strict_types=1`、类型声明、重复 ID 检查、非法数据异常处理，减少隐藏 bug。

如果你愿意，我还可以继续帮你把这段代码升级成：
- 支持“作业提交权限控制”
- 支持“教师只能修改自己课程”
- 支持“课程视频/资料上传权限校验”
- 或者改造成更接近 Laravel/Symfony 的实际项目写法。

