response:
```php
<?php
declare(strict_types=1);

/**
 * 生成安全且唯一的文件名
 */
function generateUniqueFileName(string $originalFileName): string
{
    $extension = strtolower(pathinfo($originalFileName, PATHINFO_EXTENSION));
    $randomName = bin2hex(random_bytes(16)); // 更安全的唯一名

    return $extension !== ''
        ? $randomName . '.' . $extension
        : $randomName;
}

/**
 * 上传文件
 *
 * @param array $file $_FILES['file']
 * @param string $uploadDir 上传目录
 * @param array $allowedExtensions 允许的扩展名
 * @param int $maxFileSize 最大文件大小（字节）
 * @return array
 */
function uploadFile(
    array $file,
    string $uploadDir,
    array $allowedExtensions = ['jpg', 'jpeg', 'png', 'gif', 'pdf', 'doc', 'docx', 'mp4', 'txt'],
    int $maxFileSize = 10485760 // 10MB
): array {
    if (!isset($file['error'], $file['name'], $file['tmp_name'], $file['size'])) {
        return ['success' => false, 'message' => '无效的上传参数'];
    }

    if ($file['error'] !== UPLOAD_ERR_OK) {
        return ['success' => false, 'message' => '文件上传失败，错误码：' . $file['error']];
    }

    if ($file['size'] <= 0 || $file['size'] > $maxFileSize) {
        return ['success' => false, 'message' => '文件大小不合法或超出限制'];
    }

    $originalFileName = $file['name'];
    $extension = strtolower(pathinfo($originalFileName, PATHINFO_EXTENSION));

    if (!in_array($extension, $allowedExtensions, true)) {
        return ['success' => false, 'message' => '不支持的文件类型'];
    }

    if (!is_uploaded_file($file['tmp_name'])) {
        return ['success' => false, 'message' => '非法上传文件'];
    }

    if (!is_dir($uploadDir)) {
        if (!mkdir($uploadDir, 0755, true) && !is_dir($uploadDir)) {
            return ['success' => false, 'message' => '创建上传目录失败'];
        }
    }

    $uniqueFileName = generateUniqueFileName($originalFileName);
    $destination = rtrim($uploadDir, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR . $uniqueFileName;

    if (!move_uploaded_file($file['tmp_name'], $destination)) {
        return ['success' => false, 'message' => '保存文件失败'];
    }

    return [
        'success' => true,
        'message' => '文件上传成功',
        'original_name' => $originalFileName,
        'saved_name' => $uniqueFileName,
        'path' => $destination,
        'size' => $file['size'],
        'extension' => $extension,
    ];
}

/* =========================
   使用示例
   表单示例：
   <form method="post" enctype="multipart/form-data">
       <input type="file" name="upload_file">
       <button type="submit">上传</button>
   </form>
   ========================= */

if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_FILES['upload_file'])) {
    $result = uploadFile($_FILES['upload_file'], __DIR__ . '/uploads');

    header('Content-Type: application/json; charset=utf-8');
    echo json_encode($result, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
    exit;
}

// 单独测试文件名生成
$originalFileName = "example.jpg";
$uniqueFileName = generateUniqueFileName($originalFileName);
echo $uniqueFileName;
```

关键修改点：
1. 使用 `random_bytes()` + `bin2hex()` 替代 `uniqid()`，唯一性和安全性更好。
2. 增加完整上传流程：校验上传参数、错误码、文件大小、扩展名、非法上传检测。
3. 自动创建上传目录，避免目录不存在时报错。
4. 使用 `move_uploaded_file()` 安全保存文件。
5. 返回结构化结果，便于 CMS 后续接入数据库或接口响应。

