<?php
declare(strict_types=1);

/**
 * 密码不要使用“可逆加密”存储，应该使用单向哈希。
 * 推荐使用 PHP 内置 password_hash / password_verify。
 */

/**
 * 对用户密码进行安全哈希
 */
function hashPassword(string $password): string
{
    if ($password === '') {
        throw new InvalidArgumentException('密码不能为空');
    }

    // 默认使用当前 PHP 推荐算法（通常为 bcrypt / argon2）
    $hash = password_hash($password, PASSWORD_DEFAULT);

    if ($hash === false) {
        throw new RuntimeException('密码哈希失败');
    }

    return $hash;
}

/**
 * 验证用户输入密码是否正确
 */
function verifyPassword(string $password, string $hashedPassword): bool
{
    return password_verify($password, $hashedPassword);
}

// 示例：从表单获取密码
