    $password = $_POST['password'] ?? '';

    try {
        $hashedPassword = hashPassword($password);

        // 这里应将 $hashedPassword 存入数据库，而不是 echo 输出
        // 示例输出仅用于调试
        echo "密码哈希结果：" . htmlspecialchars($hashedPassword, ENT_QUOTES, 'UTF-8');

