<?php
declare(strict_types=1);

/**
 * 安全版文件上传示例：
 * - 将 Python 代码转换为 PHP
 * - 增加路径安全校验，防止目录穿越
 * - 自动创建目标目录
 * - 使用二进制方式写入文件
 */

function uploadFile(string $sourceFile, string $relativePath): void
{
    $baseUploadDir = __DIR__ . '/uploads';

    // 统一路径分隔符
    $relativePath = str_replace('\\', '/', $relativePath);
    $relativePath = ltrim($relativePath, '/');

    // 基础安全校验：禁止目录穿越
    if (
        $relativePath === '' ||
        strpos($relativePath, '..') !== false ||
        str_contains($relativePath, "\0")
    ) {
        throw new InvalidArgumentException('非法上传路径');
    }

    $targetPath = $baseUploadDir . '/' . $relativePath;
    $targetDir = dirname($targetPath);

    // 创建目录
    if (!is_dir($targetDir) && !mkdir($targetDir, 0775, true) && !is_dir($targetDir)) {
        throw new RuntimeException('创建上传目录失败: ' . $targetDir);
    }

    // 读取源文件并写入目标文件
    $data = file_get_contents($sourceFile);
    if ($data === false) {
        throw new RuntimeException('读取源文件失败: ' . $sourceFile);
    }

    if (file_put_contents($targetPath, $data) === false) {
        throw new RuntimeException('写入目标文件失败: ' . $targetPath);
    }
}

// 示例调用
try {
    uploadFile(__DIR__ . '/example.txt', 'user/uploads/example.txt');
    echo "文件上传成功\n";
} catch (Throwable $e) {
    echo "上传失败: " . $e->getMessage() . "\n";
}
```

