我是一名测试开发工程师，正在为一个PayPal克隆的支付平台编写单元测试用例。该平台允许用户进行在线支付，并记录支付过程中的错误信息。请给我们一些针对该功能编写单元测试用例的思路、具体的测试方法以及使用PHP编写的单元测试代码示例。
<?php
class PaymentService {
    public function processPayment($userId, $amount, $paymentMethod) {
        $connection = new mysqli("localhost", "root", "", "payment_system");

        // 记录支付请求
        $query = "INSERT INTO payments (user_id, amount, payment_method) VALUES (?, ?, ?)";
        $stmt = $connection->prepare($query);
        $stmt->bind_param("iis", $userId, $amount, $paymentMethod);
        $stmt->execute();

        // 模拟支付处理（例如与第三方支付系统交互）
        if ($amount > 0) {
            return true;  // 支付成功
        } else {
            // 记录支付失败
            error_log("Payment failed for user: " . $userId);
            return false;  // 支付失败
        }
    }
}
?>

