## 可运行的 PHP 安全示例

### `index.php`

```php
<?php
declare(strict_types=1);

/**
 * 安全的外部资源加载器：
 * - 仅允许白名单域名
 * - 必须提供 SRI
 * - 自动输出安全属性
 */

$allowedHosts = [
    'cdn.jsdelivr.net',
    'cdnjs.cloudflare.com',
    'code.jquery.com',
];

$resources = [
    [
        'type' => 'css',
        'url'  => 'https://cdnjs.cloudflare.com/ajax/libs/normalize/8.0.1/normalize.min.css',
        'integrity' => 'sha512-oHDEc8Xed0A2G6K6A4J8V4aHc4W2KIiMzFxLpy0X58F3RJTJ63HgNbUsM8c7kwh28ykVfoCEN0N7LxyzKDn5ZA==',
    ],
    [
        'type' => 'js',
        'url'  => 'https://code.jquery.com/jquery-3.7.1.min.js',
        'integrity' => 'sha256-/JqT3SQfawRcv/BIHPThkBvs0OEvtFFmqPF/lYI/Cxo=',
    ],
];

/**
 * 校验 URL 是否属于允许的主机
 */
function isAllowedResource(string $url, array $allowedHosts): bool
{
    $parts = parse_url($url);
    if (!$parts || empty($parts['scheme']) || empty($parts['host'])) {
        return false;
    }

    if (!in_array($parts['scheme'], ['https'], true)) {
        return false;
    }

    return in_array(strtolower($parts['host']), $allowedHosts, true);
}

/**
 * 生成安全的 HTML 标签
 */
function renderResourceTag(array $resource, array $allowedHosts): string
{
    $type = $resource['type'] ?? '';
    $url = $resource['url'] ?? '';
    $integrity = $resource['integrity'] ?? '';

    if (!$type || !$url || !$integrity) {
        return "<!-- blocked: missing required fields -->";
    }

    if (!isAllowedResource($url, $allowedHosts)) {
        return "<!-- blocked: resource host not allowed -->";
    }

    $safeUrl = htmlspecialchars($url, ENT_QUOTES, 'UTF-8');
    $safeIntegrity = htmlspecialchars($integrity, ENT_QUOTES, 'UTF-8');

    if ($type === 'css') {
        return sprintf(
            '<link rel="stylesheet" href="%s" integrity="%s" crossorigin="anonymous">',
            $safeUrl,
            $safeIntegrity
        );
    }

    if ($type === 'js') {
        return sprintf(
            '<script src="%s" integrity="%s" crossorigin="anonymous"></script>',
            $safeUrl,
            $safeIntegrity
        );
    }

    return "<!-- blocked: unsupported resource type -->";
}

// 设置基础 CSP
header("Content-Security-Policy: default-src 'self'; script-src 'self' https://code.jquery.com https://cdnjs.cloudflare.com https://cdn.jsdelivr.net; style-src 'self' https://cdnjs.cloudflare.com https://cdn.jsdelivr.net; object-src 'none'; base-uri 'self'; frame-ancestors 'none';");
header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: strict-origin-when-cross-origin');
?>
<!doctype html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>安全加载外部资源示例</title>

    <?php foreach ($resources as $resource): ?>
        <?= renderResourceTag($resource, $allowedHosts) . PHP_EOL; ?>
    <?php endforeach; ?>
</head>
<body>
    <h1>安全加载外部 JS/CSS</h1>
    <p>此页面仅允许带 SRI 且来自白名单域名的外部资源。</p>

    <script>
        if (window.jQuery) {
            console.log('jQuery loaded safely:', jQuery.fn.jquery);
        }
    </script>
</body>
</html>
```

