#!/usr/bin/env bash
set -euo pipefail

CSV_FILE="${CSV_FILE:-financial_data.csv}"
TEMP_FILE="$(mktemp)"

cleanup() {
    rm -f "$TEMP_FILE"
}
trap cleanup EXIT

init_csv() {
    if [[ ! -f "$CSV_FILE" ]]; then
        printf 'Date,Type,Description,Amount\n' > "$CSV_FILE"
    fi
}

calculate_total() {
    awk -F',' '
        NR == 1 { next }
        $1 == "Total" { next }
        NF >= 4 {
            gsub(/^[ \t]+|[ \t]+$/, "", $4)
            if ($4 ~ /^-?[0-9]+([.][0-9]+)?$/) {
                sum += $4
            }
        }
        END {
            printf "%.2f\n", sum + 0
        }
    ' "$CSV_FILE"
}

insert_record() {
    local date="$1"
    local type="$2"
    local description="$3"
    local amount="$4"

    if [[ ! "$amount" =~ ^-?[0-9]+([.][0-9]+)?$ ]]; then
        echo "错误：Amount 必须是数字，当前值: $amount" >&2
        exit 1
    fi

    printf '%s,%s,%s,%s\n' "$date" "$type" "$description" "$amount" >> "$CSV_FILE"
}

update_total_amount() {
    local total
    total="$(calculate_total)"

    awk -F',' -v total="$total" '
        BEGIN { OFS="," }
        NR == 1 { print; next }
        $1 == "Total" { next }
        { print }
        END { print "Total", "", "", total }
    ' "$CSV_FILE" > "$TEMP_FILE"

    mv "$TEMP_FILE" "$CSV_FILE"
    TEMP_FILE="$(mktemp)"
}

main() {
    init_csv

    # 示例：插入一条新的财务记录
    insert_record "2024-12-01" "Income" "Salary" "5000"

    update_total_amount

    echo "财务总金额已更新：$(calculate_total)"
}

main "$@"
