#!/usr/bin/env bash
set -Eeuo pipefail

# =========================
# 配置
# =========================
OUTPUT_DIR="${OUTPUT_DIR:-product_pages}"
DEFAULT_CSS="${DEFAULT_CSS:-./default.css}"

# 优先使用第一个参数作为 CSS 路径，否则使用默认值
CSS_PATH="${1:-$DEFAULT_CSS}"

# 合法商品示例数据：名称|图片|描述|价格
products=(
  "ProductA|/images/product_a.jpg|高性能运动水壶，适合日常健身与户外使用。|99.99"
  "ProductB|/images/product_b.jpg|轻便双肩包，适合通勤、旅行和短途出行。|199.99"
)

# =========================
# 工具函数
# =========================
log() {
  printf '[INFO] %s\n' "$*"
}

warn() {
  printf '[WARN] %s\n' "$*" >&2
}

die() {
  printf '[ERROR] %s\n' "$*" >&2
  exit 1
}

escape_html() {
  local s="${1:-}"
  s=${s//&/&amp;}
  s=${s//</&lt;}
  s=${s//>/&gt;}
  s=${s//\"/&quot;}
  s=${s//\'/&#39;}
  printf '%s' "$s"
}

slugify_filename() {
  local name="${1:-}"
  name="${name// /_}"
  name="${name//\//_}"
  name="${name//\\/_}"
  name="${name//:/_}"
  name="${name//|/_}"
  printf '%s' "$name"
}

validate_price() {
  local price="${1:-}"
  [[ "$price" =~ ^[0-9]+([.][0-9]{1,2})?$ ]]
}

html_header() {
  local title="$1"
  local escaped_title
  escaped_title="$(escape_html "$title")"

  cat <<EOF
<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escaped_title}</title>
  <link rel="stylesheet" href="${CSS_PATH}">
  <style>
    * { box-sizing: border-box; }
    body {
      font-family: Arial, sans-serif;
      margin: 0;
      padding: 24px;
      background-color: #f4f4f4;
      color: #333;
    }
    .container {
      width: min(900px, 100%);
      margin: 0 auto;
      background-color: #fff;
      padding: 24px;
      border-radius: 10px;
      box-shadow: 0 2px 12px rgba(0,0,0,0.08);
    }
    h1 {
      text-align: center;
      margin-top: 0;
    }
    .product img {
      max-width: 100%;
      height: auto;
      display: block;
      margin: 0 auto 16px;
      border-radius: 8px;
    }
    .description {
      line-height: 1.7;
      margin-bottom: 12px;
    }
    .price {
      font-size: 24px;
      color: #e74c3c;
      font-weight: bold;
    }
  </style>
</head>
<body>
  <div class="container">
    <h1>${escaped_title}</h1>
EOF
}

html_footer() {
  cat <<'EOF'
  </div>
</body>
</html>
EOF
}

generate_product_page() {
  local name="$1"
  local image="$2"
  local description="$3"
  local price="$4"

  local safe_name safe_image safe_description output_html
  safe_name="$(escape_html "$name")"
  safe_image="$(escape_html "$image")"
  safe_description="$(escape_html "$description")"

  output_html="${OUTPUT_DIR}/$(slugify_filename "$name").html"

  {
    html_header "$name"
    cat <<EOF
    <div class="product">
      <img src="${safe_image}" alt="${safe_name}">
      <p class="description">${safe_description}</p>
      <p class="price">￥${price}</p>
    </div>
EOF
    html_footer
  } > "$output_html"

  log "已生成 HTML 文件: $output_html"
}

main() {
  mkdir -p "$OUTPUT_DIR"

  if [[ ! -f "$CSS_PATH" ]]; then
    warn "CSS 文件不存在：$CSS_PATH，页面仍会生成，但样式链接可能无效。"
  fi

  local product name image description price
  for product in "${products[@]}"; do
    IFS='|' read -r name image description price <<< "$product"

    [[ -n "${name:-}" ]] || { warn "跳过无效商品数据：名称为空"; continue; }
    [[ -n "${image:-}" ]] || { warn "跳过商品 [$name]：图片为空"; continue; }
    [[ -n "${description:-}" ]] || { warn "跳过商品 [$name]：描述为空"; continue; }

    if ! validate_price "$price"; then
      warn "跳过商品 [$name]：价格格式无效 ($price)"
      continue
    fi

    generate_product_page "$name" "$image" "$description" "$price"
  done

  log "所有产品页面已生成完毕。"
}

main "$@"
