```cpp
#include <iostream>
#include <string>
#include <vector>
#include <array>
#include <string_view>

class ActivityTracker {
private:
    static constexpr std::size_t DAYS_PER_WEEK = 7;

    struct DailyActivity {
        std::string activityName;
        std::array<int, DAYS_PER_WEEK> durationMinutes{}; // 自动零初始化

        explicit DailyActivity(std::string name) noexcept
            : activityName(std::move(name)) {}
    };

    std::vector<DailyActivity> activities;

public:
    void reserveActivities(std::size_t count) {
        activities.reserve(count);
    }

    void addActivity(std::string_view activityName) {
        activities.emplace_back(std::string(activityName)); // 避免额外临时对象
    }

    bool setActivityDuration(std::size_t activityIndex, std::size_t day, int minutes) {
        if (activityIndex >= activities.size() || day >= DAYS_PER_WEEK || minutes < 0) {
            return false;
        }
        activities[activityIndex].durationMinutes[day] = minutes;
        return true;
    }

    void displayWeeklyActivity() const {
        for (const auto& activity : activities) {
            std::cout << "Activity: " << activity.activityName << '\n';
            for (std::size_t day = 0; day < DAYS_PER_WEEK; ++day) {
                std::cout << "Day " << (day + 1)
                          << ": " << activity.durationMinutes[day]
                          << " minutes\n";
            }
            std::cout << '\n';
        }
    }
};

int main() {
    ActivityTracker tracker;
    tracker.reserveActivities(2);

    tracker.addActivity("Running");
    tracker.addActivity("Cycling");

    tracker.setActivityDuration(0, 0, 30);
    tracker.setActivityDuration(0, 1, 45);
    tracker.setActivityDuration(1, 0, 60);
    tracker.setActivityDuration(1, 2, 40);

    tracker.displayWeeklyActivity();

    return 0;
}
```

关键优化点：
1. **修复未初始化内存问题**：原来的 `int durationMinutes[7]` 未初始化，输出是未定义行为；改为 `std::array<int, 7> durationMinutes{}` 自动置零。
2. **减少拷贝开销**：`addActivity` 使用 `emplace_back` 直接构造对象，避免临时对象和额外拷贝。
3. **支持预分配容量**：增加 `reserveActivities()`，减少 `vector` 扩容带来的性能损耗。
4. **提升接口效率**：`addActivity` 使用 `std::string_view`，减少不必要的字符串构造成本。
5. **增强可维护性**：用 `constexpr DAYS_PER_WEEK` 替代硬编码 `7`，更清晰也更安全。
6. **补充数据写入接口**：新增 `setActivityDuration()`，让数据结构真正可用，并带边界检查。

