#include <algorithm>
#include <cctype>
#include <iostream>
#include <random>
#include <string>
#include <vector>

class ChatBot {
public:
    ChatBot()
        : responses{
              "你好，很高兴和你交流。",
              "请再详细描述一下你的问题。",
              "我在这里帮助你，你可以继续说。",
              "这是个不错的话题，我们可以一起看看。",
              "如果你愿意，我可以尝试给你一些建议。"},
          rng(std::random_device{}()) {}

    std::string generateResponse(const std::string& userInput) {
        std::string normalized = normalizeInput(userInput);

        if (normalized.empty()) {
            return "你似乎还没有输入内容，请说点什么吧。";
        }

        if (isGreeting(normalized)) {
            return getRandomResponse();
        }

        return "我明白了。你可以再补充一些细节，这样我能更好地帮助你。";
    }

private:
    std::vector<std::string> responses;
    std::mt19937 rng;

    static std::string normalizeInput(const std::string& input) {
        std::string result;

        auto begin = input.begin();
        auto end = input.end();

        while (begin != end && std::isspace(static_cast<unsigned char>(*begin))) {
            ++begin;
        }

        while (begin != end && std::isspace(static_cast<unsigned char>(*(end - 1)))) {
            --end;
        }

        result.assign(begin, end);

        std::transform(result.begin(), result.end(), result.begin(),
                       [](unsigned char c) { return static_cast<char>(std::tolower(c)); });

        return result;
    }

    static bool isGreeting(const std::string& input) {
        static const std::vector<std::string> greetings = {"hello", "hi", "hey"};
        return std::find(greetings.begin(), greetings.end(), input) != greetings.end();
    }

    std::string getRandomResponse() {
        std::uniform_int_distribution<std::size_t> dist(0, responses.size() - 1);
        return responses[dist(rng)];
    }
};

int main() {
    ChatBot bot;
    std::string userInput;

    std::cout << "聊天机器人已启动，输入 quit 退出。\n";

    while (true) {
        std::cout << "请输入你想说的话：";
        if (!std::getline(std::cin, userInput)) {
            std::cout << "\n输入流结束，程序退出。\n";
            break;
        }

        std::string normalized = userInput;
        std::transform(normalized.begin(), normalized.end(), normalized.begin(),
                       [](unsigned char c) { return static_cast<char>(std::tolower(c)); });

        if (normalized == "quit" || normalized == "exit") {
            std::cout << "再见！\n";
            break;
        }

        std::cout << bot.generateResponse(userInput) << '\n';
    }

    return 0;
}
