    std::vector<std::string> generate(std::size_t num_statements) {
        std::vector<std::string> statements;
        statements.reserve(num_statements); // 预分配，减少扩容

        for (std::size_t i = 0; i < num_statements; ++i) {
            statements.emplace_back(generate_one());
        }
        return statements;
    }

private:
    std::string generate_one() {
        const int length = length_dist_(rng_);

        // 粗略预估容量，减少字符串拼接时的重复分配
        std::size_t estimated_size = 0;
        for (int i = 0; i < length; ++i) {
            estimated_size += kTestKeywords[keyword_dist_(rng_)].size() + 1;
        }

        std::string statement;
        statement.reserve(estimated_size);

        // 重新生成，避免上面预估时消耗随机序列带来的逻辑混乱
        for (int i = 0; i < length; ++i) {
            if (!statement.empty()) {
                statement.push_back(' ');
            }
            statement += kTestKeywords[keyword_dist_(rng_)];
        }

        return statement;
    }

private:
    std::mt19937 rng_; // 比 default_random_engine 更稳定、常用
    std::uniform_int_distribution<int> length_dist_;
    std::uniform_int_distribution<int> keyword_dist_;
};

std::vector<std::string> bulk_generate_text(std::size_t num_statements) {
    auto start_time = std::chrono::steady_clock::now();

    TextGenerator generator;
    auto statements = generator.generate(num_statements);

    auto end_time = std::chrono::steady_clock::now();
    std::chrono::duration<double> elapsed = end_time - start_time;

    std::cout << "Generated " << num_statements
              << " test text statements in "
              << elapsed.count() << " seconds.\n";

    return statements;
}

int main() {
    constexpr std::size_t kNumStatements = 10000;
    auto statements = bulk_generate_text(kNumStatements);

    // 示例输出前5条，避免大量打印影响性能
    std::cout << "Preview:\n";
    for (std::size_t i = 0; i < std::min<std::size_t>(5, statements.size()); ++i) {
        std::cout << i + 1 << ": " << statements[i] << '\n';
    }

    return 0;
}
```

