```cpp
#include <iostream>
#include <string>
#include <cstring>

// 模拟表情符号类
class Emoji {
public:
    Emoji(const char* data, size_t length) : data(nullptr), length(length) {
        if (data == nullptr || length == 0) {
            this->length = 0;
            return;
        }

        this->data = new char[length];
        std::memcpy(this->data, data, length);
    }

    ~Emoji() {
        delete[] data;
    }

    // 禁止浅拷贝，避免重复释放
    Emoji(const Emoji&) = delete;
    Emoji& operator=(const Emoji&) = delete;

    // 支持移动语义
    Emoji(Emoji&& other) noexcept : data(other.data), length(other.length) {
        other.data = nullptr;
        other.length = 0;
    }

    Emoji& operator=(Emoji&& other) noexcept {
        if (this != &other) {
            delete[] data;
            data = other.data;
            length = other.length;
            other.data = nullptr;
            other.length = 0;
        }
        return *this;
    }

    std::string toString() const {
        if (data == nullptr || length == 0) {
            return "";
        }
        return std::string(data, length);
    }

    void display() const {
        if (data != nullptr && length > 0) {
            std::cout.write(data, length);
            std::cout << "\n";
        } else {
            std::cerr << "Invalid emoji data.\n";
        }
    }

private:
    char* data;
    size_t length;
};

// 模拟用户消息类
class UserMessage {
public:
    void setMessage(const std::string& message) {
        this->message = message;
    }

    void setMessage(const Emoji& emoji) {
        this->message = emoji.toString();
    }

    void displayMessage() const {
        if (!message.empty()) {
            std::cout << "Message: " << message << "\n";
        } else {
            std::cerr << "No message to display.\n";
        }
    }

private:
    std::string message;
};

int main() {
    // 创建表情符号对象
    Emoji emoji(":)", 2);

    // 用户消息对象
    UserMessage userMessage;

    // 正确设置消息内容，而不是把对象内存当作字符串
    userMessage.setMessage(emoji);

    // 显示用户消息
    userMessage.displayMessage();

    // 正常显示表情符号
    emoji.display();

    return 0;
}
```

