#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

class SecurityUtil {
public:
    // 对输出内容做 HTML 转义，防止注入
    static std::string escapeHtml(const std::string& input) {
        std::string result;
        result.reserve(input.size());

        for (char c : input) {
            switch (c) {
                case '&': result += "&amp;"; break;
                case '<': result += "&lt;"; break;
                case '>': result += "&gt;"; break;
                case '"': result += "&quot;"; break;
                case '\'': result += "&#39;"; break;
                default: result += c; break;
            }
        }
        return result;
    }

    // 仅允许 https 且域名在白名单中
    static bool isTrustedUrl(const std::string& url) {
        static const std::vector<std::string> trustedDomains = {
            "https://trusted-hospital.com/",
            "https://records.healthcare.gov/",
            "https://patient-portal.example.com/"
        };

        for (const auto& domain : trustedDomains) {
            if (url.rfind(domain, 0) == 0) { // 前缀匹配
                return true;
            }
        }
        return false;
    }

    // 简单检测是否包含危险 HTML 标签
    static bool containsHtmlTag(const std::string& input) {
        return input.find('<') != std::string::npos || input.find('>') != std::string::npos;
    }
};

class MedicalRecord {
public:
    bool setTrustedIframeUrl(const std::string& url) {
        if (!SecurityUtil::isTrustedUrl(url)) {
            std::cerr << "[ERROR] Untrusted iframe URL rejected: " << url << "\n";
            iframeUrl.clear();
            return false;
        }
        iframeUrl = url;
        return true;
    }

    void setRecordText(const std::string& text) {
        recordText = SecurityUtil::escapeHtml(text);
    }

    void displayRecord() const {
        std::cout << "Medical Record Text: " << recordText << "\n";
        if (!iframeUrl.empty()) {
            std::cout << "Embedded Trusted Resource: " << iframeUrl << "\n";
        } else {
            std::cout << "Embedded Trusted Resource: none\n";
        }
    }

private:
    std::string recordText;
    std::string iframeUrl;
};

class MedicalRecordPage {
public:
    bool addContent(const std::string& content) {
        if (SecurityUtil::containsHtmlTag(content)) {
            std::cerr << "[ERROR] HTML content is not allowed in medical record page content.\n";
            return false;
        }
        this->content = SecurityUtil::escapeHtml(content);
        return true;
    }

    void displayPage() const {
        std::cout << "Medical Record Page Content: " << content << "\n";
    }

private:
    std::string content;
};

int main() {
    MedicalRecord medicalRecord;

    // 安全文本内容
    medicalRecord.setRecordText("Patient summary: blood pressure stable.");

    // 恶意 URL：会被拒绝
    medicalRecord.setTrustedIframeUrl("http://malicious.com/steal-data");

    // 合法白名单 URL：允许
    medicalRecord.setTrustedIframeUrl("https://trusted-hospital.com/viewer/report123");

    medicalRecord.displayRecord();

    MedicalRecordPage medicalRecordPage;

    // 正常内容
