#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define UPLOAD_FOLDER "./uploads"
#define MAX_PATH_LEN 512
#define MAX_FILENAME_LEN 255

typedef enum {
    UPLOAD_OK = 0,
    UPLOAD_ERR_INVALID_NAME,
    UPLOAD_ERR_INVALID_FORMAT,
    UPLOAD_ERR_PORTRAIT_RISK
} UploadResult;

/* 转小写比较，兼容 .JPG / .PNG */
static int str_case_equal(const char *a, const char *b) {
    while (*a && *b) {
        if (tolower((unsigned char)*a) != tolower((unsigned char)*b)) {
            return 0;
        }
        a++;
        b++;
    }
    return *a == '\0' && *b == '\0';
}

/* 仅允许安全文件名，防止路径穿越 */
static int is_safe_filename(const char *filename) {
    size_t len;

    if (filename == NULL || *filename == '\0') {
        return 0;
    }

    len = strlen(filename);
    if (len == 0 || len > MAX_FILENAME_LEN) {
        return 0;
    }

    if (strstr(filename, "..") != NULL || strchr(filename, '/') != NULL || strchr(filename, '\\') != NULL) {
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)filename[i];
        if (!(isalnum(c) || c == '.' || c == '_' || c == '-')) {
            return 0;
        }
    }

    return 1;
}

/* 文件扩展名检查 */
static int allowed_file(const char *filename) {
    const char *ext = strrchr(filename, '.');
    if (!ext) {
        return 0;
    }

    return str_case_equal(ext, ".jpg") ||
           str_case_equal(ext, ".jpeg") ||
           str_case_equal(ext, ".png");
}

/* 简单的高风险命名拦截示例 */
static int has_portrait_risk(const char *filename) {
    if (filename == NULL) {
        return 0;
    }

    /* 示例规则：命名中包含 celebrity_name 视为高风险 */
    return strstr(filename, "celebrity_name") != NULL;
}

/* 上传图片函数 */
static UploadResult upload_image(const char *filename, char *saved_path, size_t saved_path_size) {
    int written;

    if (!is_safe_filename(filename)) {
        return UPLOAD_ERR_INVALID_NAME;
    }

    if (!allowed_file(filename)) {
        return UPLOAD_ERR_INVALID_FORMAT;
    }

    if (has_portrait_risk(filename)) {
        return UPLOAD_ERR_PORTRAIT_RISK;
    }

    written = snprintf(saved_path, saved_path_size, "%s/%s", UPLOAD_FOLDER, filename);
    if (written < 0 || (size_t)written >= saved_path_size) {
        return UPLOAD_ERR_INVALID_NAME;
    }

    /* 这里只做模拟，不实际写文件 */
    return UPLOAD_OK;
}

/* 展示广告的函数：仅展示已通过校验的图片 */
static void display_ad_image(const char *approved_image_path) {
    if (approved_image_path == NULL || *approved_image_path == '\0') {
        printf("No approved ad image available for display.\n");
        return;
    }

    printf("Displaying approved ad image: %s\n", approved_image_path);
}

static void print_upload_result(const char *filename, UploadResult result, const char *path) {
    switch (result) {
        case UPLOAD_OK:
            printf("Image '%s' uploaded successfully to '%s'.\n", filename, path);
            break;
        case UPLOAD_ERR_INVALID_NAME:
            printf("Upload failed for '%s': invalid or unsafe filename.\n", filename);
            break;
        case UPLOAD_ERR_INVALID_FORMAT:
            printf("Upload failed for '%s': only .jpg, .jpeg, .png are allowed.\n", filename);
            break;
        case UPLOAD_ERR_PORTRAIT_RISK:
            printf("Upload failed for '%s': potential portrait-rights risk detected.\n", filename);
            break;
        default:
            printf("Upload failed for '%s': unknown error.\n", filename);
            break;
    }
}

int main(void) {
    char approved_path[MAX_PATH_LEN] = {0};
    char temp_path[MAX_PATH_LEN] = {0};
    UploadResult result;

    /* 模拟上传合法图片 */
    result = upload_image("user_ad_image.jpg", temp_path, sizeof(temp_path));
    print_upload_result("user_ad_image.jpg", result, temp_path);
    if (result == UPLOAD_OK) {
        strncpy(approved_path, temp_path, sizeof(approved_path) - 1);
        approved_path[sizeof(approved_path) - 1] = '\0';
    }

    /* 模拟上传高风险图片 */
    memset(temp_path, 0, sizeof(temp_path));
    result = upload_image("celebrity_name_ad.jpg", temp_path, sizeof(temp_path));
    print_upload_result("celebrity_name_ad.jpg", result, temp_path);

    /* 仅展示审核通过的广告图 */
    display_ad_image(approved_path);

    return 0;
}
