```cpp
#include <atomic>
#include <chrono>
#include <iostream>
#include <thread>

using namespace std;

class EmbeddedSystem {
private:
    // 用 atomic 替代 volatile，保证并发场景下的可见性与原子性
    atomic<bool> interrupt_flag;
    atomic<bool> running;

public:
    EmbeddedSystem() : interrupt_flag(false), running(true) {}

    // 模拟硬件外部中断服务程序（ISR）
    void externalInterruptServiceRoutine() {
        // 原子读取并清除中断标志，避免重复处理中断
        if (interrupt_flag.exchange(false, memory_order_acq_rel)) {
            cout << "Interrupt handled, interrupt flag cleared." << endl;
        }
    }

    // 模拟硬件中断触发
    void triggerInterrupt() {
        interrupt_flag.store(true, memory_order_release);
    }

    // 停止主循环
    void stop() {
        running.store(false, memory_order_release);
    }

    // 模拟主系统任务
    void mainSystemLoop() {
        while (running.load(memory_order_acquire)) {
            if (interrupt_flag.load(memory_order_acquire)) {
                externalInterruptServiceRoutine();
            } else {
                cout << "Main system running..." << endl;
                this_thread::sleep_for(chrono::milliseconds(500));
            }
        }
    }
};

int main() {
    EmbeddedSystem system;

    thread mainLoopThread([&system]() {
        system.mainSystemLoop();
    });

    this_thread::sleep_for(chrono::seconds(1));
    system.triggerInterrupt();

    this_thread::sleep_for(chrono::seconds(2));
    system.triggerInterrupt();

    this_thread::sleep_for(chrono::seconds(2));
    system.stop();

    mainLoopThread.join();
    return 0;
}
