## 优化后代码

```cpp
#include <iostream>
#include <string>
#include <vector>

// 将用户评论做 HTML 转义，防止在网页上下文中触发 XSS
std::string htmlEscape(const std::string& input) {
    std::string escaped;
    escaped.reserve(input.size());

    for (unsigned char c : input) {
        switch (c) {
            case '<': escaped += "&lt;"; break;
            case '>': escaped += "&gt;"; break;
            case '&': escaped += "&amp;"; break;
            case '"': escaped += "&quot;"; break;
            case '\'': escaped += "&#39;"; break;
            default: escaped += static_cast<char>(c); break;
        }
    }
    return escaped;
}

// 模拟“直接输出到 HTML 页面”的危险行为
void unsafeDisplayComment(const std::string& comment) {
    std::cout << "[UNSAFE HTML OUTPUT] " << comment << '\n';
}

// 模拟“经过转义后输出到 HTML 页面”的安全行为
void safeDisplayComment(const std::string& comment) {
    std::cout << "[SAFE HTML OUTPUT] " << htmlEscape(comment) << '\n';
}

// 简单的风险检测：用于日志/测试提示，不替代真正的安全策略
bool mayContainHtmlOrScript(const std::string& comment) {
    static const std::vector<std::string> suspiciousPatterns = {
        "<script", "</script", "javascript:", "onerror=", "onload=", "<img", "<iframe", "<svg"
    };

    for (const auto& pattern : suspiciousPatterns) {
        if (comment.find(pattern) != std::string::npos) {
            return true;
        }
    }
    return false;
}

void testStoredXSSProtection() {
    std::cout << "=== Testing Stored XSS Protection ===\n\n";

    const std::vector<std::string> comments = {
        "I love this platform!",
        "<b>Breaking news!</b>",
        "<script>alert('XSS Attack');</script><a href='http://example.com'>Click me</a>",
        "\" onclick=\"alert('xss')",
        "Nice article & great insights"
    };

    for (const auto& comment : comments) {
        std::cout << "Original: " << comment << '\n';

        if (mayContainHtmlOrScript(comment)) {
            std::cout << "Risk hint: suspicious HTML/script-like content detected.\n";
        } else {
