    std::time_t now = std::time(nullptr);

    // 转换为本地时间
    std::tm* ltm = std::localtime(&now);

    // 判空，避免 localtime 返回空指针导致程序崩溃
    if (ltm == nullptr) {
        std::cerr << "获取本地时间失败！" << std::endl;
