#include <iostream>
#include <vector>
#include <limits>
#include <iomanip>
#include <string>
#include <algorithm>

using namespace std;

// 定义一个结构体来存储用户的运动数据
struct ActivityData {
    int steps{};
    double distance{};         // 单位：公里
    double caloriesBurned{};   // 单位：卡路里
};

// 安全读取整数
int readInt(const string& prompt, int minValue = 0) {
    int value;
    while (true) {
        cout << prompt;
        if (cin >> value && value >= minValue) {
            return value;
        }
        cout << "输入无效，请输入大于等于 " << minValue << " 的整数。\n";
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }
}

// 安全读取浮点数
double readDouble(const string& prompt, double minValue = 0.0) {
    double value;
    while (true) {
        cout << prompt;
        if (cin >> value && value >= minValue) {
            return value;
        }
        cout << "输入无效，请输入大于等于 " << minValue << " 的数字。\n";
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }
}

// 模拟从用户接收输入并保存活动数据
ActivityData safeRecordActivity() {
    ActivityData data;
    data.steps = readInt("请输入步数: ", 0);
    data.distance = readDouble("请输入距离(公里): ", 0.0);
    data.caloriesBurned = readDouble("请输入消耗卡路里: ", 0.0);

    cout << "活动数据记录成功！\n";
    return data;
}

// 显示单条活动数据
void printActivity(const ActivityData& data, size_t index) {
    cout << "记录 #" << index + 1
         << " | 步数: " << data.steps
         << " | 距离: " << fixed << setprecision(2) << data.distance << " km"
         << " | 卡路里: " << fixed << setprecision(2) << data.caloriesBurned
         << '\n';
}

// 显示所有历史记录
void showHistory(const vector<ActivityData>& records) {
    if (records.empty()) {
        cout << "暂无历史数据。\n";
        return;
    }

    cout << "\n===== 历史活动记录 =====\n";
    for (size_t i = 0; i < records.size(); ++i) {
        printActivity(records[i], i);
    }
}

// 统计汇总
void showSummary(const vector<ActivityData>& records) {
    if (records.empty()) {
        cout << "暂无可统计的数据。\n";
        return;
    }

    int totalSteps = 0;
    double totalDistance = 0.0;
    double totalCalories = 0.0;

    for (const auto& r : records) {
        totalSteps += r.steps;
        totalDistance += r.distance;
        totalCalories += r.caloriesBurned;
    }

    cout << "\n===== 数据汇总 =====\n";
    cout << "总记录数: " << records.size() << '\n';
    cout << "总步数: " << totalSteps << '\n';
    cout << "总距离: " << fixed << setprecision(2) << totalDistance << " km\n";
    cout << "总卡路里: " << fixed << setprecision(2) << totalCalories << '\n';
    cout << "平均步数: " << totalSteps / records.size() << '\n';
    cout << "平均距离: " << fixed << setprecision(2) << totalDistance / records.size() << " km\n";
    cout << "平均卡路里: " << fixed << setprecision(2) << totalCalories / records.size() << '\n';
}

// 简单文本图表
void showChart(const vector<ActivityData>& records) {
    if (records.empty()) {
        cout << "暂无可视化数据。\n";
        return;
    }

    cout << "\n===== 步数可视化图表(每50步一个*) =====\n";
    for (size_t i = 0; i < records.size(); ++i) {
        int stars = records[i].steps / 50;
        stars = min(stars, 100); // 防止输出过长
        cout << "记录 #" << i + 1 << " ";
        for (int j = 0; j < stars; ++j) {
            cout << '*';
        }
        cout << " (" << records[i].steps << "步)\n";
    }
}

// 菜单
void showMenu() {
    cout << "\n===== 移动健康应用 =====\n";
    cout << "1. 记录活动数据\n";
    cout << "2. 查看历史数据\n";
    cout << "3. 查看统计汇总\n";
    cout << "4. 查看步数图表\n";
    cout << "0. 退出\n";
    cout << "请选择: ";
}

int main() {
    vector<ActivityData> records;
    int choice;

    while (true) {
        showMenu();
        if (!(cin >> choice)) {
            cout << "输入无效，请重新输入。\n";
            cin.clear();
            cin.ignore(numeric_limits<streamsize>::max(), '\n');
            continue;
        }

        switch (choice) {
            case 1: {
                ActivityData data = safeRecordActivity();
                records.push_back(data);
                break;
            }
            case 2:
                showHistory(records);
                break;
            case 3:
                showSummary(records);
                break;
            case 4:
                showChart(records);
                break;
            case 0:
                cout << "程序已退出。\n";
                return 0;
            default:
                cout << "无效选项，请重新选择。\n";
                break;
        }
    }

    return 0;
}
```

关键修改点：
1. 将 `unsafeRecordActivity()` 完善为 `safeRecordActivity()`，增加了安全输入校验，避免非法输入导致程序异常。
