class LogManager {
private:
    std::vector<std::string> logs;
    std::string logFilePath;

    static std::string getCurrentTime() {
        std::time_t now = std::time(nullptr);
        char buf[32] = {0};
        std::strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", std::localtime(&now));
        return std::string(buf);
    }

public:
    explicit LogManager(const std::string& filePath) : logFilePath(filePath) {
        loadLogsFromFile();
    }

    void readLogEntry(const std::string& logEntry) {
        if (logEntry.empty()) {
            std::cerr << "日志内容不能为空" << std::endl;
            return;
        }

        std::ostringstream oss;
        oss << "[" << getCurrentTime() << "] " << logEntry;
        logs.push_back(oss.str());
    }

    void saveLogsToFile() const {
        std::ofstream outFile(logFilePath, std::ios::out | std::ios::trunc);
        if (!outFile.is_open()) {
            std::cerr << "无法打开日志文件进行写入: " << logFilePath << std::endl;
            return;
        }

        for (const auto& log : logs) {
            outFile << log << '\n';
        }
    }

    void loadLogsFromFile() {
        logs.clear();
        std::ifstream inFile(logFilePath);
        if (!inFile.is_open()) {
            return;
        }

        std::string line;
        while (std::getline(inFile, line)) {
            if (!line.empty()) {
                logs.push_back(line);
            }
        }
    }

    void printLogs() const {
        if (logs.empty()) {
            std::cout << "暂无日志记录" << std::endl;
            return;
        }

        for (const auto& log : logs) {
            std::cout << log << std::endl;
        }
    }

    void clearLogs() {
        logs.clear();
        saveLogsToFile();
    }

    std::vector<std::string> searchLogs(const std::string& keyword) const {
        std::vector<std::string> result;
        for (const auto& log : logs) {
            if (log.find(keyword) != std::string::npos) {
                result.push_back(log);
            }
        }
        return result;
    }
};

int main() {
    LogManager logManager("app.log");

    logManager.readLogEntry("系统启动");
    logManager.readLogEntry("用户登录成功");
    logManager.readLogEntry("数据库连接异常");

    logManager.saveLogsToFile();

    std::cout << "全部日志：" << std::endl;
    logManager.printLogs();

    std::cout << "\n搜索关键字“登录”结果：" << std::endl;
    auto results = logManager.searchLogs("登录");
    for (const auto& log : results) {
        std::cout << log << std::endl;
    }

    return 0;
}
