#include <iostream>
#include <sstream>
#include <string>
#include <vector>

// 对HTML属性中的特殊字符进行转义，避免路径中包含特殊字符时破坏HTML结构
std::string escapeHtml(const std::string& input) {
    std::string result;
    result.reserve(input.size());

    for (char ch : input) {
        switch (ch) {
            case '&': result += "&amp;";  break;
            case '"': result += "&quot;"; break;
            case '\'': result += "&#39;"; break;
            case '<': result += "&lt;";   break;
            case '>': result += "&gt;";   break;
            default:  result += ch;       break;
        }
    }
    return result;
}

// 生成HTML格式的视频播放器页面
std::string generateVideoPlayerPageWithCover(
    const std::vector<std::string>& videoPaths,
    const std::string& coverImagePath
) {
    std::ostringstream htmlStream;

    htmlStream << R"(<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>视频播放器</title>
<style>
  body {
    font-family: Arial, sans-serif;
    margin: 24px;
    background: #f7f7f7;
    color: #222;
  }
  h1 {
    margin-bottom: 24px;
  }
  .video-container {
    width: 100%;
    max-width: 800px;
    margin-bottom: 24px;
    background: #fff;
    border-radius: 10px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08);
    padding: 12px;
  }
  video {
    width: 100%;
    height: auto;
    display: block;
    border-radius: 8px;
    background: #000;
  }
  .empty-tip {
    color: #666;
    padding: 12px 0;
  }
</style>
</head>
<body>
<h1>视频播放列表</h1>
)";

    if (videoPaths.empty()) {
        htmlStream << "<p class=\"empty-tip\">当前没有可播放的视频。</p>\n";
    } else {
        const std::string escapedCover = escapeHtml(coverImagePath);

        for (size_t i = 0; i < videoPaths.size(); ++i) {
            const std::string escapedPath = escapeHtml(videoPaths[i]);

            htmlStream << "<div class=\"video-container\">\n"
                       << "  <p>视频 " << (i + 1) << "</p>\n"
                       << "  <video controls preload=\"metadata\" poster=\"" << escapedCover << "\">\n"
                       << "    <source src=\"" << escapedPath << "\" type=\"video/mp4\">\n"
                       << "    您的浏览器不支持视频播放。\n"
                       << "  </video>\n"
                       << "</div>\n";
        }
    }

    htmlStream << R"(</body>
</html>
)";

    return htmlStream.str();
}

int main() {
    std::vector<std::string> videoPaths = {
        "/path/to/videos/video1.mp4",
        "/path/to/videos/video2.mp4",
        "/path/to/videos/video3.mp4"
    };

    std::string coverImagePath = "/path/to/images/cover.jpg";

    std::string htmlContent = generateVideoPlayerPageWithCover(videoPaths, coverImagePath);
    std::cout << htmlContent;

    return 0;
}
