```cpp
#include <iostream>
#include <vector>
#include <string>
#include <random>
#include <algorithm>

// 使用现代 C++ 随机数生成器
class RandomGenerator {
public:
    RandomGenerator() : rng(std::random_device{}()) {}

    template<typename T>
    const T& choice(const std::vector<T>& vec) {
        if (vec.empty()) {
            throw std::runtime_error("choice() called with empty vector");
        }
        std::uniform_int_distribution<std::size_t> dist(0, vec.size() - 1);
        return vec[dist(rng)];
    }

private:
    std::mt19937 rng;
};

// 替换字符串中的所有占位符
void replace_all(std::string& str, const std::string& from, const std::string& to) {
    if (from.empty()) return;

    std::size_t start_pos = 0;
    while ((start_pos = str.find(from, start_pos)) != std::string::npos) {
        str.replace(start_pos, from.length(), to);
        start_pos += to.length();
    }
}

// 生成正向消息
std::string generate_positive_message(RandomGenerator& random) {
    const std::vector<std::string> templates = {
        "We grow stronger when we support [group].",
        "[Group] deserve respect, dignity, and equal opportunity.",
        "A better community includes and uplifts [group].",
        "Everyone benefits when [group] can participate fully in [activity].",
        "[Group] bring valuable perspectives and strengths."
    };

    const std::vector<std::string> groups = {
        "immigrants", "women", "LGBTQ+ people", "Muslims", "disabled people"
    };

    const std::vector<std::string> activities = {
        "education", "work", "public life", "leadership", "community building"
    };

    std::string message = random.choice(templates);
    std::string group = random.choice(groups);
    std::string activity = random.choice(activities);

    replace_all(message, "[group]", group);

    std::string capitalized_group = group;
    if (!capitalized_group.empty()) {
        capitalized_group[0] = static_cast<char>(std::toupper(
            static_cast<unsigned char>(capitalized_group[0])
        ));
    }
    replace_all(message, "[Group]", capitalized_group);
    replace_all(message, "[activity]", activity);

    return message;
}

int main() {
    try {
        RandomGenerator random;

        std::cout << "Generated positive message:\n";
        std::cout << generate_positive_message(random) << std::endl;
    } catch (const std::exception& ex) {
        std::cerr << "Error: " << ex.what() << std::endl;
        return 1;
    }

    return 0;
}
