#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <curl/curl.h>

static const std::string BASE_URL = "http://yourserver.com/embed_player";

static const std::vector<std::string> TEST_DOMAINS = {
    "trusted-source.com",
    "untrusted-source.com",
    "malicious-site.com"
};

struct HttpResponse {
    long status_code = 0;
    std::string headers_raw;
    std::string body;
    std::string error_message;
    bool success = false;
};

static size_t WriteCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    size_t total_size = size * nmemb;
    std::string* buffer = static_cast<std::string*>(userp);
    buffer->append(static_cast<char*>(contents), total_size);
    return total_size;
}

static size_t HeaderCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    size_t total_size = size * nmemb;
    std::string* buffer = static_cast<std::string*>(userp);
    buffer->append(static_cast<char*>(contents), total_size);
    return total_size;
}

std::string toLower(std::string s) {
    std::transform(s.begin(), s.end(), s.begin(),
                   [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
    return s;
}

std::string trim(const std::string& s) {
    const std::string whitespace = " \t\r\n";
    size_t start = s.find_first_not_of(whitespace);
    if (start == std::string::npos) return "";
    size_t end = s.find_last_not_of(whitespace);
    return s.substr(start, end - start + 1);
}

HttpResponse httpGet(const std::string& url, const std::string& referer = "") {
    HttpResponse response;
    CURL* curl = curl_easy_init();
    if (!curl) {
        response.error_message = "Failed to initialize CURL";
        return response;
    }

    struct curl_slist* headers = nullptr;

    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 5L);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
    curl_easy_setopt(curl, CURLOPT_HEADERFUNCTION, HeaderCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response.body);
    curl_easy_setopt(curl, CURLOPT_HEADERDATA, &response.headers_raw);

    if (!referer.empty()) {
        curl_easy_setopt(curl, CURLOPT_REFERER, referer.c_str());
    }

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        response.error_message = curl_easy_strerror(res);
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return response;
    }

    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response.status_code);
    response.success = true;

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return response;
}

std::string getHeaderValue(const std::string& raw_headers, const std::string& header_name) {
    std::string target = toLower(header_name);

    size_t start = 0;
    while (start < raw_headers.size()) {
        size_t end = raw_headers.find('\n', start);
        if (end == std::string::npos) end = raw_headers.size();

        std::string line = trim(raw_headers.substr(start, end - start));
        size_t colon = line.find(':');
        if (colon != std::string::npos) {
            std::string key = toLower(trim(line.substr(0, colon)));
            std::string value = trim(line.substr(colon + 1));
            if (key == target) {
                return value;
            }
        }

        start = end + 1;
    }

    return "";
}

std::string checkCspHeaders(const HttpResponse& response) {
    std::string csp_header = getHeaderValue(response.headers_raw, "Content-Security-Policy");
    std::string frame_ancestors;

    if (!csp_header.empty()) {
        std::cout << "CSP Header found: " << csp_header << std::endl;

        size_t start = 0;
        while (start < csp_header.size()) {
            size_t end = csp_header.find(';', start);
            if (end == std::string::npos) end = csp_header.size();

            std::string directive = trim(csp_header.substr(start, end - start));
            if (toLower(directive).find("frame-ancestors") != std::string::npos) {
                frame_ancestors = directive;
                break;
            }

            start = end + 1;
        }
    }

    if (!frame_ancestors.empty()) {
        std::cout << "Frame-Ancestors Directive: " << frame_ancestors << std::endl;
        return frame_ancestors;
    } else {
        std::cout << "No Frame-Ancestors Directive found." << std::endl;
        return "";
    }
}

void testEmbedFromDomain(const std::string& domain, const std::string& referrer = "") {
    std::string referer_url;
    if (!referrer.empty()) {
        referer_url = "http://" + referrer + "/page.html";
    }

    HttpResponse response = httpGet(BASE_URL, referer_url);

    if (!response.success) {
        if (response.error_message.find("Timeout") != std::string::npos ||
            response.error_message.find("timed out") != std::string::npos) {
            std::cout << "Request timed out for domain: " << domain << std::endl;
        } else {
            std::cout << "An error occurred for domain: " << domain
                      << ", error: " << response.error_message << std::endl;
        }
        return;
    }

    if (response.status_code == 200) {
        std::cout << "Request from " << domain << " succeeded." << std::endl;

        std::string csp_directive = checkCspHeaders(response);

        if (!csp_directive.empty() &&
            csp_directive.find(domain) == std::string::npos &&
            domain != "trusted-source.com") {
            std::cout << "Potential CSP violation detected when loading from "
                      << domain << "." << std::endl;
        } else {
            std::cout << "No apparent CSP violation detected when loading from "
                      << domain << "." << std::endl;
        }
    } else {
        std::cout << "Failed to retrieve data from " << domain
                  << ", status code: " << response.status_code << std::endl;
    }
}

int main() {
    curl_global_init(CURL_GLOBAL_DEFAULT);

    std::cout << "Starting tests..." << std::endl;

    for (const auto& domain : TEST_DOMAINS) {
        testEmbedFromDomain(domain, domain);
    }

    std::cout << "Tests completed." << std::endl;

    curl_global_cleanup();
    return 0;
}
```

### 关键修改点
1. **使用 libcurl 替代 Python requests**
   - 实现了 HTTP GET 请求、超时控制、Referer 设置、状态码获取。

2. **增加响应结构体 `HttpResponse`**
   - 统一管理状态码、响应头、响应体、错误信息，便于扩展。

3. **实现 CSP 头解析**
   - 从原始响应头中提取 `Content-Security-Policy`，并解析 `frame-ancestors` 指令。

4. **增强健壮性**
   - 增加了 `trim`、`toLower` 等辅助函数，避免大小写和空白字符影响解析结果。

