#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <sqlite3.h>

class SQLiteStmtDeleter {
public:
    void operator()(sqlite3_stmt* stmt) const {
        if (stmt) sqlite3_finalize(stmt);
    }
};

class SQLiteDbDeleter {
public:
    void operator()(sqlite3* db) const {
        if (db) sqlite3_close(db);
    }
};

using SqliteDbPtr = std::unique_ptr<sqlite3, SQLiteDbDeleter>;
using SqliteStmtPtr = std::unique_ptr<sqlite3_stmt, SQLiteStmtDeleter>;

bool isDigitsOnly(const std::string& s) {
    if (s.empty()) return false;
    for (char c : s) {
        if (!std::isdigit(static_cast<unsigned char>(c))) return false;
    }
    return true;
}

void queryOrdersAndCustomers(const std::string& dbPath,
                             const std::string& orderId,
                             const std::string& customerName) {
    sqlite3* rawDb = nullptr;
    int rc = sqlite3_open(dbPath.c_str(), &rawDb);
    if (rc != SQLITE_OK) {
        std::cerr << "Failed to open database: " << sqlite3_errmsg(rawDb) << std::endl;
        if (rawDb) sqlite3_close(rawDb);
        return;
    }

    SqliteDbPtr db(rawDb);

    std::string query =
        "SELECT orders.id, customers.name, orders.order_date, orders.total_amount "
        "FROM orders "
        "JOIN customers ON orders.customer_id = customers.id "
        "WHERE 1=1";

    std::vector<std::string> params;

    if (!orderId.empty()) {
        if (!isDigitsOnly(orderId)) {
            std::cerr << "Invalid order ID. It must be numeric." << std::endl;
            return;
        }
        query += " AND orders.id = ?";
        params.push_back(orderId);
    }

    if (!customerName.empty()) {
        query += " AND customers.name LIKE ?";
        params.push_back("%" + customerName + "%");
    }

    sqlite3_stmt* rawStmt = nullptr;
    rc = sqlite3_prepare_v2(db.get(), query.c_str(), -1, &rawStmt, nullptr);
    if (rc != SQLITE_OK) {
        std::cerr << "Failed to prepare statement: " << sqlite3_errmsg(db.get()) << std::endl;
        return;
    }

    SqliteStmtPtr stmt(rawStmt);

    for (int i = 0; i < static_cast<int>(params.size()); ++i) {
        rc = sqlite3_bind_text(stmt.get(), i + 1, params[i].c_str(), -1, SQLITE_TRANSIENT);
        if (rc != SQLITE_OK) {
            std::cerr << "Failed to bind parameter " << (i + 1)
                      << ": " << sqlite3_errmsg(db.get()) << std::endl;
            return;
        }
    }

    std::cout << "Query results:" << std::endl;
    bool hasRows = false;

    while ((rc = sqlite3_step(stmt.get())) == SQLITE_ROW) {
        hasRows = true;

        int id = sqlite3_column_int(stmt.get(), 0);
        const unsigned char* name = sqlite3_column_text(stmt.get(), 1);
        const unsigned char* orderDate = sqlite3_column_text(stmt.get(), 2);
        double totalAmount = sqlite3_column_double(stmt.get(), 3);

        std::cout << "Order ID: " << id
                  << ", Customer: " << (name ? reinterpret_cast<const char*>(name) : "")
                  << ", Date: " << (orderDate ? reinterpret_cast<const char*>(orderDate) : "")
                  << ", Total: " << totalAmount
                  << std::endl;
    }

    if (rc != SQLITE_DONE) {
        std::cerr << "Query execution failed: " << sqlite3_errmsg(db.get()) << std::endl;
        return;
    }

    if (!hasRows) {
        std::cout << "No matching records found." << std::endl;
    }
}

int main() {
    const std::string dbPath = "path/to/your/database.db";

    try {
        std::string orderId;
        std::string customerName;

        std::cout << "Enter Order ID (optional): ";
        std::getline(std::cin, orderId);

        std::cout << "Enter Customer Name (optional): ";
        std::getline(std::cin, customerName);

        queryOrdersAndCustomers(dbPath, orderId, customerName);
    } catch (const std::exception& e) {
        std::cerr << "An error occurred: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
```

