#include <cassert>

class Question {
public:
    void displayQuestion(const std::string& question, std::ostream& os = std::cout) const {
        // 安全输出：不把用户输入当作格式串
        os << question;
    }
};

// 单元测试：验证普通字符串输出
void testDisplayQuestion_NormalText() {
    Question q;
    std::ostringstream oss;

    q.displayQuestion("What is the answer?", oss);

    assert(oss.str() == "What is the answer?");
}

// 单元测试：验证包含格式化字符的输入也能被原样输出
void testDisplayQuestion_FormatStringPayload() {
    Question q;
    std::ostringstream oss;

    std::string userInput = "What is the answer? %n %s %x";
    q.displayQuestion(userInput, oss);

    assert(oss.str() == userInput);
}

int main() {
    testDisplayQuestion_NormalText();
    testDisplayQuestion_FormatStringPayload();

    std::cout << "All tests passed!" << std::endl;
