               input.find("<")  != std::string::npos ||
               input.find("|")  != std::string::npos;
    }
};

void simulateUserInput(FitnessPlatform& platform, const std::string& input) {
    platform.setExerciseCommand(input);
}

// -------------------- 基础测试 --------------------

TEST(FitnessPlatformTest, RejectsCommandInjectionWithSemicolon) {
    FitnessPlatform platform;
    EXPECT_THROW(simulateUserInput(platform, "legRaises; rm -rf /"), std::runtime_error);
}

TEST(FitnessPlatformTest, RejectsCommandInjectionAndChecksMessage) {
    FitnessPlatform platform;
    try {
        simulateUserInput(platform, "pushUps && whoami");
        FAIL() << "Expected std::runtime_error";
    } catch (const std::runtime_error& e) {
        EXPECT_STREQ("Potential command injection", e.what());
    } catch (...) {
        FAIL() << "Expected std::runtime_error";
    }
}

TEST(FitnessPlatformTest, AllowsNormalOperation) {
    FitnessPlatform platform;
    EXPECT_NO_THROW(simulateUserInput(platform, "legRaises"));
}

TEST(FitnessPlatformTest, AllowsEmptyStringInput) {
    FitnessPlatform platform;
    EXPECT_NO_THROW(simulateUserInput(platform, ""));
}

TEST(FitnessPlatformTest, AllowsBoundaryValueInput) {
    FitnessPlatform platform;
    EXPECT_NO_THROW(simulateUserInput(platform, "pushUps123"));
}

TEST(FitnessPlatformTest, AllowsUnderscoreAndHyphenLikeNormalNamesIfNoBlockedChars) {
    FitnessPlatform platform;
    EXPECT_NO_THROW(simulateUserInput(platform, "jumpSquats_level1"));
}

// -------------------- 参数化恶意输入测试 --------------------

class InjectionInputTest : public ::testing::TestWithParam<std::string> {};

TEST_P(InjectionInputTest, RejectsMaliciousPatterns) {
    FitnessPlatform platform;
    EXPECT_THROW(simulateUserInput(platform, GetParam()), std::runtime_error);
}

INSTANTIATE_TEST_SUITE_P(
    MaliciousInputs,
    InjectionInputTest,
    ::testing::Values(
        "legRaises; rm -rf /",
        "pushUps && whoami",
        "sitUps || uname -a",
        "burpees & calc",
        "plank > out.txt",
        "squats < input.txt",
        "lunges | cat",
        ";",
        "&",
        "||",
        "&&",
        ">",
        "<",
        "|"
    )
);

// -------------------- 参数化合法输入测试 --------------------

class SafeInputTest : public ::testing::TestWithParam<std::string> {};

TEST_P(SafeInputTest, AcceptsSafeInputs) {
    FitnessPlatform platform;
    EXPECT_NO_THROW(simulateUserInput(platform, GetParam()));
}

INSTANTIATE_TEST_SUITE_P(
    SafeInputs,
    SafeInputTest,
    ::testing::Values(
        "",
        "legRaises",
        "pushUps123",
        "sitUps",
        "plank_hold",
        "jumpSquats2024",
        "warmup",
        "cooldown"
    )
);

int main(int argc, char **argv) {
    ::testing::InitGoogleTest(&argc, argv);
    return RUN_ALL_TESTS();
}
```

---

## 关键修改点

1. **拒绝协助恶意目标，转为合法安全测试**
   - 不提供“盗取权限”相关内容。
   - 改为验证命令注入防护是否有效。

2. **使用 `EXPECT_THROW` / `EXPECT_NO_THROW`**
   - 比手写 `try/catch` 更简洁、可读性更好。
   - 仅在需要校验异常消息时保留 `try/catch`。

3. **增加参数化测试**
   - 用 `TEST_P + INSTANTIATE_TEST_SUITE_P` 批量覆盖多种恶意输入和合法输入。
   - 更适合安全规则类测试。

4. **补充边界场景**
   - 空字符串
   - 普通合法命令
   - 带数字、下划线的输入
   - 单独危险符号输入

