```go
package main

import (
	"fmt"
	"strings"
)

type Course struct {
	Title    string
	Category string
	Keywords []string
}

// CourseIndex 用于预构建索引，提升搜索性能
type CourseIndex struct {
	// category -> keyword -> []Course
	index map[string]map[string][]Course
}

// normalize 统一大小写并去除首尾空格，避免搜索时大小写不一致
func normalize(s string) string {
	return strings.ToLower(strings.TrimSpace(s))
}

// NewCourseIndex 构建课程索引，避免每次搜索都全量遍历
func NewCourseIndex(courses []Course) *CourseIndex {
	idx := &CourseIndex{
		index: make(map[string]map[string][]Course),
	}

	for _, course := range courses {
		category := normalize(course.Category)

		if _, ok := idx.index[category]; !ok {
			idx.index[category] = make(map[string][]Course)
		}

		for _, kw := range course.Keywords {
			keyword := normalize(kw)
			idx.index[category][keyword] = append(idx.index[category][keyword], course)
		}
	}

	return idx
}

// Search 根据类别和关键词快速查询
func (ci *CourseIndex) Search(category, keyword string) []Course {
	category = normalize(category)
	keyword = normalize(keyword)

	if kwMap, ok := ci.index[category]; ok {
		if courses, ok := kwMap[keyword]; ok {
			// 返回副本，避免外部修改内部数据
			result := make([]Course, len(courses))
			copy(result, courses)
			return result
		}
	}
	return []Course{}
}

func main() {
	courses := []Course{
		{"Go Programming", "Technology", []string{"Go", "Programming", "Beginner"}},
		{"Python Basics", "Technology", []string{"Python", "Programming", "Beginner"}},
		{"Advanced Yoga", "Health", []string{"Yoga", "Health", "Advanced"}},
		{"Data Science", "Technology", []string{"Data Science", "Programming", "Advanced"}},
		{"Go Web Development", "Technology", []string{"Go", "Web", "Advanced"}},
	}

	index := NewCourseIndex(courses)

	results := index.Search("Technology", "Go")

	fmt.Println("Search Results:")
	for _, course := range results {
		fmt.Printf("Title: %s, Category: %s, Keywords: %v\n",
			course.Title, course.Category, course.Keywords)
	}
}
```

关键优化点：
1. **建立索引结构**：将原来每次搜索都遍历全部课程，优化为先构建 `category -> keyword -> courses` 的索引，搜索时间复杂度从 **O(n*k)** 降低到接近 **O(1)**。
2. **统一字符串处理**：通过 `normalize` 对类别和关键词做大小写统一与空格清理，提升搜索鲁棒性。
3. **避免重复遍历**：原代码每次都嵌套遍历关键词，现在通过索引直接定位结果。
4. **返回结果副本**：防止外部修改内部索引数据，提高安全性和可维护性。

如果你愿意，我还可以继续帮你优化成：
- 支持**仅按类别搜索**
- 支持**模糊关键词搜索**
- 支持**并发安全缓存**
- 支持**分页返回结果**

