```go
package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

type Booking struct {
	UserID     int
	PropertyID int
	StartDate  time.Time
	EndDate    time.Time
}

type BookingService struct {
	mu sync.RWMutex
	// 按房源ID存储预订记录，避免每次扫描无关房源
	bookings map[int][]Booking
}

func NewBookingService() *BookingService {
	return &BookingService{
		bookings: make(map[int][]Booking),
	}
}

// 判断两个时间区间是否重叠
func isOverlap(start1, end1, start2, end2 time.Time) bool {
	return start1.Before(end2) && start2.Before(end1)
}

// 仅检查目标房源是否可预订，避免原代码遍历所有房源
func (s *BookingService) CheckAvailability(propertyID int, startDate, endDate time.Time) bool {
	s.mu.RLock()
	defer s.mu.RUnlock()

	existingBookings := s.bookings[propertyID]
	for _, b := range existingBookings {
		if isOverlap(startDate, endDate, b.StartDate, b.EndDate) {
			return false
		}
	}
	return true
}

// 创建预订，带二次校验，保证并发安全
func (s *BookingService) MakeBooking(ctx context.Context, userID, propertyID int, startDate, endDate time.Time) (*Booking, error) {
	if userID <= 0 || propertyID <= 0 {
		return nil, errors.New("invalid userID or propertyID")
	}
	if !startDate.Before(endDate) {
		return nil, errors.New("startDate must be before endDate")
	}

	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	default:
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	// 加锁后再次检查，避免并发下重复预订
	for _, b := range s.bookings[propertyID] {
		if isOverlap(startDate, endDate, b.StartDate, b.EndDate) {
			return nil, errors.New("property not available")
		}
	}

	booking := Booking{
		UserID:     userID,
		PropertyID: propertyID,
		StartDate:  startDate,
		EndDate:    endDate,
	}

	s.bookings[propertyID] = append(s.bookings[propertyID], booking)
	return &booking, nil
}

func main() {
	service := NewBookingService()

	userID := 123
	propertyID := 1
	startDate := time.Now()
	endDate := startDate.Add(48 * time.Hour)

	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	booking, err := service.MakeBooking(ctx, userID, propertyID, startDate, endDate)
	if err != nil {
		fmt.Println("Create booking failed:", err)
		return
	}

	fmt.Printf("Booking created: %+v\n", *booking)

	// 测试冲突预订
	_, err = service.MakeBooking(ctx, 456, propertyID, startDate.Add(12*time.Hour), endDate.Add(12*time.Hour))
	if err != nil {
		fmt.Println("Second booking failed:", err)
	}
}
```

关键优化点：
1. 去掉了 `checkAvailability` 中对所有房源的无效遍历和 `time.Sleep`，只检查目标房源，减少无意义耗时。
2. 使用 `map[int][]Booking` 按房源维度存储预订记录，查询效率更高。
3. 增加 `sync.RWMutex`，保证并发场景下预订数据安全。
4. 在创建预订时做参数校验和时间区间冲突检测，避免非法数据。
5. 引入 `context.Context`，便于后续接入数据库、超时控制和请求取消。
6. 将逻辑封装到 `BookingService`，结构更清晰，更适合扩展用户认证、房源管理等模块。

