		return
	}

	filtered := filterCars(cars, r)
	stats := calculateStats(filtered)
	writeJSON(w, http.StatusOK, stats)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, "method not allowed")
		return
	}

	writeJSON(w, http.StatusOK, map[string]string{
		"status": "ok",
	})
}

func filterCars(source []Car, r *http.Request) []Car {
	query := r.URL.Query()
	brand := strings.TrimSpace(strings.ToLower(query.Get("brand")))
	model := strings.TrimSpace(strings.ToLower(query.Get("model")))

	minPrice, _ := strconv.Atoi(query.Get("min_price"))
	maxPrice, _ := strconv.Atoi(query.Get("max_price"))
	sortBy := strings.TrimSpace(strings.ToLower(query.Get("sort")))

	result := make([]Car, 0, len(source))
	for _, car := range source {
		if brand != "" && strings.ToLower(car.Brand) != brand {
			continue
		}
		if model != "" && strings.ToLower(car.Model) != model {
			continue
		}
		if minPrice > 0 && car.Price < minPrice {
			continue
		}
		if maxPrice > 0 && car.Price > maxPrice {
			continue
		}
		result = append(result, car)
	}

	switch sortBy {
	case "price_asc":
		sort.Slice(result, func(i, j int) bool {
			return result[i].Price < result[j].Price
		})
	case "price_desc":
		sort.Slice(result, func(i, j int) bool {
			return result[i].Price > result[j].Price
		})
	}

	return result
}

func calculateStats(cars []Car) CarStats {
	if len(cars) == 0 {
		return CarStats{}
	}

	minPrice := cars[0].Price
	maxPrice := cars[0].Price
	total := 0

	for _, car := range cars {
		if car.Price < minPrice {
			minPrice = car.Price
		}
		if car.Price > maxPrice {
			maxPrice = car.Price
		}
		total += car.Price
	}

	return CarStats{
		Count:        len(cars),
		MinPrice:     minPrice,
		MaxPrice:     maxPrice,
		AveragePrice: float64(total) / float64(len(cars)),
	}
}

func writeJSON(w http.ResponseWriter, status int, data any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)

	if err := json.NewEncoder(w).Encode(data); err != nil {
		log.Printf("write json failed: %v", err)
	}
}

func writeError(w http.ResponseWriter, status int, message string) {
	writeJSON(w, status, map[string]string{
		"error": message,
	})
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s %s", r.Method, r.URL.RequestURI(), time.Since(start))
	})
}
```

关键优化点：
1. 增加了`/api/cars/stats`接口，支持直接做车辆价格统计分析，便于推荐系统使用。
2. 增加了查询过滤能力：支持`brand`、`model`、`min_price`、`max_price`、`sort`。
3. 增加了统一的JSON响应和错误处理，接口更规范。
4. 增加了`healthz`健康检查接口，便于部署和监控。
5. 使用`http.Server`并加入优雅关闭，提升服务稳定性。
6. 增加了请求日志中间件，方便排查问题。

示例：
- 获取所有车辆  
  `GET http://localhost:8080/api/cars`

- 按品牌和价格过滤  
  `GET http://localhost:8080/api/cars?brand=Toyota&min_price=12000&sort=price_asc`

- 获取统计信息  
  `GET http://localhost:8080/api/cars/stats?brand=Honda`

运行：
```bash
go run main.go
```

