package main

import (
	"fmt"
	"time"
)

// diagnosis 仅作为示例计算函数：
// 1. 保留原有返回规则
// 2. 用迭代 DP 替代指数级递归，避免大量重复计算和栈开销
func diagnosis(age, symptomScore int) int {
	if age < 18 {
		return 0
	}
	if symptomScore < 5 {
		return 0
	}
	if age > 60 {
		return 100
	}

	// f(a) = f(a-1) + f(a-2) + symptomScore
	// 边界：
	// a < 18 => 0
	// a > 60 => 100
	//
	// 对于当前场景 age <= 60，只需从 18 开始迭代到 age
	// f(16)=0, f(17)=0
	prev2 := 0 // f(16)
	prev1 := 0 // f(17)

	for a := 18; a <= age; a++ {
		cur := prev1 + prev2 + symptomScore
		prev2 = prev1
		prev1 = cur
	}

	return prev1
}

func main() {
	age := 45
	symptomScore := 8

	startTime := time.Now()
	result := diagnosis(age, symptomScore)
	elapsed := time.Since(startTime)

	fmt.Printf("计算结果：%d\n", result)
	fmt.Printf("耗时：%s\n", elapsed)
}
