package main

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"regexp"
	"strings"
	"time"
)

type Product struct {
	Name  string
	Price string
	Stock string
}

var productRe = regexp.MustCompile(`(?is)<div\s+class="product">.*?name="(.*?)".*?price="(.*?)".*?stock="(.*?)"`)

func fetchPage(ctx context.Context, client *http.Client, pageURL string) (string, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, pageURL, nil)
	if err != nil {
		return "", fmt.Errorf("create request failed: %w", err)
	}

	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("request failed: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, 2<<20)) // 限制最大读取 2MB
	if err != nil {
		return "", fmt.Errorf("read response failed: %w", err)
	}

	return string(body), nil
}

func parseProducts(pageContent string) []Product {
	matches := productRe.FindAllStringSubmatch(pageContent, -1)
	products := make([]Product, 0, len(matches))

	for _, match := range matches {
		if len(match) < 4 {
			continue
		}
		products = append(products, Product{
			Name:  strings.TrimSpace(match[1]),
			Price: strings.TrimSpace(match[2]),
			Stock: strings.TrimSpace(match[3]),
		})
	}

	return products
}

func buildNextPageURL(rawURL string, page int) string {
	u, err := url.Parse(rawURL)
	if err != nil {
		return rawURL
	}

	q := u.Query()
	q.Set("page", fmt.Sprintf("%d", page))
	u.RawQuery = q.Encode()
	return u.String()
}

func crawlPages(ctx context.Context, client *http.Client, startURL string, maxDepth int, delay time.Duration) error {
	if maxDepth <= 0 {
		return nil
	}

	currentURL := startURL
	for page := 1; page <= maxDepth; page++ {
		fmt.Printf("正在抓取: %s\n", currentURL)

		pageContent, err := fetchPage(ctx, client, currentURL)
		if err != nil {
			return fmt.Errorf("crawl page %d failed: %w", page, err)
		}

		products := parseProducts(pageContent)
		for _, p := range products {
			fmt.Printf("商品名称: %s, 价格: %s, 库存: %s\n", p.Name, p.Price, p.Stock)
		}

		if page < maxDepth {
			select {
			case <-ctx.Done():
				return ctx.Err()
			case <-time.After(delay):
			}
			currentURL = buildNextPageURL(startURL, page+1)
		}
	}

	return nil
}

func main() {
	startURL := "https://example.com/products"

	client := &http.Client{
		Timeout: 10 * time.Second,
	}

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	if err := crawlPages(ctx, client, startURL, 5, 1*time.Second); err != nil {
		fmt.Println("抓取失败:", err)
	}
}
```

### 关键优化点
1. **修复无效导入**
   - 原代码里 `strings` 导入未使用，会导致编译失败；优化后实际用于 `TrimSpace`。

2. **避免只读取固定 1000 字节**
   - 原来 `resp.Body.Read(body)` 可能读不完整，还忽略了返回的字节数和错误。
   - 改为 `io.ReadAll(io.LimitReader(...))`，更安全可靠。

3. **增加 HTTP 超时与上下文控制**
   - 使用 `http.Client{Timeout: ...}` 和 `context.WithTimeout`，避免请求卡死。

4. **检查 HTTP 状态码**
   - 原代码未判断 `resp.StatusCode`，现在会校验是否为 `200 OK`。

5. **正则只编译一次**
   - 原代码每次递归都 `MustCompile`，浪费性能。
   - 改为全局复用 `productRe`。

6. **递归改迭代**
   - 原代码递归层数大时不够稳健。
   - 改为 `for` 循环分页抓取，更清晰也更安全。

7. **正确构造下一页 URL**
   - 原代码直接拼接 `?page=`，如果原 URL 已有参数会出错。
   - 改为使用 `net/url` 安全拼接查询参数。

8. **增强错误处理**
   - 原代码大量忽略错误，例如读取 body 时未处理错误。
   - 现在每一步都返回明确错误信息。

9. **结构化商品数据**
   - 增加 `Product` 结构体，便于后续扩展，比如保存到数据库或导出 JSON。

如果你愿意，我还可以继续帮你把这段代码进一步优化成：
- **并发抓取版本**
- **基于 HTML 解析器（goquery）替代正则版本**
- **支持重试、限流、日志的生产级版本**

