package main

import (
	"fmt"
	"os"
)

func controlDevice(deviceID, command string) error {
	// 创建临时文件。os.CreateTemp 默认使用 0600 权限，更安全。
	tmpFile, err := os.CreateTemp("", "device-control-*.tmp")
	if err != nil {
		return fmt.Errorf("create temp file failed: %w", err)
	}

	// 确保文件关闭并删除，避免临时文件残留
	defer func() {
		tmpFile.Close()
		os.Remove(tmpFile.Name())
	}()

	content := fmt.Sprintf("DeviceID: %s, Command: %s\n", deviceID, command)

	if _, err := tmpFile.WriteString(content); err != nil {
		return fmt.Errorf("write temp file failed: %w", err)
	}

	// 确保数据刷盘
	if err := tmpFile.Sync(); err != nil {
		return fmt.Errorf("sync temp file failed: %w", err)
	}

	fmt.Println("Command executed successfully.")
	return nil
}

func main() {
	if err := controlDevice("device1", "Turn On"); err != nil {
		fmt.Println("Error:", err)
	}
}
```

关键修改点：
1. 用 `os.CreateTemp` 替换已废弃的 `ioutil.TempFile`。
2. 临时文件默认权限为 `0600`，更适合测试临时文件权限安全性。
3. 增加 `defer os.Remove(tmpFile.Name())`，防止临时文件残留。
4. 将 `controlDevice` 改为返回 `error`，便于调用方统一处理错误。
