package main

import (
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"strings"
	"time"
)

const maxBodySize = 1 << 20 // 1MB

type Product struct {
	Name        string  `json:"name"`
	Description string  `json:"description"`
	Price       float64 `json:"price"`
}

type APIResponse struct {
	Message string   `json:"message,omitempty"`
	Error   string   `json:"error,omitempty"`
	Product *Product `json:"product,omitempty"`
}

func writeJSON(w http.ResponseWriter, status int, resp APIResponse) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(resp)
}

func validateProduct(p *Product) error {
	if strings.TrimSpace(p.Name) == "" {
		return errors.New("product name is required")
	}
	if p.Price < 0 {
		return errors.New("product price must be >= 0")
	}
	return nil
}

func uploadProduct(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeJSON(w, http.StatusMethodNotAllowed, APIResponse{
			Error: "method not allowed, use POST",
		})
		return
	}

	defer r.Body.Close()
	r.Body = http.MaxBytesReader(w, r.Body, maxBodySize)

	var p Product
	decoder := json.NewDecoder(r.Body)
	decoder.DisallowUnknownFields()

	if err := decoder.Decode(&p); err != nil {
		if errors.Is(err, io.EOF) {
			writeJSON(w, http.StatusBadRequest, APIResponse{
				Error: "request body is empty",
			})
			return
		}
		writeJSON(w, http.StatusBadRequest, APIResponse{
			Error: "invalid JSON: " + err.Error(),
		})
		return
	}

	if decoder.More() {
		writeJSON(w, http.StatusBadRequest, APIResponse{
			Error: "request body must contain only one JSON object",
		})
		return
	}

	if err := validateProduct(&p); err != nil {
		writeJSON(w, http.StatusBadRequest, APIResponse{
			Error: err.Error(),
		})
		return
	}

	log.Printf("product uploaded: name=%q price=%.2f", p.Name, p.Price)

	writeJSON(w, http.StatusOK, APIResponse{
		Message: "product uploaded successfully",
		Product: &p,
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/upload", uploadProduct)

	server := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
	}

	log.Println("server started at http://localhost:8080")
	log.Fatal(server.ListenAndServe())
}
```

关键修改点：
1. 修复了 `log.Fatal(err)` 的严重问题  
   - 原代码在请求处理中调用 `log.Fatal`，一旦出错会直接退出整个服务。  
   - 现在改为返回 HTTP 错误响应，不会导致服务崩溃。

2. 修复了请求无响应的问题  
   - 原代码即使成功读取数据，也没有给客户端返回任何响应。  
   - 现在统一返回 JSON 响应。

3. 增加了方法校验  
   - 只允许 `POST` 请求，其他方法返回 `405 Method Not Allowed`。

4. 增加了请求体大小限制  
   - 使用 `http.MaxBytesReader` 防止超大请求体导致内存问题。

5. 改进了数据解析方式  
   - 原来直接 `ReadAll` 读取原始数据，现在按 JSON 解析为 `Product` 结构体，更适合商品上传场景。

6. 增加了参数校验  
   - 校验商品名称不能为空、价格不能小于 0。

7. 增加了资源释放  
   - 使用 `defer r.Body.Close()`，避免请求体未关闭。

8. 提升了服务健壮性  
   - 增加 `ReadHeaderTimeout`，避免慢连接问题。

