package main

import (
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

const (
	uploadDir = "./uploads/configs"
	maxSize   = 5 << 20 // 5MB
)

// uploadConfigFile 将本地配置文件复制到平台指定上传目录
func uploadConfigFile(srcPath string) (string, error) {
	if strings.TrimSpace(srcPath) == "" {
		return "", errors.New("source file path is empty")
	}

	// 校验源文件
	srcInfo, err := os.Stat(srcPath)
	if err != nil {
		return "", fmt.Errorf("failed to stat source file: %w", err)
	}
	if srcInfo.IsDir() {
		return "", errors.New("source path is a directory, not a file")
	}
	if srcInfo.Size() > maxSize {
		return "", fmt.Errorf("file too large: %d bytes, max allowed is %d bytes", srcInfo.Size(), maxSize)
	}

	// 仅允许常见配置文件扩展名
	ext := strings.ToLower(filepath.Ext(srcInfo.Name()))
	allowedExt := map[string]bool{
		".json": true,
		".yaml": true,
		".yml":  true,
		".toml": true,
		".ini":  true,
		".conf": true,
		".txt":  true,
	}
	if !allowedExt[ext] {
		return "", fmt.Errorf("unsupported file type: %s", ext)
	}

	// 创建上传目录
	if err := os.MkdirAll(uploadDir, 0o755); err != nil {
		return "", fmt.Errorf("failed to create upload directory: %w", err)
	}

	// 防止路径穿越，仅保留文件名
	dstName := filepath.Base(srcInfo.Name())
	dstPath := filepath.Join(uploadDir, dstName)

	srcFile, err := os.Open(srcPath)
	if err != nil {
		return "", fmt.Errorf("failed to open source file: %w", err)
	}
	defer srcFile.Close()

	dstFile, err := os.Create(dstPath)
	if err != nil {
		return "", fmt.Errorf("failed to create destination file: %w", err)
	}
	defer dstFile.Close()

	written, err := io.Copy(dstFile, srcFile)
	if err != nil {
		return "", fmt.Errorf("failed to copy file: %w", err)
	}

	if written != srcInfo.Size() {
		return "", fmt.Errorf("incomplete copy: written %d, expected %d", written, srcInfo.Size())
	}

	return dstPath, nil
}

func main() {
	// 示例：先创建一个测试配置文件
	testFile := "app.conf"
	content := "car_platform=true\nupload_enabled=true\n"

	if err := os.WriteFile(testFile, []byte(content), 0o644); err != nil {
		fmt.Println("Error creating test config file:", err)
		return
	}

	uploadedPath, err := uploadConfigFile(testFile)
	if err != nil {
		fmt.Println("Upload failed:", err)
		return
	}

	fmt.Println("Upload succeeded:", uploadedPath)
}
```

