2. `getListing(id int) Listing` 在找不到房源时返回 `Listing{}`，调用方无法明确区分“没找到”还是“刚好是空值对象”

另外还有一些可优化点：

- 没有做重复 ID 校验，可能插入重复房源
- 全局切片直接暴露式使用，后续不利于维护
- 查询效率是线性遍历，数据量大时性能一般

下面给你一版**可直接运行的优化后代码**，修复了 bug，并做了更合理的设计：

```go
package main

import (
	"errors"
	"fmt"
)

type Listing struct {
	ID       int
	Name     string
	Location string
	Price    float64
}

type ListingStore struct {
	data map[int]Listing
}

func NewListingStore() *ListingStore {
	return &ListingStore{
		data: make(map[int]Listing),
	}
}

func (s *ListingStore) AddListing(listing Listing) error {
	if listing.ID <= 0 {
		return errors.New("listing ID must be greater than 0")
	}
	if listing.Name == "" {
		return errors.New("listing name cannot be empty")
	}
	if listing.Location == "" {
		return errors.New("listing location cannot be empty")
	}
	if listing.Price < 0 {
		return errors.New("listing price cannot be negative")
	}
	if _, exists := s.data[listing.ID]; exists {
		return fmt.Errorf("listing with ID %d already exists", listing.ID)
	}

	s.data[listing.ID] = listing
	return nil
}

func (s *ListingStore) GetListing(id int) (Listing, bool) {
	listing, exists := s.data[id]
	return listing, exists
}

func main() {
	store := NewListingStore()

	listing1 := Listing{
		ID:       1,
		Name:     "Cozy Apartment",
		Location: "New York",
		Price:    120.5,
	}
	if err := store.AddListing(listing1); err != nil {
		fmt.Println("add listing1 failed:", err)
		return
	}

	listing2 := Listing{
		ID:       2,
		Name:     "Beach House",
		Location: "Miami",
		Price:    250.0,
	}
	if err := store.AddListing(listing2); err != nil {
		fmt.Println("add listing2 failed:", err)
		return
	}

	if result, ok := store.GetListing(3); ok {
		fmt.Printf("Found listing: %+v\n", result)
	} else {
		fmt.Println("Listing with ID 3 not found")
	}

	if result, ok := store.GetListing(2); ok {
		fmt.Printf("Found listing: %+v\n", result)
	} else {
		fmt.Println("Listing with ID 2 not found")
	}
}
```

### 关键修改点
- **修复未使用变量 bug**：把查询结果打印出来，避免编译失败
- **优化查询返回值**：`GetListing` 改为返回 `(Listing, bool)`，明确表示是否找到
- **增加数据校验**：防止空名称、空地址、负价格、非法 ID
- **防止重复 ID**：新增房源时检查是否已存在
- **用 `map[int]Listing` 替代切片**：按 ID 查询从 O(n) 优化到 O(1)
- **封装存储结构**：用 `ListingStore` 管理房源，便于后续扩展

