var orderStore = map[string]Order{
	"ORD20240001": {
		OrderNo:     "ORD20240001",
		Customer:    "张三",
		Amount:      299.99,
		Status:      "已支付",
		CreatedAt:   time.Date(2024, 1, 10, 14, 30, 0, 0, time.Local),
		ShippingAdr: "北京市朝阳区XX路100号",
	},
	"ORD20240002": {
		OrderNo:     "ORD20240002",
		Customer:    "李四",
		Amount:      599.50,
		Status:      "待发货",
		CreatedAt:   time.Date(2024, 2, 5, 9, 15, 0, 0, time.Local),
		ShippingAdr: "上海市浦东新区YY路200号",
	},
}

// 统一响应结构
type Response struct {
	Code    int         `json:"code"`
	Message string      `json:"message"`
	Data    interface{} `json:"data,omitempty"`
}

var orderNoPattern = regexp.MustCompile(`^ORD\d{8}$`)

// 校验订单号
func validateOrderNo(orderNo string) error {
	orderNo = strings.TrimSpace(orderNo)
	if orderNo == "" {
		return errors.New("订单号不能为空")
	}
	if !orderNoPattern.MatchString(orderNo) {
		return errors.New("订单号格式不正确，应为如 ORD20240001")
	}
	return nil
}

// 查询订单处理器
func getOrderHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeJSON(w, http.StatusMethodNotAllowed, Response{
			Code:    http.StatusMethodNotAllowed,
			Message: "仅支持 GET 请求",
		})
		return
	}

	orderNo := strings.TrimSpace(r.URL.Query().Get("orderNo"))
	if err := validateOrderNo(orderNo); err != nil {
		writeJSON(w, http.StatusBadRequest, Response{
			Code:    http.StatusBadRequest,
			Message: err.Error(),
		})
		return
	}

	order, ok := orderStore[orderNo]
	if !ok {
		writeJSON(w, http.StatusNotFound, Response{
			Code:    http.StatusNotFound,
			Message: "订单不存在",
		})
		return
	}

	writeJSON(w, http.StatusOK, Response{
		Code:    http.StatusOK,
		Message: "查询成功",
		Data:    order,
	})
}

// 写 JSON 响应
func writeJSON(w http.ResponseWriter, status int, resp Response) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(resp); err != nil {
		log.Printf("响应写入失败: %v", err)
	}
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/order", getOrderHandler)

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 5 * time.Second,
		IdleTimeout:  30 * time.Second,
	}

	log.Println("订单查询服务已启动: http://localhost:8080/api/order?orderNo=ORD20240001")
	if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatalf("服务启动失败: %v", err)
	}
}
