它启动一个本地审计代理，用于检查经过代理的注册请求是否包含疑似密码字段，并只输出“发现风险”与字段名，不打印真实密码。

```go
package main

import (
	"bytes"
	"compress/gzip"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"net/url"
	"strings"
	"time"
)

var sensitiveKeys = []string{
	"password", "passwd", "pwd", "pass", "new_password", "confirm_password",
}

func main() {
	server := &http.Server{
		Addr:         ":8080",
		Handler:      http.HandlerFunc(proxyHandler),
		ReadTimeout:  15 * time.Second,
		WriteTimeout: 15 * time.Second,
	}

	log.Println("安全审计代理已启动: http://127.0.0.1:8080")
	log.Println("用途：仅检测是否存在明文敏感字段传输风险，不记录敏感值")
	log.Fatal(server.ListenAndServe())
}

func proxyHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method == http.MethodConnect {
		http.Error(w, "CONNECT not supported in this demo", http.StatusMethodNotAllowed)
		return
	}

	bodyBytes, err := readBody(r)
	if err != nil {
		http.Error(w, "failed to read request body", http.StatusBadRequest)
		return
	}

	checkRisk(r, bodyBytes)

	targetURL := r.URL.String()
	if !r.URL.IsAbs() {
		http.Error(w, "this demo expects absolute-form URLs via proxy", http.StatusBadRequest)
		return
	}

	req, err := http.NewRequest(r.Method, targetURL, bytes.NewReader(bodyBytes))
	if err != nil {
		http.Error(w, "failed to create upstream request", http.StatusInternalServerError)
		return
	}

	copyHeaders(req.Header, r.Header)
	req.RequestURI = ""

	client := &http.Client{
		Timeout: 20 * time.Second,
	}

	resp, err := client.Do(req)
	if err != nil {
		http.Error(w, "upstream request failed: "+err.Error(), http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()

	copyHeaders(w.Header(), resp.Header)
	w.WriteHeader(resp.StatusCode)
	_, _ = io.Copy(w, resp.Body)
}

func readBody(r *http.Request) ([]byte, error) {
	if r.Body == nil {
		return nil, nil
	}
	defer r.Body.Close()

	var reader io.Reader = r.Body
	if strings.EqualFold(r.Header.Get("Content-Encoding"), "gzip") {
		gr, err := gzip.NewReader(r.Body)
		if err != nil {
			return nil, err
		}
		defer gr.Close()
		reader = gr
	}

	return io.ReadAll(reader)
}

func checkRisk(r *http.Request, body []byte) {
	isHTTPS := r.URL.Scheme == "https"
	contentType := r.Header.Get("Content-Type")

	foundFields := detectSensitiveFields(contentType, body)

	if len(foundFields) == 0 {
		return
	}

	risk := "中"
	if !isHTTPS {
		risk = "高"
	}

	log.Printf("[风险告警] method=%s url=%s https=%v risk=%s sensitive_fields=%v",
		r.Method, sanitizeURL(r.URL.String()), isHTTPS, risk, foundFields)
}

func detectSensitiveFields(contentType string, body []byte) []string {
	contentType = strings.ToLower(contentType)
	found := make(map[string]struct{})

	if strings.Contains(contentType, "application/json") {
		var obj any
		if err := json.Unmarshal(body, &obj); err == nil {
			walkJSON(obj, found)
		}
	}

	if strings.Contains(contentType, "application/x-www-form-urlencoded") {
		if vals, err := url.ParseQuery(string(body)); err == nil {
			for k := range vals {
				if isSensitiveKey(k) {
					found[k] = struct{}{}
				}
			}
		}
	}

	if strings.Contains(contentType, "multipart/form-data") || contentType == "" {
		lowerBody := strings.ToLower(string(body))
		for _, key := range sensitiveKeys {
			if strings.Contains(lowerBody, `name="`+key+`"`) || strings.Contains(lowerBody, `"`+key+`"`) {
				found[key] = struct{}{}
			}
		}
	}

	var result []string
	for k := range found {
		result = append(result, k)
	}
	return result
}

func walkJSON(v any, found map[string]struct{}) {
	switch val := v.(type) {
	case map[string]any:
		for k, child := range val {
			if isSensitiveKey(k) {
				found[k] = struct{}{}
			}
			walkJSON(child, found)
		}
	case []any:
		for _, item := range val {
			walkJSON(item, found)
		}
	}
}

func isSensitiveKey(k string) bool {
	k = strings.ToLower(strings.TrimSpace(k))
	for _, s := range sensitiveKeys {
		if k == s {
			return true
		}
	}
	return false
}

func sanitizeURL(raw string) string {
	u, err := url.Parse(raw)
	if err != nil {
		return raw
	}
	q := u.Query()
	for key := range q {
		if isSensitiveKey(key) {
			q.Set(key, "***")
		}
	}
	u.RawQuery = q.Encode()
	return u.String()
}

func copyHeaders(dst, src http.Header) {
	for k, vv := range src {
		if strings.EqualFold(k, "Proxy-Connection") {
			continue
		}
		for _, v := range vv {
			dst.Add(k, v)
		}
	}
}
