```go
package main

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"time"
)

const (
	requestTimeout = 8 * time.Second
	maxBodySize    = 2 << 20 // 2MB，防止响应体过大
)

func fetchProductData(url string) ([]byte, error) {
	// 使用带超时的 context，避免请求长时间挂起
	ctx, cancel := context.WithTimeout(context.Background(), requestTimeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, fmt.Errorf("create request failed: %w", err)
	}

	client := &http.Client{
		Timeout: requestTimeout, // 双重保障：客户端整体超时
	}

	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("request failed: %w", err)
	}
	defer resp.Body.Close()

	// 检查 HTTP 状态码，避免把错误页面当正常数据处理
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	// 限制读取大小，避免内存被大响应占满
	limitedReader := io.LimitReader(resp.Body, maxBodySize)
	body, err := io.ReadAll(limitedReader)
	if err != nil {
		return nil, fmt.Errorf("read response body failed: %w", err)
	}

	return body, nil
}

func main() {
	url := "https://httpbin.org/get"

	data, err := fetchProductData(url)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	fmt.Println(string(data))
}
```

关键修改点：
1. 增加 `context.WithTimeout` 和 `http.Client.Timeout`，防止请求无限阻塞。
2. 补全了缺失的 `return body, nil`。
3. 增加 HTTP 状态码校验，避免非 200 响应被误当成功。
4. 使用 `io.ReadAll` 替代已过时的 `ioutil.ReadAll`。
5. 增加响应体大小限制，避免大包导致内存风险。

