type PageData struct {
	Reviews []string
	Error   string
}

var (
	mu      sync.RWMutex
	reviews []string
	tmpl    = template.Must(template.New("page").Parse(`
<!DOCTYPE html>
<html lang="zh-CN">
<head>
	<meta charset="UTF-8" />
	<meta name="viewport" content="width=device-width, initial-scale=1.0" />
	<title>旅游评价网站</title>
</head>
<body>
	<h1>提交旅游评价</h1>

	{{if .Error}}
	<p style="color:red;">{{.Error}}</p>
	{{end}}

	<form action="/submit" method="POST">
		<textarea name="review" rows="5" cols="60" placeholder="请输入您的旅游评价"></textarea><br><br>
		<button type="submit">提交评价</button>
	</form>

	<h2>评价列表</h2>
	<ul>
		{{range .Reviews}}
			<li>{{.}}</li>
		{{else}}
			<li>暂无评价</li>
		{{end}}
	</ul>
</body>
</html>
`))
)

func renderPage(w http.ResponseWriter, errMsg string) {
	mu.RLock()
	data := PageData{
		Reviews: append([]string(nil), reviews...),
		Error:   errMsg,
	}
	mu.RUnlock()

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	if err := tmpl.Execute(w, data); err != nil {
		http.Error(w, "页面渲染失败", http.StatusInternalServerError)
	}
}

func homeHandler(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	renderPage(w, "")
}

func submitReview(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "仅支持 POST 请求", http.StatusMethodNotAllowed)
		return
	}

	if err := r.ParseForm(); err != nil {
		http.Error(w, "请求参数解析失败", http.StatusBadRequest)
		return
	}

	review := strings.TrimSpace(r.FormValue("review"))
	if review == "" {
		renderPage(w, "评价内容不能为空")
		return
	}

	if len([]rune(review)) > 500 {
		renderPage(w, "评价内容不能超过 500 个字符")
		return
	}

	mu.Lock()
	reviews = append(reviews, review)
	mu.Unlock()

	http.Redirect(w, r, "/", http.StatusSeeOther)
}

func main() {
	http.HandleFunc("/", homeHandler)
	http.HandleFunc("/submit", submitReview)

	log.Println("服务器已启动：http://localhost:8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}
