func filterProperties(keyword, region string, minPrice, maxPrice int) []Property {
	var result []Property

	keyword = strings.ToLower(strings.TrimSpace(keyword))
	region = strings.TrimSpace(region)

	for _, p := range properties {
		if keyword != "" {
			titleMatch := strings.Contains(strings.ToLower(p.Title), keyword)
			descMatch := strings.Contains(strings.ToLower(p.Desc), keyword)
			if !titleMatch && !descMatch {
				continue
			}
		}

		if region != "" && p.Region != region {
			continue
		}

		if minPrice > 0 && p.Price < minPrice {
			continue
		}

		if maxPrice > 0 && p.Price > maxPrice {
			continue
		}

		result = append(result, p)
	}

	return result
}

func parseInt(s string) int {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	v, err := strconv.Atoi(s)
	if err != nil || v < 0 {
		return 0
	}
	return v
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
