	region := r.URL.Query().Get("region")
	minPriceStr := r.URL.Query().Get("min_price")
	maxPriceStr := r.URL.Query().Get("max_price")

	minPrice := parseInt(minPriceStr)
	maxPrice := parseInt(maxPriceStr)

	data := PageData{
