下面给出 **Go 语言版本**，并且做了**安全优化**：  
你的原始 C++ 代码直接执行用户输入的系统命令，这会带来严重的**命令注入风险**。  
在智能家居设备管理场景中，更合理的做法是：**只允许执行预定义的设备控制命令**，而不是把用户输入直接交给操作系统执行。

---

## 优化后的 Go 代码（可直接运行）

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type Device struct {
	Name  string
	State string
}

func main() {
	devices := map[string]*Device{
		"light":  {Name: "light", State: "off"},
		"fan":    {Name: "fan", State: "off"},
		"heater": {Name: "heater", State: "off"},
		"door":   {Name: "door", State: "closed"},
	}

	fmt.Println("Smart Home Device Console")
	fmt.Println("Usage:")
	fmt.Println("  <device> <command>")
	fmt.Println("Examples:")
	fmt.Println("  light on")
	fmt.Println("  fan off")
	fmt.Println("  door open")
	fmt.Println("  status")
	fmt.Println("  exit")

	scanner := bufio.NewScanner(os.Stdin)

	for {
		fmt.Print("> ")
		if !scanner.Scan() {
			break
		}

		input := strings.TrimSpace(scanner.Text())
		if input == "" {
			continue
		}

		if input == "exit" {
			fmt.Println("Bye.")
			break
		}

		if input == "status" {
			printStatus(devices)
			continue
		}

		parts := strings.Fields(input)
		if len(parts) != 2 {
			fmt.Println("Invalid input. Format: <device> <command>")
			continue
		}

		deviceName := strings.ToLower(parts[0])
		command := strings.ToLower(parts[1])

		device, exists := devices[deviceName]
		if !exists {
			fmt.Printf("Unknown device: %s\n", deviceName)
			continue
		}

		if err := executeDeviceCommand(device, command); err != nil {
			fmt.Println("Error:", err)
			continue
		}

		fmt.Printf("%s state: %s\n", device.Name, device.State)
	}

	if err := scanner.Err(); err != nil {
		fmt.Println("Input error:", err)
	}
}

func executeDeviceCommand(device *Device, command string) error {
	switch device.Name {
	case "light", "fan", "heater":
		if command != "on" && command != "off" {
			return fmt.Errorf("device %s only supports: on/off", device.Name)
		}
		device.State = command
		return nil

	case "door":
		if command == "open" {
			device.State = "open"
			return nil
		}
		if command == "close" {
			device.State = "closed"
			return nil
		}
		return fmt.Errorf("device door only supports: open/close")

	default:
		return fmt.Errorf("unsupported device: %s", device.Name)
	}
}

func printStatus(devices map[string]*Device) {
	fmt.Println("Device status:")
	for _, device := range devices {
		fmt.Printf("  %s: %s\n", device.Name, device.State)
	}
}
```

---

## 关键修改点

1. **移除了直接执行系统命令的方式**
   - 原 C++ 使用 `system(command.c_str())`
   - Go 中如果照搬成 `exec.Command(...)` 仍然存在高风险
   - 这里改成了**白名单式设备控制逻辑**

2. **增加了设备状态管理**
   - 用 `map[string]*Device` 保存设备及其状态
   - 更符合“智能家居控制台”的业务场景

3. **限制命令范围**
   - `light/fan/heater` 只允许 `on/off`
   - `door` 只允许 `open/close`
   - 防止任意输入被当作系统命令执行

4. **增加交互式控制台**
   - 支持：
     - `status` 查看所有设备状态
     - `exit` 退出程序

---

## 如果你只是想“机械地翻译”成 Go（不推荐）

如果你只是想看和原 C++ 行为接近的 Go 写法，下面是**不安全版本**，**不建议用于真实项目**：

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"os/exec"
	"runtime"
	"strings"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	fmt.Print("Enter command: ")
	command, _ := reader.ReadString('\n')
	command = strings.TrimSpace(command)

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("cmd", "/C", command)
	} else {
		cmd = exec.Command("sh", "-c", command)
	}

	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin

	if err := cmd.Run(); err != nil {
		fmt.Println("Command execution failed:", err)
	}
}
```

