func TestUploadImage_SVG(t *testing.T) {
	var body bytes.Buffer
	writer := multipart.NewWriter(&body)

	part, err := writer.CreateFormFile("image", "test.svg")
	if err != nil {
		t.Fatalf("CreateFormFile failed: %v", err)
	}

	svgContent := `<svg xmlns="http://www.w3.org/2000/svg"><circle cx="50" cy="50" r="40"/></svg>`
	if _, err := io.Copy(part, strings.NewReader(svgContent)); err != nil {
		t.Fatalf("writing svg content failed: %v", err)
	}

	if err := writer.Close(); err != nil {
		t.Fatalf("closing multipart writer failed: %v", err)
	}

	req := httptest.NewRequest(http.MethodPost, "/upload", &body)
	req.Header.Set("Content-Type", writer.FormDataContentType())

	rr := httptest.NewRecorder()
	uploadImage(rr, req)

	resp := rr.Result()
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		t.Fatalf("expected status %d, got %d", http.StatusOK, resp.StatusCode)
	}

	respBody, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("reading response body failed: %v", err)
	}

	expectedBase64 := base64.StdEncoding.EncodeToString([]byte(svgContent))
	expectedHTML := `<html><body><img src="data:image/svg+xml;base64,` + expectedBase64 + `"></body></html>`

	// 注意：你当前实现里 tmpl.Execute(w, file) 传入的是 multipart.File，
	// template 不会自动把文件内容转成 base64 字符串，因此这个断言会失败。
	// 这里保留该测试，用于暴露当前实现问题。
	if strings.TrimSpace(string(respBody)) != expectedHTML {
		t.Fatalf("unexpected response body.\nexpected: %s\ngot: %s", expectedHTML, string(respBody))
	}
}

func TestUploadImage_MissingFile(t *testing.T) {
	req := httptest.NewRequest(http.MethodPost, "/upload", nil)
	rr := httptest.NewRecorder()

	uploadImage(rr, req)

	resp := rr.Result()
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusBadRequest {
		t.Fatalf("expected status %d, got %d", http.StatusBadRequest, resp.StatusCode)
	}
}
