func TestGetUserDataAndHash(t *testing.T) {
	expectedUser := "testuser"
	expectedData := []byte(`{"user":"testuser","score":100,"level":5}`)

	// 启动一个本地测试 HTTP 服务
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/getdata" {
			http.NotFound(w, r)
			return
		}

		user := r.URL.Query().Get("user")
		if user != expectedUser {
			http.Error(w, "unexpected user", http.StatusBadRequest)
			return
		}

		w.WriteHeader(http.StatusOK)
		_, _ = w.Write(expectedData)
	}))
	defer server.Close()

	// 调用被测逻辑
	data, err := getUserDataFromBaseURL(server.URL, expectedUser)
	if err != nil {
		t.Fatalf("getUserDataFromBaseURL returned error: %v", err)
	}

	// 校验返回数据
	if string(data) != string(expectedData) {
		t.Fatalf("unexpected data: got %s, want %s", string(data), string(expectedData))
	}

	// 校验哈希
	gotHash := fmt.Sprintf("%x", sha256.Sum256(data))
	wantHash := fmt.Sprintf("%x", sha256.Sum256(expectedData))

	if gotHash != wantHash {
		t.Fatalf("unexpected hash: got %s, want %s", gotHash, wantHash)
	}
}
