            String fileName = String.format("loadtest_%s_%05d.dat", batchId, i);
            Path file = targetDir.resolve(fileName).normalize();

            ensureInsideTargetDir(targetDir, file);

            writeFile(file, currentFileSize, buffer, random);

            remainingBudget -= currentFileSize;
            System.out.println("已创建测试文件: " + file + " (" + currentFileSize + " bytes)");
        }
    }

    private static void writeFile(Path file, long fileSizeInBytes, byte[] buffer, SecureRandom random) throws IOException {
        long remaining = fileSizeInBytes;

        try (OutputStream os = Files.newOutputStream(
                file,
                EnumSet.of(StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE).toArray(new OpenOption[0]))) {

            while (remaining > 0) {
                int chunk = (int) Math.min(buffer.length, remaining);
                random.nextBytes(buffer);
                os.write(buffer, 0, chunk);
                remaining -= chunk;
            }

            os.flush();
        }
    }

    private static long calculateTestFilesSize(Path targetDir) throws IOException {
        if (!Files.exists(targetDir)) {
            return 0L;
        }

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(targetDir, "loadtest_*.dat")) {
            long total = 0L;
            for (Path path : stream) {
                if (Files.isRegularFile(path)) {
                    total += Files.size(path);
                }
            }
            return total;
        }
    }

    public static void cleanTestFiles(Path targetDir) throws IOException {
        if (!Files.exists(targetDir)) {
            return;
        }

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(targetDir, "loadtest_*.dat")) {
            for (Path path : stream) {
                ensureInsideTargetDir(targetDir, path);
                Files.deleteIfExists(path);
                System.out.println("已删除测试文件: " + path);
            }
        }
    }

    private static void validateArguments(Path targetDir, int numFilesToCreate, long fileSizeInBytes, long maxTotalBytes) {
        if (targetDir == null) {
            throw new IllegalArgumentException("targetDir 不能为空");
        }
        if (numFilesToCreate <= 0) {
            throw new IllegalArgumentException("numFilesToCreate 必须大于 0");
        }
        if (fileSizeInBytes <= 0) {
            throw new IllegalArgumentException("fileSizeInBytes 必须大于 0");
        }
        if (maxTotalBytes <= 0) {
            throw new IllegalArgumentException("maxTotalBytes 必须大于 0");
        }
        if (fileSizeInBytes > maxTotalBytes) {
            throw new IllegalArgumentException("单文件大小不能大于最大总空间限制");
        }
    }

    private static void ensureInsideTargetDir(Path targetDir, Path file) {
        Path normalizedTarget = targetDir.toAbsolutePath().normalize();
        Path normalizedFile = file.toAbsolutePath().normalize();

        if (!normalizedFile.startsWith(normalizedTarget)) {
            throw new SecurityException("检测到越界路径访问: " + normalizedFile);
        }
    }
}
