```java
package com.example.demo;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.concurrent.ThreadLocalRandom;
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.*;

@WebServlet("/headline_generator")
public class HeadlineGeneratorServlet extends HttpServlet {

    private static final List<String> HEADLINE_TEMPLATES = List.of(
        "关注：[主题] 的最新进展与背景解析",
        "解读：[主题] 可能带来的影响",
        "观察：[主题] 为何引发广泛讨论",
        "盘点：[主题] 的几个关键事实",
        "分析：[主题] 背后的原因与趋势"
    );

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        request.setCharacterEncoding(StandardCharsets.UTF_8.name());
        response.setCharacterEncoding(StandardCharsets.UTF_8.name());
        response.setContentType("application/json; charset=UTF-8");

        String topic = trimToEmpty(request.getParameter("topic"));

        if (topic.isEmpty()) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            response.getWriter().write("{\"error\":\"参数 topic 不能为空\"}");
            return;
        }

        String headline = generateHeadline(topic);

        String json = "{\"topic\":\"" + escapeJson(topic) + "\","
                + "\"headline\":\"" + escapeJson(headline) + "\","
                + "\"notice\":\"该内容为示例标题生成，不代表事实陈述\"}";

        response.setStatus(HttpServletResponse.SC_OK);
        response.getWriter().write(json);
    }

    private String generateHeadline(String topic) {
        int index = ThreadLocalRandom.current().nextInt(HEADLINE_TEMPLATES.size());
        String template = HEADLINE_TEMPLATES.get(index);
        return template.replace("[主题]", topic);
    }

    private String trimToEmpty(String value) {
        return value == null ? "" : value.trim();
    }

    private String escapeJson(String value) {
        if (value == null) {
            return "";
        }
        return value
                .replace("\\", "\\\\")
                .replace("\"", "\\\"")
                .replace("\b", "\\b")
                .replace("\f", "\\f")
                .replace("\n", "\\n")
                .replace("\r", "\\r")
                .replace("\t", "\\t");
    }
}
