import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Scanner;

class InsufficientBalanceException extends Exception {
    public InsufficientBalanceException(String message) {
        super(message);
    }
}

class InvalidAmountException extends Exception {
    public InvalidAmountException(String message) {
        super(message);
    }
}

class Account {
    private BigDecimal balance;

    public Account(BigDecimal balance) {
        if (balance == null || balance.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("账户初始余额非法");
        }
        this.balance = balance.setScale(2, RoundingMode.HALF_UP);
    }

    public synchronized BigDecimal getBalance() {
        return balance;
    }

    public synchronized void withdraw(BigDecimal amount)
            throws InsufficientBalanceException, InvalidAmountException {
        validateAmount(amount);

        if (amount.compareTo(balance) > 0) {
            throw new InsufficientBalanceException("余额不足");
        }

        balance = balance.subtract(amount).setScale(2, RoundingMode.HALF_UP);
    }

    private void validateAmount(BigDecimal amount) throws InvalidAmountException {
        if (amount == null) {
            throw new InvalidAmountException("金额不能为空");
        }
        if (amount.scale() > 2) {
            throw new InvalidAmountException("金额最多支持两位小数");
        }
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new InvalidAmountException("取款金额必须大于0");
        }
    }
}

public class FinanceExceptionVulnerable {
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            Account account = new Account(new BigDecimal("1000.00"));

            System.out.print("请输入取款金额：");

            if (!scanner.hasNextBigDecimal()) {
                System.out.println("输入非法：请输入有效的数字金额");
                return;
            }

            BigDecimal withdrawAmount = scanner.nextBigDecimal();

            try {
                account.withdraw(withdrawAmount);
                System.out.println("取款成功，当前余额为: " + account.getBalance());
            } catch (InvalidAmountException | InsufficientBalanceException e) {
                System.out.println("交易失败：" + e.getMessage());
            }
        } catch (Exception e) {
            System.out.println("系统异常，请稍后重试");
        }
    }
}
