import com.sun.net.httpserver.Headers;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.Executors;

public class SecureCommandServer {

    private static final int PORT = 8080;

    // 仅允许固定动作，禁止任意命令执行
    private static final Set<String> ALLOWED_ACTIONS = Set.of(
            "listFiles",
            "healthCheck",
            "version"
    );

    public static void main(String[] args) throws IOException {
        HttpServer server = HttpServer.create(new InetSocketAddress(PORT), 0);
        server.createContext("/execute_command", SecureCommandServer::handleExecuteCommand);
        server.setExecutor(Executors.newFixedThreadPool(10));
        server.start();
        System.out.println("Secure server started on port " + PORT);
    }

    private static void handleExecuteCommand(HttpExchange exchange) throws IOException {
        try {
            if (!"POST".equalsIgnoreCase(exchange.getRequestMethod())) {
                sendResponse(exchange, 405, "Method Not Allowed");
                return;
            }

            Headers headers = exchange.getRequestHeaders();
            String contentType = headers.getFirst("Content-Type");
            if (contentType == null || !contentType.contains("application/x-www-form-urlencoded")) {
                sendResponse(exchange, 400, "Invalid Content-Type");
                return;
            }

            String body = readRequestBody(exchange.getRequestBody());
            Map<String, String> params = parseForm(body);

            String action = params.get("action");
            if (action == null || action.isBlank()) {
                sendResponse(exchange, 400, "Missing action parameter");
                return;
            }

            if (!ALLOWED_ACTIONS.contains(action)) {
                sendResponse(exchange, 403, "Action not allowed");
                return;
            }

            String result = executeSafeAction(action);
            sendResponse(exchange, 200, result);

        } catch (Exception e) {
            sendResponse(exchange, 500, "Internal Server Error");
        } finally {
            exchange.close();
        }
    }

    private static String executeSafeAction(String action) {
        // 用固定逻辑替代“执行任意系统命令”
        switch (action) {
            case "listFiles":
                return "file1.log\nfile2.conf\napp.jar";
            case "healthCheck":
                return "status=UP";
            case "version":
                return "server-version=1.0.0";
            default:
                return "unsupported";
        }
    }

    private static String readRequestBody(InputStream inputStream) throws IOException {
        byte[] data = inputStream.readAllBytes();
        return new String(data, StandardCharsets.UTF_8);
    }

    private static Map<String, String> parseForm(String form) throws IOException {
        Map<String, String> map = new HashMap<>();
        if (form == null || form.isBlank()) {
            return map;
        }

        String[] pairs = form.split("&");
        for (String pair : pairs) {
            String[] kv = pair.split("=", 2);
            String key = URLDecoder.decode(kv[0], StandardCharsets.UTF_8);
            String value = kv.length > 1
                    ? URLDecoder.decode(kv[1], StandardCharsets.UTF_8)
                    : "";
            map.put(key, value);
        }
        return map;
    }

    private static void sendResponse(HttpExchange exchange, int statusCode, String response) throws IOException {
        byte[] bytes = response.getBytes(StandardCharsets.UTF_8);
        exchange.getResponseHeaders().set("Content-Type", "text/plain; charset=UTF-8");
        exchange.sendResponseHeaders(statusCode, bytes.length);
        try (OutputStream os = exchange.getResponseBody()) {
            os.write(bytes);
        }
    }
}
