import java.util.Map;
import java.util.Objects;
import java.util.concurrent.ConcurrentHashMap;

final class User {
    private final String username;
    private final String password;

    public User(String username, String password) {
        this.username = username;
        this.password = password;
    }

    public String getUsername() {
        return username;
    }

    public String getPassword() {
        return password;
    }
}

public class CRMSystem {
    /**
     * 使用小写用户名作为 key，避免遍历查询，提升登录性能
     */
    private static final Map<String, User> USERS = new ConcurrentHashMap<>();

    public static void registerUser(String username, String password) {
        validateUsername(username);
        validatePassword(password);

        String normalizedUsername = normalizeUsername(username);
        User newUser = new User(username.trim(), password);

        User existing = USERS.putIfAbsent(normalizedUsername, newUser);
        if (existing != null) {
            throw new IllegalArgumentException("用户名已存在: " + username);
        }
    }

    public static boolean loginUser(String username, String password) {
        if (username == null || password == null) {
            return false;
        }

        User user = USERS.get(normalizeUsername(username));
        return user != null && Objects.equals(user.getPassword(), password);
    }

    private static String normalizeUsername(String username) {
        return username.trim().toLowerCase();
    }

    private static void validateUsername(String username) {
        if (username == null || username.trim().isEmpty()) {
            throw new IllegalArgumentException("用户名不能为空");
        }
    }

    private static void validatePassword(String password) {
        if (password == null || password.isEmpty()) {
            throw new IllegalArgumentException("密码不能为空");
        }
    }

    public static void main(String[] args) {
        registerUser("test", "123456");

        System.out.println(loginUser(null, "123456"));     // false
        System.out.println(loginUser("test", "123456"));   // true
        System.out.println(loginUser("TEST", "123456"));   // true
        System.out.println(loginUser("test", "wrong"));    // false
    }
}
```

关键修改点：
1. 修复编译错误  
   原代码中 `users.get(randomIndex).password = null;` 直接访问 `User` 私有字段，无法编译，已移除这段危险逻辑。

2. 修复空指针风险  
   原代码 `loginUser(null, "123456")` 会在 `equalsIgnoreCase` 处触发 `NullPointerException`，现在对 `username/password` 做了空值判断。

3. 提升性能  
   原来登录需要遍历 `List`，时间复杂度是 `O(n)`；现在改为 `ConcurrentHashMap` 按用户名直接查找，时间复杂度接近 `O(1)`。

4. 增强数据安全性与一致性  
   `User` 改为不可变对象，字段使用 `final`，避免对象状态被随意修改。

5. 增加输入校验  
   注册时校验用户名和密码不能为空，并禁止重复用户名。

6. 统一用户名匹配规则  
   使用 `trim().toLowerCase()` 做标准化处理，实现大小写不敏感登录，同时避免前后空格导致的问题。

