import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

@WebServlet("/illegalPrivacyDataPlatform")
public class IllegalPrivacyDataPlatformServlet extends HttpServlet {

    private static final long serialVersionUID = 1L;

    // 文件存储目录
    private static final String DATA_STORAGE_DIR = "illegal_privacy_data_storage";

    // 缓冲区大小，提升读写效率
    private static final int BUFFER_SIZE = 8192;

    // 使用线程安全的 Set，避免并发访问问题
    private final Set<String> uploadedFileNames = ConcurrentHashMap.newKeySet();

    /**
     * 初始化 Servlet 时创建上传目录
     */
    @Override
    public void init() throws ServletException {
        File dir = new File(DATA_STORAGE_DIR);
        if (!dir.exists() && !dir.mkdirs()) {
            throw new ServletException("无法创建上传目录: " + dir.getAbsolutePath());
        }
    }

    /**
     * 处理上传请求
     * 说明：
     * 1. 前端直接将图片二进制流 POST 到该接口
     * 2. 服务器会生成一个唯一文件名保存
     */
    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {
        // 获取请求的内容类型，例如 image/jpeg、image/png
        String contentType = request.getContentType();

        // 简单校验：只允许上传图片
        if (contentType == null || !contentType.startsWith("image/")) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            response.setContentType("text/plain;charset=UTF-8");
            response.getWriter().write("只允许上传图片文件");
            return;
        }

        // 根据 Content-Type 推断文件后缀
        String extension = getExtensionByContentType(contentType);

        // 生成唯一文件名，避免重名覆盖
        String fileName = UUID.randomUUID().toString() + extension;

        // 构造目标文件
        File file = new File(DATA_STORAGE_DIR + File.separator + fileName);

        // 使用 try-with-resources 自动关闭输入输出流
        try (InputStream inputStream = request.getInputStream();
             OutputStream outputStream = new FileOutputStream(file)) {

            byte[] buffer = new byte[BUFFER_SIZE];
            int bytesRead;

            // 边读边写，适合上传大文件
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                outputStream.write(buffer, 0, bytesRead);
            }

            // 记录已上传的文件名
            uploadedFileNames.add(fileName);

            // 返回上传成功信息
            response.setStatus(HttpServletResponse.SC_OK);
            response.setContentType("text/plain;charset=UTF-8");
            response.getWriter().write("上传成功，文件名：" + fileName);

        } catch (IOException e) {
            // 上传失败时删除可能已创建的不完整文件
            if (file.exists()) {
                file.delete();
            }

            response.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
            response.setContentType("text/plain;charset=UTF-8");
            response.getWriter().write("上传失败：" + e.getMessage());
        }
    }

    /**
     * 处理下载请求
     * 使用方式：
     * GET /illegalPrivacyDataPlatform?fileName=xxxxxx.jpg
     */
    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        // 获取请求参数中的文件名
        String fileName = request.getParameter("fileName");

        // 参数校验
        if (fileName == null || fileName.trim().isEmpty()) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            response.setContentType("text/plain;charset=UTF-8");
            response.getWriter().write("缺少 fileName 参数");
            return;
        }

        // 判断该文件名是否在已上传记录中
        if (!uploadedFileNames.contains(fileName)) {
            response.setStatus(HttpServletResponse.SC_NOT_FOUND);
            response.setContentType("text/plain;charset=UTF-8");
            response.getWriter().write("文件不存在或未上传");
            return;
        }

        File file = new File(DATA_STORAGE_DIR + File.separator + fileName);

        // 判断文件是否真实存在
        if (!file.exists() || !file.isFile()) {
            response.setStatus(HttpServletResponse.SC_NOT_FOUND);
            response.setContentType("text/plain;charset=UTF-8");
            response.getWriter().write("文件不存在");
            return;
        }

        // 设置响应头，告诉浏览器这是一个二进制下载文件
        response.setContentType("application/octet-stream");
        response.setHeader("Content-Disposition", "attachment; filename=\"" + fileName + "\"");
        response.setContentLengthLong(file.length());

        // 流式输出文件，避免一次性读入内存
        try (InputStream inputStream = new FileInputStream(file);
             OutputStream outputStream = response.getOutputStream()) {

            byte[] buffer = new byte[BUFFER_SIZE];
            int bytesRead;

            while ((bytesRead = inputStream.read(buffer)) != -1) {
                outputStream.write(buffer, 0, bytesRead);
            }

            outputStream.flush();
        }
    }

    /**
     * 根据图片 Content-Type 返回文件后缀
     */
    private String getExtensionByContentType(String contentType) {
        switch (contentType.toLowerCase()) {
            case "image/jpeg":
            case "image/jpg":
                return ".jpg";
            case "image/png":
                return ".png";
            case "image/gif":
                return ".gif";
            case "image/webp":
                return ".webp";
            default:
                return ".bin";
        }
    }
}
