import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

final class SafetyInstruction {
    private final String topicName;
    private final List<String> safetyGuidelines;

    public SafetyInstruction(String topicName, List<String> safetyGuidelines) {
        this.topicName = Objects.requireNonNull(topicName, "topicName cannot be null");
        Objects.requireNonNull(safetyGuidelines, "safetyGuidelines cannot be null");

        List<String> copy = new ArrayList<>();
        for (String guideline : safetyGuidelines) {
            copy.add(Objects.requireNonNull(guideline, "guideline cannot be null"));
        }
        this.safetyGuidelines = Collections.unmodifiableList(copy);
    }

    public String getTopicName() {
        return topicName;
    }

    public List<String> getSafetyGuidelines() {
        return safetyGuidelines;
    }
}

