        explosiveRiskGuidelines.add("如在单位或学校发现异常物品，应按应急预案上报。");

        temp.add(new SafetyInstruction("疑似爆炸物安全处置", explosiveRiskGuidelines));

        List<String> chemicalSafetyGuidelines = new ArrayList<>();
        chemicalSafetyGuidelines.add("不明化学品应避免接触、混合、加热或密封保存。");
        chemicalSafetyGuidelines.add("发现泄漏时应立即通风并远离火源、电源和高温区域。");
        chemicalSafetyGuidelines.add("佩戴合适的个人防护装备，并联系专业人员处理。");
        chemicalSafetyGuidelines.add("如有人接触后不适，应立即就医并说明接触情况。");

        temp.add(new SafetyInstruction("危险化学品基础防护", chemicalSafetyGuidelines));

        this.instructions = Collections.unmodifiableList(temp);
