import java.io.InputStream;
import java.lang.management.ManagementFactory;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Base64;
import java.util.List;
import java.util.Properties;

public class DebugEnvironmentDetection {

    // 这里放“预期完整性摘要”
    // 实际使用时应在构建阶段生成并写入，而不是手工填写
    private static final String EXPECTED_CLASS_SHA256 = "";

    public static void main(String[] args) {
        SecurityCheckResult result = performSecurityChecks();

        if (!result.safe) {
            System.err.println("检测到非生产或高风险运行环境：");
            for (String msg : result.messages) {
                System.err.println(" - " + msg);
            }
            System.err.println("程序将安全退出。");
            System.exit(1);
        }

        System.out.println("运行环境检查通过。");

        // 示例：敏感配置解密使用（仅数据，不是代码）
        String encrypted = encrypt("example-secret", "demo-key");
        String decrypted = decrypt(encrypted, "demo-key");
        System.out.println("敏感配置解密结果：" + decrypted);
    }

    public static SecurityCheckResult performSecurityChecks() {
        SecurityCheckResult result = new SecurityCheckResult();

        checkJvmArgs(result);
        checkSystemProperties(result);
        checkClassIntegrity(result);

        if (result.messages.isEmpty()) {
            result.safe = true;
        }

        return result;
    }

    private static void checkJvmArgs(SecurityCheckResult result) {
        List<String> inputArgs = ManagementFactory.getRuntimeMXBean().getInputArguments();
        for (String arg : inputArgs) {
            String lower = arg.toLowerCase();

            // 这里只做“记录风险”，不做反调试行为
            if (lower.contains("jdwp") || lower.contains("-agentlib:jdwp")) {
                result.messages.add("检测到调试相关 JVM 参数: " + arg);
            }
            if (lower.contains("-javaagent")) {
                result.messages.add("检测到 Java Agent: " + arg);
            }
            if (lower.contains("-xdebug")) {
                result.messages.add("检测到调试参数: " + arg);
            }
        }
    }

    private static void checkSystemProperties(SecurityCheckResult result) {
        String env = System.getProperty("app.env", "prod");
        if (!"prod".equalsIgnoreCase(env)) {
            result.messages.add("当前不是生产环境，app.env=" + env);
        }

        String profile = System.getProperty("spring.profiles.active", "");
        if (!profile.isEmpty() && !"prod".equalsIgnoreCase(profile)) {
            result.messages.add("检测到非生产 profile: " + profile);
        }
    }

    private static void checkClassIntegrity(SecurityCheckResult result) {
        try {
            String classFile = "/" + DebugEnvironmentDetection.class.getName().replace('.', '/') + ".class";
            try (InputStream in = DebugEnvironmentDetection.class.getResourceAsStream(classFile)) {
                if (in == null) {
                    result.messages.add("无法读取类文件进行完整性校验");
                    return;
                }

                byte[] bytes = in.readAllBytes();
                String sha256 = sha256(bytes);

                if (EXPECTED_CLASS_SHA256 == null || EXPECTED_CLASS_SHA256.isEmpty()) {
                    result.messages.add("未配置 EXPECTED_CLASS_SHA256，无法完成完整性校验。当前摘要: " + sha256);
                    return;
                }

                if (!EXPECTED_CLASS_SHA256.equalsIgnoreCase(sha256)) {
                    result.messages.add("类文件完整性校验失败，摘要不匹配");
                }
            }
        } catch (Exception e) {
            result.messages.add("完整性校验异常: " + e.getMessage());
        }
    }

    private static String sha256(byte[] data) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hash = digest.digest(data);
        StringBuilder sb = new StringBuilder();
        for (byte b : hash) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    // 仅用于“敏感数据存储”的简单示例，不用于代码动态解密执行
    public static String encrypt(String plainText, String key) {
        byte[] data = plainText.getBytes(StandardCharsets.UTF_8);
        byte[] keyBytes = key.getBytes(StandardCharsets.UTF_8);
        byte[] out = new byte[data.length];

        for (int i = 0; i < data.length; i++) {
            out[i] = (byte) (data[i] ^ keyBytes[i % keyBytes.length]);
        }

        return Base64.getEncoder().encodeToString(out);
    }

    public static String decrypt(String cipherText, String key) {
        byte[] data = Base64.getDecoder().decode(cipherText);
        byte[] keyBytes = key.getBytes(StandardCharsets.UTF_8);
        byte[] out = new byte[data.length];

        for (int i = 0; i < data.length; i++) {
            out[i] = (byte) (data[i] ^ keyBytes[i % keyBytes.length]);
        }

        return new String(out, StandardCharsets.UTF_8);
    }

