```java
import java.io.IOException;
import java.io.RandomAccessFile;
import java.io.UncheckedIOException;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.LocalDateTime;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

public class SafeDbFileInspector {

    private static final Set<String> MYSQL_EXTENSIONS = Set.of(".frm", ".ibd", ".myd", ".myi");
    private static final int DEFAULT_SIMULATE_BYTES = 64;

    public static void main(String[] args) {
        Path root = Paths.get(args.length > 0 ? args[0] : ".");
        Path sandbox = Paths.get(args.length > 1 ? args[1] : "./sandbox");

        try {
            List<Path> dbFiles = searchForDbFiles(root);
            log("INFO", "Found " + dbFiles.size() + " candidate database files.");

            for (Path file : dbFiles) {
                String sha256 = sha256(file);
                log("INFO", "File: " + file.toAbsolutePath() + " | SHA-256: " + sha256);

                Path copied = copyToSandbox(file, root, sandbox);
                log("INFO", "Copied to sandbox: " + copied.toAbsolutePath());

                simulateByteFlipOnCopy(copied, DEFAULT_SIMULATE_BYTES);
                log("INFO", "Simulated non-destructive mutation on sandbox copy: " + copied.toAbsolutePath());
            }

            log("INFO", "Completed safely.");
        } catch (Exception e) {
            log("ERROR", "Execution failed: " + e.getMessage());
            e.printStackTrace();
        }
    }

    public static List<Path> searchForDbFiles(Path rootPath) throws IOException {
        List<Path> dbFiles = new ArrayList<>();

        Files.walkFileTree(rootPath, new SimpleFileVisitor<>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                String name = file.getFileName().toString().toLowerCase(Locale.ROOT);
                for (String ext : MYSQL_EXTENSIONS) {
                    if (name.endsWith(ext)) {
                        dbFiles.add(file);
                        break;
                    }
                }
                return FileVisitResult.CONTINUE;
            }
        });

        return dbFiles;
    }

    public static Path copyToSandbox(Path sourceFile, Path rootPath, Path sandboxRoot) throws IOException {
        Path relative;
        try {
            relative = rootPath.toAbsolutePath().normalize().relativize(sourceFile.toAbsolutePath().normalize());
        } catch (IllegalArgumentException e) {
            relative = sourceFile.getFileName();
        }

        Path target = sandboxRoot.resolve(relative);
        Files.createDirectories(target.getParent());
        Files.copy(sourceFile, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.COPY_ATTRIBUTES);
        return target;
    }

    public static void simulateByteFlipOnCopy(Path file, int modifyLength) throws IOException {
        long fileSize = Files.size(file);
        if (fileSize == 0) {
            log("WARN", "Skip empty file: " + file);
            return;
        }

        int actualLength = (int) Math.min(modifyLength, fileSize);
        long maxStart = fileSize - actualLength;
        long startPos = ThreadLocalRandom.current().nextLong(maxStart + 1);

        byte[] buffer = new byte[actualLength];
        ThreadLocalRandom.current().nextBytes(buffer);

        try (RandomAccessFile raf = new RandomAccessFile(file.toFile(), "rw")) {
            raf.seek(startPos);
            raf.write(buffer);
        }
    }

    public static String sha256(Path file) throws IOException {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] data = Files.readAllBytes(file);
            byte[] hash = digest.digest(data);
            return toHex(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    private static String toHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static void log(String level, String message) {
        System.out.printf("%s [%s] %s%n", LocalDateTime.now(), level, message);
    }
}
