## 一个安全的“风险演示”示例
下面这个示例只演示：**如果错误开启多态反序列化，攻击者可能控制实例化的类型**。  
它不会执行系统命令，也不会包含任何攻击利用链。

### 可运行示例代码
```java
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.jsontype.BasicPolymorphicTypeValidator;

public class JacksonSafeDemo {

    public static class SafeMessage {
        public String message;

        public SafeMessage() {
            System.out.println("SafeMessage instantiated");
        }

        @Override
        public String toString() {
            return "SafeMessage{message='" + message + "'}";
        }
    }

    public static class UnexpectedType {
        public String data;

        public UnexpectedType() {
            System.out.println("UnexpectedType instantiated");
        }

        @Override
        public String toString() {
            return "UnexpectedType{data='" + data + "'}";
        }
    }

    public static void main(String[] args) throws Exception {
        unsafeDemo();
        System.out.println("--------------------------------------------------");
        safeDemo();
    }

    private static void unsafeDemo() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

        // 仅用于风险演示：允许当前包下所有类型参与多态反序列化
        BasicPolymorphicTypeValidator ptv = BasicPolymorphicTypeValidator.builder()
                .allowIfSubType(JacksonSafeDemo.class.getPackageName() == null ? "" : JacksonSafeDemo.class.getPackageName())
                .allowIfSubType(JacksonSafeDemo.class.getName())
                .build();

        mapper.activateDefaultTyping(ptv, ObjectMapper.DefaultTyping.NON_FINAL, JsonTypeInfo.As.PROPERTY);

        String json = "{"
                + "\"@class\":\"" + UnexpectedType.class.getName() + "\","
                + "\"data\":\"controlled by input\""
                + "}";

        Object obj = mapper.readValue(json, Object.class);
        System.out.println("[unsafeDemo] deserialized type = " + obj.getClass().getName());
        System.out.println("[unsafeDemo] object = " + obj);
    }

    private static void safeDemo() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

        // 安全方式：不要对 Object 开启宽泛默认类型
        String json = "{\"message\":\"hello\"}";
        SafeMessage msg = mapper.readValue(json, SafeMessage.class);

        System.out.println("[safeDemo] deserialized type = " + msg.getClass().getName());
        System.out.println("[safeDemo] object = " + msg);
    }
}
```

