import sqlite3
from contextlib import closing
from typing import Any, Dict, Optional, Tuple


DB_PATH = "restaurant_db.db"


class OrderServiceError(Exception):
    """业务异常基类"""


class OrderNotFoundError(OrderServiceError):
    """订单不存在异常"""


class DatabaseExecutionError(OrderServiceError):
    """数据库执行异常"""


def get_connection(db_path: str = DB_PATH) -> sqlite3.Connection:
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    return conn


def execute_query(
    query: str,
    params: Tuple[Any, ...] = (),
    db_path: str = DB_PATH,
    fetchone: bool = False
) -> Optional[Any]:
    try:
        with closing(get_connection(db_path)) as conn:
            with closing(conn.cursor()) as cursor:
                cursor.execute(query, params)
                return cursor.fetchone() if fetchone else cursor.fetchall()
    except sqlite3.Error as e:
        raise DatabaseExecutionError(f"数据库执行失败: {e}") from e


def get_order_by_id(order_id: int, db_path: str = DB_PATH) -> Dict[str, Any]:
    if not isinstance(order_id, int):
        raise ValueError("order_id 必须是整数")

    query = """
        SELECT *
        FROM orders
        WHERE order_id = ?;
    """
    row = execute_query(query, (order_id,), db_path=db_path, fetchone=True)

    if row is None:
        raise OrderNotFoundError(f"订单不存在: order_id={order_id}")

    return dict(row)


def process_order(order_details: Dict[str, Any], db_path: str = DB_PATH) -> Dict[str, Any]:
    if not isinstance(order_details, dict):
        raise ValueError("order_details 必须是字典")

    if "order_id" not in order_details:
        raise ValueError("order_details 缺少必要字段: order_id")

    order_id = order_details["order_id"]
    order = get_order_by_id(order_id, db_path=db_path)
    print(f"Order {order_id} found: {order}")
    return order


def place_order(order_details: Dict[str, Any], db_path: str = DB_PATH) -> Optional[Dict[str, Any]]:
    try:
        return process_order(order_details, db_path=db_path)
    except OrderServiceError as e:
        print(f"Error placing order: {e}")
    except ValueError as e:
        print(f"参数错误: {e}")
    except Exception as e:
        print(f"未知错误: {e}")
    return None


if __name__ == "__main__":
    test_order = {"order_id": 1}
    place_order(test_order)
```

### 关键优化点
1. **修复 SQL 注入风险**  
   原来使用 f-string 拼接 SQL，改为参数化查询：`WHERE order_id = ?`。

2. **增加连接与游标的安全关闭**  
   使用 `contextlib.closing`，确保数据库连接和游标正确释放。

3. **细化异常类型**  
   自定义了 `OrderNotFoundError`、`DatabaseExecutionError`，便于区分业务错误和数据库错误。

4. **增加输入校验**  
   校验 `order_details` 是否为字典、是否包含 `order_id`、`order_id` 是否为整数。

5. **提升结果可读性**  
   设置 `row_factory = sqlite3.Row`，返回结果可直接转成字典，便于后续处理。

6. **增强可维护性**  
   将查询订单逻辑拆分为 `get_order_by_id`，职责更清晰，后续扩展更方便。  

