```sql
-- 适用：MySQL 8.x
-- 说明：
-- 1) 原代码把“写入数据”放在 FUNCTION 里，这在 MySQL 中不适合，建议改为 PROCEDURE
-- 2) 增加主外键、非空、时间默认值、索引，避免脏数据
-- 3) 增加参数校验：学员/动态是否存在、评论内容是否为空
-- 4) 增加异常处理，避免插入失败时无提示
-- 5) 修复变量名与字段名同名导致的歧义问题

DROP TABLE IF EXISTS comments;
DROP TABLE IF EXISTS fitness_posts;
DROP TABLE IF EXISTS students;

CREATE TABLE students (
    student_id INT PRIMARY KEY,
    student_name VARCHAR(100) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE fitness_posts (
    post_id INT PRIMARY KEY,
    student_id INT NOT NULL,
    post_content TEXT NOT NULL,
    post_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_fitness_posts_student
        FOREIGN KEY (student_id) REFERENCES students(student_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE comments (
    comment_id INT AUTO_INCREMENT PRIMARY KEY,
    student_id INT NOT NULL,
    post_id INT NOT NULL,
    comment_text TEXT NOT NULL,
    comment_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_comments_student
        FOREIGN KEY (student_id) REFERENCES students(student_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE,
    CONSTRAINT fk_comments_post
        FOREIGN KEY (post_id) REFERENCES fitness_posts(post_id)
        ON DELETE CASCADE
        ON UPDATE CASCADE,
    INDEX idx_comments_post_id (post_id),
    INDEX idx_comments_student_id (student_id),
    INDEX idx_comments_comment_date (comment_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 示例数据
INSERT INTO students (student_id, student_name) VALUES
(201, '小李'),
(202, '小王');

INSERT INTO fitness_posts (post_id, student_id, post_content, post_date) VALUES
(301, 201, '今天完成了核心训练和拉伸，感觉状态不错！', NOW()),
(302, 202, '这周开始增肌训练，记录一下饮食和动作安排。', NOW());

DROP PROCEDURE IF EXISTS submitComment;
DELIMITER $$

CREATE PROCEDURE submitComment (
    IN p_student_id INT,
    IN p_post_id INT,
    IN p_comment_text TEXT
)
BEGIN
    DECLARE v_result VARCHAR(500);
    DECLARE v_student_name VARCHAR(100);
    DECLARE v_post_content TEXT;
    DECLARE v_comment_id INT;
    DECLARE v_post_exists INT DEFAULT 0;
    DECLARE v_student_exists INT DEFAULT 0;

    -- 异常处理
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = '评论提交失败：数据库执行异常';
    END;

    START TRANSACTION;

    -- 参数清洗
    SET p_comment_text = TRIM(p_comment_text);

    -- 参数校验
    IF p_student_id IS NULL OR p_post_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = '评论提交失败：student_id 和 post_id 不能为空';
    END IF;

    IF p_comment_text IS NULL OR CHAR_LENGTH(p_comment_text) = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = '评论提交失败：评论内容不能为空';
    END IF;

    -- 可选：限制评论长度
    IF CHAR_LENGTH(p_comment_text) > 1000 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = '评论提交失败：评论内容不能超过 1000 个字符';
    END IF;

    -- 检查学员是否存在
    SELECT COUNT(*)
      INTO v_student_exists
      FROM students s
     WHERE s.student_id = p_student_id;

    IF v_student_exists = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = '评论提交失败：学员不存在';
    END IF;

    -- 检查动态是否存在
    SELECT COUNT(*)
      INTO v_post_exists
      FROM fitness_posts fp
     WHERE fp.post_id = p_post_id;

    IF v_post_exists = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = '评论提交失败：动态不存在';
    END IF;

    -- 插入评论
    INSERT INTO comments (student_id, post_id, comment_text, comment_date)
    VALUES (p_student_id, p_post_id, p_comment_text, NOW());

    SET v_comment_id = LAST_INSERT_ID();

    -- 查询展示信息
    SELECT s.student_name
      INTO v_student_name
      FROM students s
     WHERE s.student_id = p_student_id;

    SELECT fp.post_content
      INTO v_post_content
      FROM fitness_posts fp
     WHERE fp.post_id = p_post_id;

    COMMIT;

    SET v_result = CONCAT(
        '评论提交成功：评论ID=', v_comment_id,
        '；学员“', v_student_name,
        '” 发表评论：“', p_comment_text,
        '” 于动态：“', LEFT(v_post_content, 100), '”'
    );

    SELECT v_result AS message, v_comment_id AS comment_id;
END$$

DELIMITER ;

-- 调用示例
CALL submitComment(201, 301, '这节健身课真的很有效果呀！');

-- 查看结果
SELECT * FROM comments;
```

关键修改点：
1. **把 FUNCTION 改成 PROCEDURE**：MySQL 中函数不适合做插入这类有副作用的操作，存储过程更合理。
2. **补齐约束**：给 `comments` 和 `fitness_posts` 增加外键、`NOT NULL`、索引，保证数据一致性和查询性能。
3. **增加校验逻辑**：评论内容去空格后不能为空，学员和动态必须存在。
4. **增加事务和异常处理**：插入失败时自动回滚，并返回明确错误信息。
5. **修复命名歧义**：原来 `student_name`、`post_content` 既是变量名又是字段名，容易出错，现改为 `v_` 前缀变量。

